INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23206, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西出来。", "primary_collocate": null, "pronunciation": "fàng chū", "ipa": "faŋ˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "小女孩把盒子里的蝴蝶放出来了。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课了，老师把孩子们放出来玩。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里烟太多，我打开窗户，把烟放出去。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把关在房间里的猫放出来。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把关在地下室里的老鼠放出来了。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烤箱一打开，里面的热气就放出来了。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把气球里的气放出了一点。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他解开绳子，把绑着的小狗放出来了。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把被困在树洞里的小松鼠放出来了。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打开笼子，把仓鼠放出来玩一会儿。", "target_word": "放出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放出了", "label": "体标"}, {"form": "放出来", "label": "复合"}], "register": "中性", "sense_fingerprint": "打开或松开后，让里面的东西出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24849d55-0b5a-4d61-b13f-ff8d3ff3a864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23206, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放出", "is_correct": true, "explanation": "正确：“放出来”表示把关在盒子里的蝴蝶放走，与句中“盒子里”的情境相合。"}, {"text": "装进", "is_correct": false, "explanation": "搭配：“装”用于往容器里装货物，不用于活的蝴蝶，而且蝴蝶本来就在盒子里。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”用于花果、叶子等植物，不能说摘蝴蝶。"}, {"text": "关进", "is_correct": false, "explanation": "语义：蝴蝶本来就在盒子里，“关进”说的是再把它关进去，与句意的状况相矛盾。"}], "explanations": {"放出": "正确：“放出来”表示把关在盒子里的蝴蝶放走，与句中“盒子里”的情境相合。", "装进": "搭配：“装”用于往容器里装货物，不用于活的蝴蝶，而且蝴蝶本来就在盒子里。", "摘": "搭配：“摘”用于花果、叶子等植物，不能说摘蝴蝶。", "关进": "语义：蝴蝶本来就在盒子里，“关进”说的是再把它关进去，与句意的状况相矛盾。"}, "sentence_index": 0, "correct_answer": "放出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从包里放出了一本书。", "explanation": "这里应该用〈拿出〉。放出指把关着或被困的东西放走，从包里拿东西要用拿出。"}, {"text": "小猫从门缝里放出了头。", "explanation": "这里应该用〈探出〉。放出指释放被关住的东西，把头伸出去要用探出。"}, {"text": "他把桌上的水杯放出来喝水。", "explanation": "这里应该用〈拿起〉。放出指把关着或被困的东西放走，水杯并没有被关住，应用拿起。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23206, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放出", "is_correct": true, "explanation": "正确：“放出了一点”表示气球里的气被放掉一些，与句意相合。"}, {"text": "放下", "is_correct": false, "explanation": "搭配：“放下”的对象是可以拿起的物件，不能说放下气。"}, {"text": "收起", "is_correct": false, "explanation": "搭配：“收起”用于收拾物件，不能用于气体。"}, {"text": "充入", "is_correct": false, "explanation": "语义：“充入”是往里灌，与“气球里的气”已在球内、要放出去的情况相反。"}], "explanations": {"放出": "正确：“放出了一点”表示气球里的气被放掉一些，与句意相合。", "放下": "搭配：“放下”的对象是可以拿起的物件，不能说放下气。", "收起": "搭配：“收起”用于收拾物件，不能用于气体。", "充入": "语义：“充入”是往里灌，与“气球里的气”已在球内、要放出去的情况相反。"}, "sentence_index": 6, "correct_answer": "放出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他放出一个大哈欠。", "explanation": "这里应该用〈打〉。放出指释放被关住或被困的东西，哈欠要说打哈欠，不能说放出。"}, {"text": "妈妈在菜里放出了一勺盐。", "explanation": "这里应该用〈放入〉。放出指把关着的东西放走，往菜里加调料要用放入。"}, {"text": "他从怀里放出一张照片。", "explanation": "这里应该用〈掏出〉。放出指把被关住的东西放走，从怀里拿东西要用掏出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23206, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把那本鸟放出来了。", "corrected_sentence": "妈妈把那只鸟放出来了。", "error_description": "错误：“鸟”的量词应用“只”，“本”用于书册等，不能修饰鸟；应说“那只鸟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23206, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈打开鸟笼，把小鸟放出来了飞一会儿。", "corrected_sentence": "妈妈打开鸟笼，把小鸟放出来飞一会儿。", "error_description": "错误：“放出来了飞”；正确：“放出来飞”。“了”表示完成，接在动词后面；这里“放出来”后还要接下一个动作，“了”不能夹在“放出来”和“飞”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23208, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23208, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23208, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "我们住的大圆球，有很多很多水、树木和人。", "primary_collocate": null, "pronunciation": "dì qiú", "ipa": "ti˥˩ tɕʰjoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "地球是我们的家。", "target_word": "地球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球上有很多水和树木。", "target_word": "地球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球围着太阳转。", "target_word": "地球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要保护地球，少用塑料。", "target_word": "地球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从太空看，地球是蓝色的。", "target_word": "地球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球上的人越来越多了。", "target_word": "地球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宇航员第一次看到了远处的地球。", "target_word": "地球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球一天转一圈。", "target_word": "地球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在课本上画了一个地球。", "target_word": "地球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，地球只有一个。", "target_word": "地球", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "地球仪", "label": "复合"}, {"form": "地球村", "label": "复合"}], "register": "中性", "sense_fingerprint": "地球：人类居住的行星", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89604cde-aa36-49a3-b834-19b3606a7411') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23208, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "地球", "is_correct": true, "explanation": "正确。地球是人类居住的行星，读作 dì qiú。"}, {"text": "地区", "is_correct": false, "explanation": "qū（第一声）与 qiú（第二声）韵母与声调都不同，意思是地区，不是行星。"}, {"text": "第九", "is_correct": false, "explanation": "jiǔ（第三声）与 qiú（第二声）声母与声调都不同，意思是“第九”，与“地球”不同。"}, {"text": "皮球", "is_correct": false, "explanation": "pí（第二声）与 dì（第四声）声母与声调都不同，意思是皮球，不是行星。"}], "explanations": {"地球": "正确。地球是人类居住的行星，读作 dì qiú。", "地区": "qū（第一声）与 qiú（第二声）韵母与声调都不同，意思是地区，不是行星。", "第九": "jiǔ（第三声）与 qiú（第二声）声母与声调都不同，意思是“第九”，与“地球”不同。", "皮球": "pí（第二声）与 dì（第四声）声母与声调都不同，意思是皮球，不是行星。"}, "sentence_index": null, "correct_answer": "地球"}, "level_3": {"options": [{"text": "地球", "is_correct": true, "explanation": "正确。地球是人类居住的行星，可以说是我们的家。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是恒星，人类不能在上面居住，不能说是“我们的家”。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“是……的家”要接居住之所，“手机”是随身物品，不能这样搭配。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不是人居住的地方，不能说是“我们的家”。"}], "explanations": {"地球": "正确。地球是人类居住的行星，可以说是我们的家。", "太阳": "语义：太阳是恒星，人类不能在上面居住，不能说是“我们的家”。", "手机": "搭配：“是……的家”要接居住之所，“手机”是随身物品，不能这样搭配。", "桌子": "语义：桌子是家具，不是人居住的地方，不能说是“我们的家”。"}, "sentence_index": 0, "correct_answer": "地球"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "火星是一颗很冷的地球。", "explanation": "这里指火星，应该用〈星球〉。地球专指人类居住的这颗行星，不能用来称呼其他星球。"}, {"text": "他一脚踩空，摔在了地球旁边的草地上。", "explanation": "这里指草地的位置，应该用〈草地〉。“地球”指整个行星，不能用来定位一块草地。"}, {"text": "夜晚抬头看，地球上满是星星。", "explanation": "这里指天空，应该用〈天上〉。地球指人类居住的行星，星星在天上，不在地球上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23208, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地球", "is_correct": true, "explanation": "正确。地球是人类居住的行星，宇航员在太空中可以看到远处的地球。"}, {"text": "操场", "is_correct": false, "explanation": "语义：宇航员身处太空，看不到地面上的操场，不能说“远处的操场”。"}, {"text": "出租车", "is_correct": false, "explanation": "语义：出租车只在地面行驶，宇航员在太空中看不到它。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“远处的”修饰可以远望见的事物，冰箱是室内家具，不能说“远处的冰箱”。"}], "explanations": {"地球": "正确。地球是人类居住的行星，宇航员在太空中可以看到远处的地球。", "操场": "语义：宇航员身处太空，看不到地面上的操场，不能说“远处的操场”。", "出租车": "语义：出租车只在地面行驶，宇航员在太空中看不到它。", "冰箱": "搭配：“远处的”修饰可以远望见的事物，冰箱是室内家具，不能说“远处的冰箱”。"}, "sentence_index": 6, "correct_answer": "地球"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "中国是一个大地球。", "explanation": "这里指国家，应该用〈国家〉。地球指人类居住的行星，不能用来称呼一个国家。"}, {"text": "他一脚把地球踢进了球门。", "explanation": "这里指足球，应该用〈足球〉。地球是行星，不能当球来踢。"}, {"text": "我们的老师是一个地球。", "explanation": "这里用“地球”指人，不能用来比喻或称呼老师。“地球”指人类居住的行星。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23208, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "人类生活地球上。", "corrected_sentence": "人类生活在地球上。", "error_description": "错误：“生活”后面的处所要用“在……上”结构，这里漏掉了“在”。正确说法是：人类生活在地球上。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23208, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些行星里只有地球们有生命。", "corrected_sentence": "这些行星里只有地球有生命。", "error_description": "错误：“地球”是无生命的事物，不能加“们”表示复数。正确说法是：只有地球有生命。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
