INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23218, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "人用两条腿向前移动身体。", "primary_collocate": null, "pronunciation": "zǒu lù", "ipa": "tsou˨˩˦ lu˥˩", "syllable_count": 2, "sentences": [{"text": "小宝宝刚学会走路，走得不太稳。", "target_word": "走路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走路的时候喜欢听音乐。", "target_word": "走路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人走路慢，我们要等一等他。", "target_word": "走路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从地铁站走路到公司要十分钟。", "target_word": "走路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我每天走路上班，要走一个小时。", "target_word": "走路", "complexity_tier": "T3", "furigana": "zǒu lù", "sentence_source": "generated"}, {"text": "你走路为什么总是低着头？", "target_word": "走路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让他每天走路半小时。", "target_word": "走路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她走路的样子很好看。", "target_word": "走路", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "不要在马路上边走路边玩手机。", "target_word": "走路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里没有车，大家只能走路。", "target_word": "走路", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人用双腿一步一步前行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9161064e-2cba-486a-b7ee-cb947dd8f72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23218, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "走路", "is_correct": true, "explanation": "正确：“学会走路”是常见说法，后句“走得不太稳”正好承接。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与后句“走得不太稳”指的步行不相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”是在水中进行，与后句描述的步态无关。"}, {"text": "写字", "is_correct": false, "explanation": "搭配：“写字”不能与“走得不太稳”这样的步态描写相接。"}], "explanations": {"走路": "正确：“学会走路”是常见说法，后句“走得不太稳”正好承接。", "唱歌": "语义：“唱歌”与后句“走得不太稳”指的步行不相符。", "游泳": "语义：“游泳”是在水中进行，与后句描述的步态无关。", "写字": "搭配：“写字”不能与“走得不太稳”这样的步态描写相接。"}, "sentence_index": 0, "correct_answer": "走路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电梯从一楼走路到六楼要十分钟。", "explanation": "这里应该用〈坐〉。电梯没有腿，不能走路，应说坐电梯。"}, {"text": "他用眼睛走路到公司，要十分钟。", "explanation": "这里应该用〈去〉。走路只指用两条腿向前移动，眼睛不能移动身体，应说去公司。"}, {"text": "这辆公交车从地铁站走路到公司要十分钟。", "explanation": "这里应该用〈开〉。公交车不能走路，应说开车或乘车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23218, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "走路", "is_correct": true, "explanation": "正确：“医生让他每天走路半小时”指医生建议的步行锻炼，句意通顺。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”与医嘱中的锻炼无关，不能用来表示医生的要求。"}, {"text": "打字", "is_correct": false, "explanation": "语义：“打字”是手上的动作，不能表示每天半小时的身体活动。"}, {"text": "修车", "is_correct": false, "explanation": "搭配：“修车”不是医生会让病人每天做的活动，与“半小时”的锻炼说法不搭。"}], "explanations": {"走路": "正确：“医生让他每天走路半小时”指医生建议的步行锻炼，句意通顺。", "吃饭": "语义：“吃饭”与医嘱中的锻炼无关，不能用来表示医生的要求。", "打字": "语义：“打字”是手上的动作，不能表示每天半小时的身体活动。", "修车": "搭配：“修车”不是医生会让病人每天做的活动，与“半小时”的锻炼说法不搭。"}, "sentence_index": 6, "correct_answer": "走路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个箱子今天自己走路去了楼下。", "explanation": "这里应该用〈搬〉。箱子没有腿，不能自己走路，只能说搬到楼下。"}, {"text": "山里的河只能走路。", "explanation": "这里应该用〈流〉。河不能走路，走路只指有腿的人或动物行走。"}, {"text": "山里没有车，大家只能用翅膀走路。", "explanation": "这里应该用〈飞〉。走路只靠腿，用翅膀应说飞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23218, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他走路了很快。", "corrected_sentence": "他走路很快。", "error_description": "错误在于“了”加在了“走路”后面。“走路很快”中间不能插“了”，“了”表示完成，这里描述的是走路的状态，应说“他走路很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23218, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她走路得很稳。", "corrected_sentence": "她走路走得很稳。", "error_description": "错误在于补语结构。“得”需要接在动词“走”之后，且要重复动词，说“走路走得很稳”；“走路得很稳”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23220, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脏", "is_correct": true, "explanation": "“脏”与“干净”意思相反，指有污垢或脏东西。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”指光线充足，与“干净”没有反义关系。"}, {"text": "宽敞", "is_correct": false, "explanation": "“宽敞”指空间大，与“干净”没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”指人多声响大，与“干净”不构成反义。"}], "correct_answer": "脏", "explanations": {"脏": "“脏”与“干净”意思相反，指有污垢或脏东西。", "明亮": "“明亮”指光线充足，与“干净”没有反义关系。", "宽敞": "“宽敞”指空间大，与“干净”没有反义关系。", "热闹": "“热闹”指人多声响大，与“干净”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23220, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脏", "is_correct": true, "explanation": "“脏”与“干净”意思相反，指有污垢或脏东西。"}, {"text": "冰凉", "is_correct": false, "explanation": "“冰凉”指温度低，与“干净”不是反义词。"}, {"text": "嘹亮", "is_correct": false, "explanation": "“嘹亮”形容声音高亢，与“干净”不构成反义。"}, {"text": "热烈", "is_correct": false, "explanation": "“热烈”指情绪高涨，与“干净”没有反义关系。"}], "correct_answer": "脏", "explanations": {"脏": "“脏”与“干净”意思相反，指有污垢或脏东西。", "冰凉": "“冰凉”指温度低，与“干净”不是反义词。", "嘹亮": "“嘹亮”形容声音高亢，与“干净”不构成反义。", "热烈": "“热烈”指情绪高涨，与“干净”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23220, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有脏东西，很整洁。", "primary_collocate": null, "pronunciation": "gān jìng", "ipa": "kan˥ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这间屋子打扫得很干净。", "target_word": "干净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的手不干净，先去洗一洗。", "target_word": "干净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把衣服洗得干净又整齐。", "target_word": "干净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆很小，但是很干净。", "target_word": "干净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子喜欢干净的白衬衫。", "target_word": "干净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水变干净了，鱼也多起来了。", "target_word": "干净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把桌子擦干净，客人马上就到。", "target_word": "干净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街每天都有人打扫，非常干净。", "target_word": "干净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用干净的杯子喝水。", "target_word": "干净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗完澡，我觉得身上很干净。", "target_word": "干净", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "干净了", "label": "体标"}, {"form": "不干净", "label": "否定"}, {"form": "更干净", "label": "比较"}, {"form": "干干净净", "label": "重叠"}], "register": "中性", "sense_fingerprint": "物体或环境没有脏东西、整洁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e5e0e04-19d0-4826-8ae8-48040290f7a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23220, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干净", "is_correct": true, "explanation": "干净指没有脏东西，与“打扫”的结果相符，句意通顺。"}, {"text": "滚烫", "is_correct": false, "explanation": "语义：“滚烫”形容温度，不能用来形容屋子的整洁。"}, {"text": "香甜", "is_correct": false, "explanation": "搭配：“香甜”形容味道，不能用来形容房间。"}, {"text": "结实", "is_correct": false, "explanation": "搭配：“结实”形容物体牢固，不能用来形容打扫的结果。"}], "explanations": {"干净": "干净指没有脏东西，与“打扫”的结果相符，句意通顺。", "滚烫": "语义：“滚烫”形容温度，不能用来形容屋子的整洁。", "香甜": "搭配：“香甜”形容味道，不能用来形容房间。", "结实": "搭配：“结实”形容物体牢固，不能用来形容打扫的结果。"}, "sentence_index": 0, "correct_answer": "干净"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子的温度很干净，有点冷。", "explanation": "这里应该用〈暖和〉。温度的高低要说暖和或凉快，干净只指没有脏东西，不能形容温度。"}, {"text": "这本书的价格很干净。", "explanation": "这里应该用〈便宜〉。价格的高低要说贵或便宜，干净不能形容价格。"}, {"text": "这个小区的噪音很干净。", "explanation": "这里应该用〈安静〉。噪音的多少要说安静或吵，干净不能形容声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23220, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干净", "is_correct": true, "explanation": "干净指没有脏东西，与“擦”的结果以及“客人马上就到”的语境相符。"}, {"text": "擦碎", "is_correct": false, "explanation": "语义：桌子被擦碎就无法使用，与“客人马上就到”的整理语境相冲突。"}, {"text": "擦破", "is_correct": false, "explanation": "语义：“擦破”是损坏桌面，不是清理的结果。"}, {"text": "擦红", "is_correct": false, "explanation": "搭配：“擦红”多用于手或脸，不说擦红桌子。"}], "explanations": {"干净": "干净指没有脏东西，与“擦”的结果以及“客人马上就到”的语境相符。", "擦碎": "语义：桌子被擦碎就无法使用，与“客人马上就到”的整理语境相冲突。", "擦破": "语义：“擦破”是损坏桌面，不是清理的结果。", "擦红": "搭配：“擦红”多用于手或脸，不说擦红桌子。"}, "sentence_index": 6, "correct_answer": "干净"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块石头的重量很干净。", "explanation": "这里应该用〈沉〉。重量的大小要说沉或轻，干净只指没有脏东西，不能形容重量。"}, {"text": "他的力气很干净。", "explanation": "这里应该用〈大〉。干净不能用来形容力气。"}, {"text": "这辆车的速度很干净。", "explanation": "这里应该用〈快〉。干净不能用来形容速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23220, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把厨房擦很干净。", "corrected_sentence": "妈妈把厨房擦得很干净。", "error_description": "错误形式：擦很干净；正确形式：擦得很干净。动词后面带“很干净”作程度补语时，要用“得”把动词和补语连接起来。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23220, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把手干净了。", "corrected_sentence": "我把手洗干净了。", "error_description": "错误：“把手干净了”；正确：“把手洗干净了”。“干净”作结果补语时，“把”字句需要有动作动词“洗”，只说“把手干净”不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
