INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23232, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "路上跑的东西，能坐人，也能拉东西。", "primary_collocate": null, "pronunciation": "chē", "ipa": "ʈʂʰɤ˥", "syllable_count": 1, "sentences": [{"text": "我家有一辆红色的车。", "target_word": "车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上的车太多，我们走得很慢。", "target_word": "车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把车停在楼下了。", "target_word": "车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这辆车能坐五个人。", "target_word": "车", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那辆红色的车正在给商店送货。", "target_word": "车", "complexity_tier": "T3", "furigana": "nà liàng hóng sè de chē zhèng zài gěi shāng diàn sòng huò", "sentence_source": "generated"}, {"text": "我的车坏了，只好坐地铁。", "target_word": "车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前面的车突然停了下来。", "target_word": "车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想买一辆新车。", "target_word": "车", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这辆车很旧，但是还能跑。", "target_word": "车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车上有两个孩子和一只小狗。", "target_word": "车", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "汽车", "label": "复合"}, {"form": "火车", "label": "复合"}, {"form": "車", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：路上跑的、能坐人也能拉东西的车辆", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739f0140-8cbc-457e-8526-f10ae4204bc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23232, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "车", "is_correct": true, "explanation": "车（chē，第一声）指路上跑的、能坐人也能拉东西的车辆，是正确答案。"}, {"text": "茶", "is_correct": false, "explanation": "chá（第二声）与 chē（第一声）声调不同，意思是茶。"}, {"text": "撤", "is_correct": false, "explanation": "chè（第四声）与 chē 声调不同，意思是撤退、撤销。"}, {"text": "遮", "is_correct": false, "explanation": "zhē 与 chē 声母不同：zh 与 ch，意思是遮挡。"}, {"text": "扯", "is_correct": false, "explanation": "chě（第三声）与 chē 声调不同，意思是拉、扯。"}], "explanations": {"车": "车（chē，第一声）指路上跑的、能坐人也能拉东西的车辆，是正确答案。", "茶": "chá（第二声）与 chē（第一声）声调不同，意思是茶。", "撤": "chè（第四声）与 chē 声调不同，意思是撤退、撤销。", "遮": "zhē 与 chē 声母不同：zh 与 ch，意思是遮挡。", "扯": "chě（第三声）与 chē 声调不同，意思是拉、扯。"}, "sentence_index": null, "correct_answer": "车"}, "level_3": {"options": [{"text": "车", "is_correct": true, "explanation": "车：空位应是能载人、能跑的交通工具“车”。"}, {"text": "船", "is_correct": false, "explanation": "搭配：量词“辆”只用于车辆，船应用“艘”。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫不是车辆，“一辆红色的猫”说不通。"}, {"text": "书", "is_correct": false, "explanation": "搭配：量词“辆”不能用于书，书应用“本”。"}], "explanations": {"车": "车：空位应是能载人、能跑的交通工具“车”。", "船": "搭配：量词“辆”只用于车辆，船应用“艘”。", "猫": "语义：猫不是车辆，“一辆红色的猫”说不通。", "书": "搭配：量词“辆”不能用于书，书应用“本”。"}, "sentence_index": 0, "correct_answer": "车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家有一本车，很漂亮。", "explanation": "这里应该用〈辆〉。车的量词是“辆”，“本”用于书，不用于车。"}, {"text": "这台车能背诗，很有意思。", "explanation": "这里应该用〈机器人〉。车指路上跑的交通工具，不能背诗。"}, {"text": "我们沿着车走去学校。", "explanation": "这里应该用〈马路〉。车是交通工具，人不能沿着车走路，应说“沿着马路走”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23232, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "车", "is_correct": true, "explanation": "车：空位应是能突然停下来的交通工具“车”。"}, {"text": "花", "is_correct": false, "explanation": "语义：花不是能移动、能停下来的东西，“前面的花突然停了下来”说不通。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“房子”不会移动，不能和“突然停下来”搭配。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会移动，“突然停了下来”对它没有意义。"}], "explanations": {"车": "车：空位应是能突然停下来的交通工具“车”。", "花": "语义：花不是能移动、能停下来的东西，“前面的花突然停了下来”说不通。", "房子": "搭配：“房子”不会移动，不能和“突然停下来”搭配。", "桌子": "语义：桌子不会移动，“突然停了下来”对它没有意义。"}, "sentence_index": 6, "correct_answer": "车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家有一条车，很大。", "explanation": "这里应该用〈辆〉。车的量词是“辆”，“条”用于长的东西，不用于车。"}, {"text": "他用车煮了一锅饭。", "explanation": "这里应该用〈锅〉。车指交通工具，不能用来煮饭。"}, {"text": "我昨天买了一座车，很好开。", "explanation": "这里应该用〈辆〉。车的量词是“辆”，“座”用于山、桥、楼房等大型固定的东西，不用于车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23232, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "路上有一个车坏了，我们只好走路。", "corrected_sentence": "路上有一辆车坏了，我们只好走路。", "error_description": "错误形式：“一个车”；正确形式：“一辆车”。车的量词是“辆”，“个”不能用于车。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23232, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他想买一只新车，已经看了很久。", "corrected_sentence": "他想买一辆新车，已经看了很久。", "error_description": "错误形式：“一只新车”；正确形式：“一辆新车”。车的量词是“辆”，“只”不能用于车。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23234, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
