INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23234, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做一件事的方式。", "primary_collocate": null, "pronunciation": "bàn fǎ", "ipa": "pan˥˩ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "我想到一个好办法。", "target_word": "办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机坏了，我没有办法打电话。", "target_word": "办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题有三个办法可以解决。", "target_word": "办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总有办法让孩子笑。", "target_word": "办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学汉字最好的办法是每天写。", "target_word": "办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们换个办法试试吧。", "target_word": "办法", "complexity_tier": "T3", "furigana": "wǒmen huàn ge bànfǎ shìshi ba.", "sentence_source": "generated"}, {"text": "你有什么办法提高听力？", "target_word": "办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法太麻烦，我们换一个吧。", "target_word": "办法", "complexity_tier": "T3", "furigana": "zhège bànfǎ tài máfan, wǒmen huàn yí ge ba.", "sentence_source": "generated"}, {"text": "老师教了我们一个记单词的办法。", "target_word": "办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车坏了，我们想不出别的办法。", "target_word": "办法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}, {"form": "没办法", "label": "否定搭配"}], "register": "中性", "sense_fingerprint": "解决问题或完成事情的方式、手段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d813a3-5c7c-4c35-a022-bcb120b67276') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23234, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "办法", "is_correct": true, "explanation": "办法指做事的方式，“想到一个好办法”符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：想到的应是解决问题的方法，天气是自然现象，不能作为想出来的东西。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁是交通工具，不是可以“想到”的解决方案。"}, {"text": "出租车", "is_correct": false, "explanation": "语义：出租车是交通工具，不是可以“想到”的解决方式，“想到一个好出租车”不通。"}], "explanations": {"办法": "办法指做事的方式，“想到一个好办法”符合语境。", "天气": "语义：想到的应是解决问题的方法，天气是自然现象，不能作为想出来的东西。", "地铁": "语义：地铁是交通工具，不是可以“想到”的解决方案。", "出租车": "语义：出租车是交通工具，不是可以“想到”的解决方式，“想到一个好出租车”不通。"}, "sentence_index": 0, "correct_answer": "办法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他总有一只办法让孩子笑。", "explanation": "这里应该用〈个〉或〈种〉。办法是抽象名词，量词用“个”或“种”，“只”多用于动物，不用于办法。"}, {"text": "他的办法很严重。", "explanation": "这里应该用〈问题〉。“严重”形容问题或情况的程度，“办法”本身不能用“严重”来形容。"}, {"text": "他为了赚钱，不择办法。", "explanation": "这里应该用〈手段〉。“不择手段”是固定说法，指为达目的什么方法都用；“办法”不能用于“不择”后面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23234, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "办法", "is_correct": true, "explanation": "办法指解决问题的方式，“你有什么办法提高听力”符合语境。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不是提高听力的手段，句子问的是可行的方法。"}, {"text": "汽车", "is_correct": false, "explanation": "配价：“提高听力”需要一个可以施行的方式，“汽车”不能作为提高听力的手段。"}, {"text": "水杯", "is_correct": false, "explanation": "语义：水杯与提高听力没有关系，句子不通。"}], "explanations": {"办法": "办法指解决问题的方式，“你有什么办法提高听力”符合语境。", "钥匙": "语义：钥匙不是提高听力的手段，句子问的是可行的方法。", "汽车": "配价：“提高听力”需要一个可以施行的方式，“汽车”不能作为提高听力的手段。", "水杯": "语义：水杯与提高听力没有关系，句子不通。"}, "sentence_index": 6, "correct_answer": "办法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "车坏了，我们吃掉了一个办法。", "explanation": "这里应该用〈想出〉。“吃掉”的对象是食物，不能接“办法”；想到解决方法应说“想出”。"}, {"text": "车坏了，我们要去办理办法。", "explanation": "这里应该用〈手续〉。“办理”后面接手续、业务，不接办法，这里重复用“办理”，搭配不当。"}, {"text": "我每天锻炼，已经养成了办法。", "explanation": "这里应该用〈习惯〉。“养成”后面接习惯，不接“办法”；“办法”指做事的方式，不能被“养成”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23234, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想出了一只好办法。", "corrected_sentence": "他想出了一个好办法。", "error_description": "“办法”的量词应用“个”或“种”，不能用“只”。错误形式是“一只好办法”，正确形式是“一个好办法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23234, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们没想出了一个好办法。", "corrected_sentence": "我们没想出一个好办法。", "error_description": "“没”与“了”不能同时用在“想出”后面表示否定。错误形式是“没想出了”，正确形式是“没想出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23236, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "天气", "is_correct": false, "explanation": "与“污染”无反义关系：“天气”指一段时间里的风雨冷热，与污染的意思不相对。"}, {"text": "花园", "is_correct": false, "explanation": "与“污染”无反义关系：“花园”指种花草、供人游玩的地方，不是与污染相对的概念。"}, {"text": "河流", "is_correct": false, "explanation": "与“污染”无反义关系：“河流”是水道，是污染的对象之一，并不与污染相对。"}, {"text": "净化", "is_correct": true, "explanation": "反义：“净化”指去掉脏东西，使水、空气等变干净，与“污染”意思相对。"}], "correct_answer": "净化", "explanations": {"天气": "与“污染”无反义关系：“天气”指一段时间里的风雨冷热，与污染的意思不相对。", "花园": "与“污染”无反义关系：“花园”指种花草、供人游玩的地方，不是与污染相对的概念。", "河流": "与“污染”无反义关系：“河流”是水道，是污染的对象之一，并不与污染相对。", "净化": "反义：“净化”指去掉脏东西，使水、空气等变干净，与“污染”意思相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23236, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "教室", "is_correct": false, "explanation": "与“污染”无反义关系：“教室”是学生上课的房间，与污染的意思不相对。"}, {"text": "书包", "is_correct": false, "explanation": "与“污染”无反义关系：“书包”是装书本的用品，与污染的意思无关。"}, {"text": "窗户", "is_correct": false, "explanation": "与“污染”无反义关系：“窗户”是房屋上透光通气的部分，与污染不相对。"}, {"text": "净化", "is_correct": true, "explanation": "反义：“净化”指去掉脏东西，使水、空气等变干净，与“污染”意思相对。"}], "correct_answer": "净化", "explanations": {"教室": "与“污染”无反义关系：“教室”是学生上课的房间，与污染的意思不相对。", "书包": "与“污染”无反义关系：“书包”是装书本的用品，与污染的意思无关。", "窗户": "与“污染”无反义关系：“窗户”是房屋上透光通气的部分，与污染不相对。", "净化": "反义：“净化”指去掉脏东西，使水、空气等变干净，与“污染”意思相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23236, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "脏东西让水、空气变坏了。", "primary_collocate": null, "pronunciation": "wū rǎn", "ipa": "u˥ ʐan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个城市的空气污染很严重。", "target_word": "污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂把脏水排进河里，造成了水污染。", "target_word": "污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要保护环境，减少污染。", "target_word": "污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车太多会带来空气污染。", "target_word": "污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海洋污染让很多鱼死了。", "target_word": "污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水污染以后，人们不能喝了。", "target_word": "污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想办法解决污染问题。", "target_word": "污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的污染比去年少了。", "target_word": "污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料垃圾也是一种污染。", "target_word": "污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "化工厂排出的废气让附近的空气污染越来越严重。", "target_word": "污染", "complexity_tier": "T3", "furigana": "huà gōng chǎng pái chū de fèi qì ràng fù jìn de kōng qì wū rǎn yuè lái yuè yán zhòng", "sentence_source": "generated"}], "morphological_forms": [{"form": "污染物", "label": "复合"}, {"form": "污染源", "label": "复合"}, {"form": "环境污染", "label": "复合"}], "register": "中性", "sense_fingerprint": "污染：脏东西使水、空气等变坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea089b11-07da-4ae5-aa39-37efb2e90fe9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23236, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "污染", "is_correct": true, "explanation": "正确：“空气污染”是名词，“很严重”形容污染的程度，符合句意。"}, {"text": "质量", "is_correct": false, "explanation": "搭配：“严重”常修饰问题、污染、后果，不说“空气质量很严重”，应说“空气质量很差”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度指冷热的程度，不能用“很严重”来描述，句子意思不通。"}, {"text": "湿度", "is_correct": false, "explanation": "语义：湿度表示空气的潮湿程度，不能用“严重”来形容，与空气的脏和坏无关。"}], "explanations": {"污染": "正确：“空气污染”是名词，“很严重”形容污染的程度，符合句意。", "质量": "搭配：“严重”常修饰问题、污染、后果，不说“空气质量很严重”，应说“空气质量很差”。", "温度": "语义：温度指冷热的程度，不能用“很严重”来描述，句子意思不通。", "湿度": "语义：湿度表示空气的潮湿程度，不能用“严重”来形容，与空气的脏和坏无关。"}, "sentence_index": 0, "correct_answer": "污染"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他花了三天时间污染了这篇文章。", "explanation": "这里应该用〈修改〉。污染是把环境、水源等弄脏；文章的改动要说修改，不用污染。"}, {"text": "这个决定污染了公司的利益。", "explanation": "这里应该用〈损害〉。污染指物质环境被弄脏，利益受到伤害要说损害，不说污染。"}, {"text": "他一个人污染了三个小时的时间。", "explanation": "这里应该用〈浪费〉。污染是把环境、水源等弄脏；时间的消耗要说浪费，不用污染。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23236, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "污染", "is_correct": true, "explanation": "正确：“解决污染问题”中，“污染问题”是名词短语，符合句意。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：“解决”后接问题、矛盾，不能说“蛋糕问题”需要政府解决。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：政府要解决的是社会问题，“诗歌”与政府处理的事务无关，句子不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不是需要政府去解决的社会问题，句子意思不通。"}], "explanations": {"污染": "正确：“解决污染问题”中，“污染问题”是名词短语，符合句意。", "蛋糕": "搭配：“解决”后接问题、矛盾，不能说“蛋糕问题”需要政府解决。", "诗歌": "语义：政府要解决的是社会问题，“诗歌”与政府处理的事务无关，句子不通。", "石头": "语义：“石头”不是需要政府去解决的社会问题，句子意思不通。"}, "sentence_index": 6, "correct_answer": "污染"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校污染了很多人才。", "explanation": "这里应该用〈培养〉。污染指把环境、水源等弄脏，培养人才要用培养，不用污染。"}, {"text": "他的英语水平很快污染了。", "explanation": "这里应该用〈提高〉。污染用于环境、水源等被弄脏，水平、成绩要用提高。"}, {"text": "我们要污染国家的利益。", "explanation": "这里应该用〈维护〉。污染是把物质弄脏，保护国家利益要用维护，不能说污染利益。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23236, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农药是一只很严重的污染。", "corrected_sentence": "农药是一种很严重的污染。", "error_description": "量词错误：“污染”应该用量词“种”，“只”用于动物等，不能用来数“污染”。应为「农药是一种很严重的污染」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23236, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条河被工厂污染的很厉害。", "corrected_sentence": "这条河被工厂污染得很厉害。", "error_description": "补语标记错误：“污染”后面表示程度的补语要用“得”，不能用“的”。应为「这条河被工厂污染得很厉害」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
