INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23238, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "让人在钱财、精力或心理上感到沉重的事情或压力。", "primary_collocate": null, "pronunciation": "fù dān", "ipa": "fu˥˩ tan˥", "syllable_count": 2, "sentences": [{"text": "孩子上学的费用是家里很大的负担。", "target_word": "负担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份工作太累，成了他的负担。", "target_word": "负担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不想给朋友增加负担。", "target_word": "负担", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他找了工作，帮家里减轻了负担。", "target_word": "负担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个月的房租对他是个很重的负担。", "target_word": "负担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人生病，给全家带来了很大的负担。", "target_word": "负担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作业太多，学生的负担很重。", "target_word": "负担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请别把这件事当成负担。", "target_word": "负担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想成为别人的负担。", "target_word": "负担", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这点钱对我来说不是负担。", "target_word": "负担", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种负担", "label": "量词"}, {"form": "一个负担", "label": "量词"}, {"form": "经济负担", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，让人在钱、精力或心理上感到沉重的事情或压力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fef3691-c05f-4979-b766-4af9a742d3ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23238, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "财富", "is_correct": false, "explanation": "语义：财富指钱财和资产，与“费用”所指的支出不是一类，句子说不通。"}, {"text": "负担", "is_correct": true, "explanation": "负担：让人在钱、精力或心理上感到沉重的事情。这里指孩子上学的费用给家里带来的压力，正确。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「很大的」不能修饰颜色，费用的轻重不能用来形容颜色。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：礼物是送给别人的东西，费用是要花出去的钱，二者不能互相指代。"}], "explanations": {"财富": "语义：财富指钱财和资产，与“费用”所指的支出不是一类，句子说不通。", "负担": "负担：让人在钱、精力或心理上感到沉重的事情。这里指孩子上学的费用给家里带来的压力，正确。", "颜色": "搭配：「很大的」不能修饰颜色，费用的轻重不能用来形容颜色。", "礼物": "语义：礼物是送给别人的东西，费用是要花出去的钱，二者不能互相指代。"}, "sentence_index": 0, "correct_answer": "负担"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他负担着失去亲人的痛苦，每天都很难过。", "explanation": "这里应该用〈承受〉。「负担」多用于费用、责任，失去亲人的痛苦要说承受。"}, {"text": "他负担了这次比赛的冠军，大家都为他高兴。", "explanation": "这里应该用〈夺得〉。「负担」指承担费用、责任或沉重的事，不能说“负担冠军”。"}, {"text": "公司的负担很充足，可以开新工厂。", "explanation": "这里应该用〈资金〉。公司的钱要说资金；「负担」指沉重的事，不能说“负担很充足”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23238, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：天空不是学生身上的东西，与“作业太多”的语境无关。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：「很重」形容分量，不能用来形容成绩。"}, {"text": "负担", "is_correct": true, "explanation": "负担：让人感到沉重的事。这里指作业给学生带来的压力，正确。"}, {"text": "饭量", "is_correct": false, "explanation": "搭配：饭量的多少用「大」「小」来说，不用「重」。"}], "explanations": {"天空": "语义：天空不是学生身上的东西，与“作业太多”的语境无关。", "成绩": "搭配：「很重」形容分量，不能用来形容成绩。", "负担": "负担：让人感到沉重的事。这里指作业给学生带来的压力，正确。", "饭量": "搭配：饭量的多少用「大」「小」来说，不用「重」。"}, "sentence_index": 6, "correct_answer": "负担"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试他取得了好负担，老师很满意。", "explanation": "这里应该用〈成绩〉。「负担」指沉重的事，不能说“好负担”。"}, {"text": "这位歌手的负担很动听，我们都很喜欢。", "explanation": "这里应该用〈嗓音〉。「负担」指沉重的事，不能形容歌声；歌手的声音要说嗓音。"}, {"text": "院子里充满了负担，孩子们在玩耍。", "explanation": "这里应该用〈欢乐〉。欢乐是愉快的心情，「负担」指沉重的事，二者不能互换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23238, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事对他来说是一个沉重地负担。", "corrected_sentence": "这件事对他来说是一个沉重的负担。", "error_description": "错误：修饰名词“负担”的定语应用“的”，不用“地”。“地”用于修饰动词或形容词作状语，名词前不用“地”。正确应为“沉重的负担”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23238, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一个人要养活五口人，这颗负担他背了十年。", "corrected_sentence": "他一个人要养活五口人，这份负担他背了十年。", "error_description": "量词错误：「负担」应用「份」或「个」，「颗」用于粒状的小东西，不能用于负担。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
