INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23244, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "规划者就是做计划的人。", "primary_collocate": null, "pronunciation": "guī huà zhě", "ipa": "kuei˥ xua˥˩ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "我们的旅行规划者已经订好了车票。", "target_word": "规划者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是班里的活动规划者，大家都听他的。", "target_word": "规划者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的规划者正在做明年的计划。", "target_word": "规划者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "规划者要想清楚每一步该怎么走。", "target_word": "规划者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是我们家的规划者，周末去哪儿都由她安排。", "target_word": "规划者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "规划者把一个月的工作写在了本子上。", "target_word": "规划者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为规划者，他每天都要开很多会。", "target_word": "规划者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的规划者是我们的体育老师。", "target_word": "规划者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁路的规划者说，明年要再修一条新线路。", "target_word": "规划者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做一个好规划者，需要有耐心。", "target_word": "规划者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "旅行规划者", "label": "复合"}, {"form": "規劃者", "label": "繁体"}], "register": "中性", "sense_fingerprint": "泛指为旅行、活动、工作等做计划安排的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2efa2384-c1dd-4c37-a182-92a2f89de8d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23244, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "规划者", "is_correct": true, "explanation": "正确。「旅行规划者」指负责安排旅行的人，与「旅行」搭配，句意通顺。"}, {"text": "医生", "is_correct": false, "explanation": "语义：医生不负责安排旅行，「我们的旅行医生已经订好了车票」句意矛盾。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：歌手与旅行安排无关，「订好车票」与歌手身份不符。"}, {"text": "教练", "is_correct": false, "explanation": "搭配：「旅行教练」搭配不当，句中「订车票」也不是教练的常规职责。"}], "explanations": {"规划者": "正确。「旅行规划者」指负责安排旅行的人，与「旅行」搭配，句意通顺。", "医生": "语义：医生不负责安排旅行，「我们的旅行医生已经订好了车票」句意矛盾。", "歌手": "语义：歌手与旅行安排无关，「订好车票」与歌手身份不符。", "教练": "搭配：「旅行教练」搭配不当，句中「订车票」也不是教练的常规职责。"}, "sentence_index": 0, "correct_answer": "规划者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的规划者在医院里给病人做手术。", "explanation": "这里应该用〈医生〉。规划者指做计划的人，做手术是医生的工作，应说〈医生〉。"}, {"text": "这次晚会的规划者在给小狗看病。", "explanation": "这里应该用〈兽医〉。规划者指做计划的人，给动物看病是兽医的工作，应说〈兽医〉。"}, {"text": "这位规划者每天为我们理发。", "explanation": "这里应该用〈理发师〉。规划者指做计划的人，不指理发的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23244, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "规划者", "is_correct": true, "explanation": "正确。「作为规划者」表示身份，与「开很多会」的组织工作相符。"}, {"text": "清洁工", "is_correct": false, "explanation": "语义：清洁工的日常工作是打扫卫生，不负责规划和组织，与「每天都要开很多会」的角色不符。"}, {"text": "运动员", "is_correct": false, "explanation": "语义：运动员的日常以训练为主，与「每天都要开很多会」的角色不符。"}, {"text": "画家", "is_correct": false, "explanation": "搭配：「作为画家」后接「开很多会」搭配不当，画家的工作重心在创作。"}], "explanations": {"规划者": "正确。「作为规划者」表示身份，与「开很多会」的组织工作相符。", "清洁工": "语义：清洁工的日常工作是打扫卫生，不负责规划和组织，与「每天都要开很多会」的角色不符。", "运动员": "语义：运动员的日常以训练为主，与「每天都要开很多会」的角色不符。", "画家": "搭配：「作为画家」后接「开很多会」搭配不当，画家的工作重心在创作。"}, "sentence_index": 6, "correct_answer": "规划者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "做一只好规划者，需要有耐心。", "explanation": "这里应该用〈个〉。「规划者」指人，量词「只」用于动物或物件，不能用于人。"}, {"text": "这位规划者在台上演话剧。", "explanation": "这里应该用〈演员〉。规划者指做计划的人，演话剧是演员的工作，应说〈演员〉。"}, {"text": "这位规划者的职业是厨师，每天都在厨房里忙碌。", "explanation": "这里应该用〈厨师〉。规划者指做计划的人，做饭是厨师的职业，应说〈厨师〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23244, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只旅行规划者已经订好了酒店。", "corrected_sentence": "这位旅行规划者已经订好了酒店。", "error_description": "量词错误：「规划者」指人，应用量词「位」，「只」用于动物或物件，不能用于人。正确说法是「这位旅行规划者已经订好了酒店」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23244, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条旅行规划者经验很丰富。", "corrected_sentence": "这位旅行规划者经验很丰富。", "error_description": "量词错误：「规划者」指人，应用量词「位」，「条」多用于细长的物件，不能用于人。正确说法是「这位旅行规划者经验很丰富」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23246, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "重", "is_correct": true, "explanation": "重：与“轻”相对，指重量大，与“铝比铁轻”形成反义。"}, {"text": "快", "is_correct": false, "explanation": "快：形容速度，与“轻”没有反义关系。"}, {"text": "亮", "is_correct": false, "explanation": "亮：形容光线，与“轻”没有反义关系。"}, {"text": "甜", "is_correct": false, "explanation": "甜：形容味道，与“轻”没有反义关系。"}], "correct_answer": "重", "explanations": {"重": "重：与“轻”相对，指重量大，与“铝比铁轻”形成反义。", "快": "快：形容速度，与“轻”没有反义关系。", "亮": "亮：形容光线，与“轻”没有反义关系。", "甜": "甜：形容味道，与“轻”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23246, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "重", "is_correct": true, "explanation": "重：与“轻”相对，指重量大，与“提着很轻的包”形成反义。"}, {"text": "慢", "is_correct": false, "explanation": "慢：形容速度，与“轻”没有反义关系。"}, {"text": "暗", "is_correct": false, "explanation": "暗：形容光线，与“轻”没有反义关系。"}, {"text": "苦", "is_correct": false, "explanation": "苦：形容味道，与“轻”没有反义关系。"}], "correct_answer": "重", "explanations": {"重": "重：与“轻”相对，指重量大，与“提着很轻的包”形成反义。", "慢": "慢：形容速度，与“轻”没有反义关系。", "暗": "暗：形容光线，与“轻”没有反义关系。", "苦": "苦：形容味道，与“轻”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23246, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "东西不重，拿起来不费力气。", "primary_collocate": null, "pronunciation": "qīng", "ipa": "tɕʰiŋ˥", "syllable_count": 1, "sentences": [{"text": "这个箱子很轻，我一个人就能拿。", "target_word": "轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的行李很轻，只有一个小包。", "target_word": "轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把伞很轻，放进包里不占地方。", "target_word": "轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铝比铁轻，所以飞机用铝很多。", "target_word": "轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书很薄，拿着很轻。", "target_word": "轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋很轻，走远路也不累。", "target_word": "轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空杯子很轻，装满水就重了。", "target_word": "轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人买菜时，只拿轻的东西。", "target_word": "轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机又薄又轻，我很喜欢。", "target_word": "轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提着很轻的包，慢慢走进教室。", "target_word": "轻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "轻轻", "label": "重叠"}, {"form": "輕", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西重量小，拿着不费力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9161064e-2cba-486a-b7ee-cb947dd8f72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23246, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "轻", "is_correct": true, "explanation": "轻（qīng）：东西重量小，拿起来不费力。"}, {"text": "请", "is_correct": false, "explanation": "qǐng（第三声）与 qīng（第一声）声调不同，意思是请求。"}, {"text": "庆", "is_correct": false, "explanation": "qìng（第四声）与 qīng（第一声）声调不同，意思是庆祝。"}, {"text": "亲", "is_correct": false, "explanation": "qīn 与 qīng 韵尾不同（-n 与 -ng），意思是亲人。"}, {"text": "情", "is_correct": false, "explanation": "qíng（第二声）与 qīng（第一声）声调不同，意思是感情。"}], "explanations": {"轻": "轻（qīng）：东西重量小，拿起来不费力。", "请": "qǐng（第三声）与 qīng（第一声）声调不同，意思是请求。", "庆": "qìng（第四声）与 qīng（第一声）声调不同，意思是庆祝。", "亲": "qīn 与 qīng 韵尾不同（-n 与 -ng），意思是亲人。", "情": "qíng（第二声）与 qīng（第一声）声调不同，意思是感情。"}, "sentence_index": null, "correct_answer": "轻"}, "level_3": {"options": [{"text": "轻", "is_correct": true, "explanation": "轻：说明箱子重量小，与后句“一个人就能拿”一致。"}, {"text": "重", "is_correct": false, "explanation": "语义：“重”说箱子沉，与后句“一个人就能拿”的前提矛盾。"}, {"text": "慢", "is_correct": false, "explanation": "搭配：“慢”说速度，不能用来形容箱子的重量。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“亮”说光线或颜色，不能用来形容箱子的重量。"}], "explanations": {"轻": "轻：说明箱子重量小，与后句“一个人就能拿”一致。", "重": "语义：“重”说箱子沉，与后句“一个人就能拿”的前提矛盾。", "慢": "搭配：“慢”说速度，不能用来形容箱子的重量。", "亮": "搭配：“亮”说光线或颜色，不能用来形容箱子的重量。"}, "sentence_index": 0, "correct_answer": "轻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他为人很轻，说话做事都不稳重。", "explanation": "这里是“轻浮”的意思，指为人举止不庄重，与“东西不重、拿着不费力”的义项无关。"}, {"text": "他做决定很轻，没有考虑后果就签了合同。", "explanation": "这里是“轻率、不慎重”的意思，指做事不加考虑，与“东西不重、拿着不费力”的义项无关。"}, {"text": "他的存款很轻，买房子还差得远。", "explanation": "这里应该用〈少〉。存款的多少要用“少”，“轻”不用来形容钱的数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23246, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "轻", "is_correct": true, "explanation": "轻（qīng）：东西重量小，拿起来不费力。"}, {"text": "晴", "is_correct": false, "explanation": "qíng（第二声）与 qīng（第一声）声调不同，意思是晴天。"}, {"text": "星", "is_correct": false, "explanation": "xīng 与 qīng 声母不同（x 与 q），意思是星星。"}, {"text": "经", "is_correct": false, "explanation": "jīng 与 qīng 声母不同（j 与 q），意思是经过。"}, {"text": "惊", "is_correct": false, "explanation": "jīng 与 qīng 声母不同（j 与 q），意思是惊讶。"}], "explanations": {"轻": "轻（qīng）：东西重量小，拿起来不费力。", "晴": "qíng（第二声）与 qīng（第一声）声调不同，意思是晴天。", "星": "xīng 与 qīng 声母不同（x 与 q），意思是星星。", "经": "jīng 与 qīng 声母不同（j 与 q），意思是经过。", "惊": "jīng 与 qīng 声母不同（j 与 q），意思是惊讶。"}, "sentence_index": null, "correct_answer": "轻"}, "level_3": {"options": [{"text": "轻", "is_correct": true, "explanation": "轻：与“装满水就重了”呼应，说明空杯子重量小。"}, {"text": "沉", "is_correct": false, "explanation": "语义：“沉”说重，与“空杯子”矛盾。"}, {"text": "满", "is_correct": false, "explanation": "语义：“满”说装满，与“空杯子”矛盾。"}, {"text": "快", "is_correct": false, "explanation": "搭配：“快”说速度，不能用来形容杯子的重量。"}], "explanations": {"轻": "轻：与“装满水就重了”呼应，说明空杯子重量小。", "沉": "语义：“沉”说重，与“空杯子”矛盾。", "满": "语义：“满”说装满，与“空杯子”矛盾。", "快": "搭配：“快”说速度，不能用来形容杯子的重量。"}, "sentence_index": 6, "correct_answer": "轻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的水很轻，一眼就能看到底。", "explanation": "这里应该用〈浅〉。河水的深浅要用“浅”，“轻”不表示深度。"}, {"text": "他对这件事的印象很轻，过了几天就忘了。", "explanation": "这里是“印象不深”的意思，指印象的深浅，与“东西不重、拿着不费力”的义项无关。"}, {"text": "这件衣服的颜色很轻，穿在身上很舒服。", "explanation": "这里应该用〈淡〉。颜色的深浅要用“淡”，“轻”不用来形容颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23246, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个包轻很，我提着不累。", "corrected_sentence": "这个包很轻，我提着不累。", "error_description": "错误形式：“轻很”。正确形式：“很轻”。形容词“轻”作谓语时，程度副词“很”要放在它前面，不能放在后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23246, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶出门时，只带很轻包。", "corrected_sentence": "奶奶出门时，只带很轻的包。", "error_description": "错误形式：“很轻包”，缺少结构助词“的”。正确形式：“很轻的包”。“很轻”修饰名词时，中间要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
