INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23248, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "路上车子不多，走得很快。", "primary_collocate": null, "pronunciation": "bù dǔ chē", "ipa": "pu˥˩ tu˨˩˦ ʈʂʰɤ˥", "syllable_count": 3, "sentences": [{"text": "晚上十点以后，这条路不堵车。", "target_word": "不堵车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "走这条小路不堵车，十分钟就到。", "target_word": "不堵车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "星期天我骑车去超市，路上不堵车。", "target_word": "不堵车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你放心，现在路上车子很少，不堵车。", "target_word": "不堵车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他住在郊外，每天开车上班都不堵车。", "target_word": "不堵车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天路上不堵车，我早到了十分钟。", "target_word": "不堵车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年的时候，城里的人都回家了，路上不堵车。", "target_word": "不堵车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个时间走高速不堵车，车开得很快。", "target_word": "不堵车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家离学校近，路上从来不堵车。", "target_word": "不堵车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下午三点车少，去医院不堵车。", "target_word": "不堵车", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "路上车少、行车很快", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9161064e-2cba-486a-b7ee-cb947dd8f72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23248, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不堵车", "is_correct": true, "explanation": "不堵车：与“晚上十点以后”的少车状况一致，说明路上车子不多。"}, {"text": "很挤", "is_correct": false, "explanation": "语义：“很挤”说车多，与“晚上十点以后”的少车状况矛盾。"}, {"text": "很慢", "is_correct": false, "explanation": "搭配：“慢”说速度，不能用来形容路面的通行状况。"}, {"text": "很远", "is_correct": false, "explanation": "搭配：“远”说距离，不能用来形容路况。"}], "explanations": {"不堵车": "不堵车：与“晚上十点以后”的少车状况一致，说明路上车子不多。", "很挤": "语义：“很挤”说车多，与“晚上十点以后”的少车状况矛盾。", "很慢": "搭配：“慢”说速度，不能用来形容路面的通行状况。", "很远": "搭配：“远”说距离，不能用来形容路况。"}, "sentence_index": 0, "correct_answer": "不堵车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他负责的项目很不堵车，大家都很放心。", "explanation": "这里应该用〈顺利〉。“不堵车”只说道路上车辆行驶顺畅，不能用来形容项目。"}, {"text": "这首诗读起来很不堵车，很有节奏。", "explanation": "这里应该用〈流畅〉。“不堵车”只描述交通状况，不能用来形容诗歌。"}, {"text": "这句话很不堵车，我一看就懂了。", "explanation": "这里应该用〈通顺〉。“不堵车”只描述交通状况，不能用来形容话语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23248, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不堵车", "is_correct": true, "explanation": "不堵车：与“城里的人都回家了”呼应，说明路上车少。"}, {"text": "很堵", "is_correct": false, "explanation": "语义：与“城里的人都回家了”矛盾，人少时路上不会堵。"}, {"text": "很长", "is_correct": false, "explanation": "搭配：“长”说长度，不能用来形容路况。"}, {"text": "很热", "is_correct": false, "explanation": "搭配：“热”说温度，不能用来形容路况。"}], "explanations": {"不堵车": "不堵车：与“城里的人都回家了”呼应，说明路上车少。", "很堵": "语义：与“城里的人都回家了”矛盾，人少时路上不会堵。", "很长": "搭配：“长”说长度，不能用来形容路况。", "很热": "搭配：“热”说温度，不能用来形容路况。"}, "sentence_index": 6, "correct_answer": "不堵车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考察的安排很不堵车，大家都很满意。", "explanation": "这里应该用〈顺畅〉。“不堵车”只描述道路交通，安排的进行要说“顺畅”。"}, {"text": "这首歌很不堵车，大家都能跟着唱。", "explanation": "这里应该用〈顺口〉。“不堵车”只用于车辆通行，不能用来形容歌曲。"}, {"text": "这条河的水很不堵车，流得很快。", "explanation": "这里应该用〈畅通〉。“不堵车”只用于交通，不能用来形容水流。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23248, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜里十二点，把街上不堵车，出租车开得很快。", "corrected_sentence": "夜里十二点，街上不堵车，出租车开得很快。", "error_description": "错误在于多用了“把”。“把”字句要处置某个事物，这里只是描述路况，应删去“把”，说“街上不堵车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23248, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下午三点，路上不堵车子，去医院很方便。", "corrected_sentence": "下午三点，路上不堵车，去医院很方便。", "error_description": "错误形式：“不堵车子”。正确形式：“不堵车”。“堵车”是离合词，不能直接带“车子”作宾语，否定时直接说“不堵车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229c580d-6ad0-4b7e-8d34-4715d9d1f1f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
