INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23254, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "能带人去别的地方的东西，比如汽车、火车。", "primary_collocate": null, "pronunciation": "jiāo tōng gōng jù", "ipa": "tɕjɑʊ˥˥ tʰʊŋ˥˥ kʊŋ˥˥ tɕy˥˩", "syllable_count": 4, "sentences": [{"text": "火车是我最喜欢的交通工具。", "target_word": "交通工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船也是一种交通工具。", "target_word": "交通工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，去机场坐什么交通工具最快？", "target_word": "交通工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家离学校很远，要用交通工具。", "target_word": "交通工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车和火车都是常见的交通工具。", "target_word": "交通工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小城里的交通工具只有公交车。", "target_word": "交通工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时没有交通工具，每天走路上班。", "target_word": "交通工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门旅行，你喜欢哪种交通工具？", "target_word": "交通工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁是这个城市最快的交通工具。", "target_word": "交通工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们很喜欢画各种交通工具。", "target_word": "交通工具", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种交通工具", "label": "量词"}, {"form": "公共交通工具", "label": "复合"}], "register": "中性", "sense_fingerprint": "能带人去别处的汽车、火车等东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6d1d209-2497-4689-a3ce-946e569e7ac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23254, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交通工具", "is_correct": true, "explanation": "正确：火车是运送乘客的交通工具，符合句意。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：火车不是乐器，不能作为“最喜欢的乐器”，句子说不通。"}, {"text": "食物", "is_correct": false, "explanation": "语义：火车不是食物，与“最喜欢的食物”的说法不合。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“火车”不能与“颜色”构成“最喜欢的颜色”这样的说法。"}], "explanations": {"交通工具": "正确：火车是运送乘客的交通工具，符合句意。", "乐器": "语义：火车不是乐器，不能作为“最喜欢的乐器”，句子说不通。", "食物": "语义：火车不是食物，与“最喜欢的食物”的说法不合。", "颜色": "搭配：“火车”不能与“颜色”构成“最喜欢的颜色”这样的说法。"}, "sentence_index": 0, "correct_answer": "交通工具"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的书房里摆满了交通工具。", "explanation": "这里应该用〈书籍〉。交通工具指运送人或货物的车船，书房里摆满的应是书籍。"}, {"text": "妈妈把交通工具放进冰箱里保鲜。", "explanation": "这里应该用〈食物〉。交通工具指运送人或货物的车船，放进冰箱保鲜的应是食物。"}, {"text": "他在比赛中穿着交通工具。", "explanation": "这里应该用〈衣服〉。交通工具指运送人或货物的车船，比赛中穿在身上的应是衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23254, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交通工具", "is_correct": true, "explanation": "正确：没有交通工具，只能走路上班，句意相合。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：没有眼镜与“每天走路上班”没有关系，句子说不通。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴与“走路上班”无关，句子说不通。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“上班”的人一般不用课本，“课本”与“上班”不搭配。"}], "explanations": {"交通工具": "正确：没有交通工具，只能走路上班，句意相合。", "眼镜": "语义：没有眼镜与“每天走路上班”没有关系，句子说不通。", "钢琴": "语义：钢琴与“走路上班”无关，句子说不通。", "课本": "搭配：“上班”的人一般不用课本，“课本”与“上班”不搭配。"}, "sentence_index": 6, "correct_answer": "交通工具"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨房的橱柜里摆着很多交通工具。", "explanation": "这里应该用〈餐具〉。交通工具指运送人或货物的车船，橱柜里摆的是餐具。"}, {"text": "木匠用交通工具修好了桌子。", "explanation": "这里应该用〈工具〉。交通工具是运送人或货物的车船，修桌子用的是工具。"}, {"text": "客厅里摆着很多交通工具。", "explanation": "这里应该用〈家具〉。交通工具指运送人或货物的车船，客厅里摆的应是家具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23254, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "火车是他去北京的一支交通工具。", "corrected_sentence": "火车是他去北京的一种交通工具。", "error_description": "量词错误：“支”用于细长的物件，交通工具应用量词“种”。应说“一种交通工具”，不能说“一支交通工具”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23254, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车站门口停了着几种交通工具。", "corrected_sentence": "车站门口停着几种交通工具。", "error_description": "体貌错误：“着”表示状态持续，不能与“了”连用。应说“停着几种交通工具”，不能说“停了着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
