INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23264, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "工厂或汽车排出的、没用的、脏脏的气体。", "primary_collocate": null, "pronunciation": "fèi qì", "ipa": "feɪ˥˩ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "汽车跑的时候会排出废气。", "target_word": "废气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烟囱里冒出了黑色的废气。", "target_word": "废气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢站在大卡车后面闻废气。", "target_word": "废气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的废气让附近的空气很脏。", "target_word": "废气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些废气对小孩的身体不好。", "target_word": "废气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公交车排出一股废气，我赶快捂住鼻子。", "target_word": "废气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑自行车不会产生废气。", "target_word": "废气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上没有工厂，也没有废气。", "target_word": "废气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，吸入太多废气会头疼。", "target_word": "废气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新车的废气比旧车少很多。", "target_word": "废气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股废气", "label": "量词"}, {"form": "工业废气", "label": "复合"}], "register": "中性", "sense_fingerprint": "工厂或汽车排出的没用的脏气体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6d1d209-2497-4689-a3ce-946e569e7ac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23264, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "废气", "is_correct": true, "explanation": "废气（fèiqì）即正确答案：工厂或汽车排出的、没用的、脏的气体。"}, {"text": "费力", "is_correct": false, "explanation": "费力（fèilì）与废气（fèiqì）后一音节声母不同（l 与 q），意思是费劲、吃力。"}, {"text": "飞起", "is_correct": false, "explanation": "飞起（fēiqǐ）与废气（fèiqì）两个音节的声调都不同，意思是飞上去。"}, {"text": "匪气", "is_correct": false, "explanation": "匪气（fěiqì）与废气（fèiqì）第一音节声调不同（第三声与第四声），意思是土匪的作风。"}, {"text": "费事", "is_correct": false, "explanation": "费事（fèishì）与废气（fèiqì）后一音节声母不同（sh 与 q），意思是麻烦。"}], "explanations": {"废气": "废气（fèiqì）即正确答案：工厂或汽车排出的、没用的、脏的气体。", "费力": "费力（fèilì）与废气（fèiqì）后一音节声母不同（l 与 q），意思是费劲、吃力。", "飞起": "飞起（fēiqǐ）与废气（fèiqì）两个音节的声调都不同，意思是飞上去。", "匪气": "匪气（fěiqì）与废气（fèiqì）第一音节声调不同（第三声与第四声），意思是土匪的作风。", "费事": "费事（fèishì）与废气（fèiqì）后一音节声母不同（sh 与 q），意思是麻烦。"}, "sentence_index": null, "correct_answer": "废气"}, "level_3": {"options": [{"text": "废气", "is_correct": true, "explanation": "正确：汽车跑时排出的是废气，这与“排出”搭配，符合句意。"}, {"text": "垃圾", "is_correct": false, "explanation": "搭配：“排出”后接气体，不说排出垃圾，汽车跑时也不排出垃圾。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块是固体，汽车跑的时候不会排出冰块。"}, {"text": "铁块", "is_correct": false, "explanation": "语义：铁块是固体，不会从汽车里排出。"}], "explanations": {"废气": "正确：汽车跑时排出的是废气，这与“排出”搭配，符合句意。", "垃圾": "搭配：“排出”后接气体，不说排出垃圾，汽车跑时也不排出垃圾。", "冰块": "语义：冰块是固体，汽车跑的时候不会排出冰块。", "铁块": "语义：铁块是固体，不会从汽车里排出。"}, "sentence_index": 0, "correct_answer": "废气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "烟囱里冒出了一只废气。", "explanation": "这里应该用〈股〉。废气是气体，量词用“股”，应说“一股废气”，不说“一只”。"}, {"text": "山上的废气很清新。", "explanation": "这里应该用〈空气〉。废气是排出的脏气体，不能用“清新”形容；形容清新要用空气。"}, {"text": "我每天都吃废气。", "explanation": "这里应该用〈蔬菜〉。废气不能吃，“吃”的对象应是食物，如蔬菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23264, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "废气", "is_correct": true, "explanation": "正确：骑自行车不排废气，句中“产生”的是废气，与语境相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是固体，骑自行车不会产生石头。"}, {"text": "闪电", "is_correct": false, "explanation": "语义：闪电是自然现象，与骑车无关，不会因骑车而产生。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：“产生”多接热量、气体、结果，不接花朵。"}], "explanations": {"废气": "正确：骑自行车不排废气，句中“产生”的是废气，与语境相符。", "石头": "语义：石头是固体，骑自行车不会产生石头。", "闪电": "语义：闪电是自然现象，与骑车无关，不会因骑车而产生。", "花朵": "搭配：“产生”多接热量、气体、结果，不接花朵。"}, "sentence_index": 6, "correct_answer": "废气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把废气放进了冰箱。", "explanation": "这里应该用〈牛奶〉。废气是气体，不能放进冰箱保存；冰箱放的是食物。"}, {"text": "我们用废气装饰房间。", "explanation": "这里应该用〈鲜花〉。废气是有害无用的气体，不能用来装饰；装饰房间要用鲜花之类的东西。"}, {"text": "他用废气写字。", "explanation": "这里应该用〈钢笔〉。写字要用书写工具，废气不能用来写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23264, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆老汽车排出一只黑色的废气。", "corrected_sentence": "这辆老汽车排出一股黑色的废气。", "error_description": "“废气”的量词应为“股”，应说“一股废气”，不说“一只废气”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23264, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把废气收集起去了。", "corrected_sentence": "工人把废气收集起来了。", "error_description": "趋向补语应说“起来”，不说“起去”，应说“把废气收集起来”，不说“把废气收集起去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23270, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变好", "is_correct": true, "explanation": "正确：“变好”与“变坏”互为反义，表示变得好。"}, {"text": "存放", "is_correct": false, "explanation": "存放是动词，指保存物品，与“变坏”没有反义关系。"}, {"text": "生长", "is_correct": false, "explanation": "生长是动词，指生物的发育增长，与“变坏”没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步是动词，指快速移动身体，与“变坏”没有反义关系。"}], "correct_answer": "变好", "explanations": {"变好": "正确：“变好”与“变坏”互为反义，表示变得好。", "存放": "存放是动词，指保存物品，与“变坏”没有反义关系。", "生长": "生长是动词，指生物的发育增长，与“变坏”没有反义关系。", "跑步": "跑步是动词，指快速移动身体，与“变坏”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23270, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变好", "is_correct": true, "explanation": "正确：“变好”与“变坏”互为反义，表示变得好。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳是动词，指在水中运动，与“变坏”没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌是动词，指发出有节奏的声音，与“变坏”没有反义关系。"}, {"text": "写信", "is_correct": false, "explanation": "写信是动词，指用文字传递消息，与“变坏”没有反义关系。"}], "correct_answer": "变好", "explanations": {"变好": "正确：“变好”与“变坏”互为反义，表示变得好。", "游泳": "游泳是动词，指在水中运动，与“变坏”没有反义关系。", "唱歌": "唱歌是动词，指发出有节奏的声音，与“变坏”没有反义关系。", "写信": "写信是动词，指用文字传递消息，与“变坏”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23270, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "变得不好。", "primary_collocate": null, "pronunciation": "biàn huài", "ipa": "pjɛn˥˩ xwaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他的心情突然变坏了，一句话也不说。", "target_word": "变坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "换了新老板，饭店的服务变坏了。", "target_word": "变坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变坏，我们不能去爬山了。", "target_word": "变坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的关系变坏了，现在很少说话。", "target_word": "变坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脾气越来越大，人也变坏了。", "target_word": "变坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天饭菜不放冰箱，很容易变坏。", "target_word": "变坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的眼睛变坏了，看书要戴眼镜。", "target_word": "变坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做了错事以后，他的名声变坏了。", "target_word": "变坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的学习习惯变坏了，作业总是不做。", "target_word": "变坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城里车太多，空气变坏了，大家都咳嗽。", "target_word": "变坏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "变坏了", "label": "体标"}, {"form": "变坏过", "label": "体标"}, {"form": "變壞", "label": "繁体"}], "register": "中性", "sense_fingerprint": "状态、关系、心情等变得不好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6d1d209-2497-4689-a3ce-946e569e7ac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23270, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "变坏", "is_correct": true, "explanation": "变坏（biànhuài）即正确答案，指变得不好。"}, {"text": "变化", "is_correct": false, "explanation": "变化（biànhuà）与变坏（biànhuài）韵尾不同（a 与 ai），意思是改变、变动。"}, {"text": "变换", "is_correct": false, "explanation": "变换（biànhuàn）与变坏（biànhuài）韵尾不同（an 与 ai），意思是改换、转换。"}, {"text": "变快", "is_correct": false, "explanation": "变快（biànkuài）与变坏（biànhuài）声母不同（k 与 h），意思是速度变快。"}], "explanations": {"变坏": "变坏（biànhuài）即正确答案，指变得不好。", "变化": "变化（biànhuà）与变坏（biànhuài）韵尾不同（a 与 ai），意思是改变、变动。", "变换": "变换（biànhuàn）与变坏（biànhuài）韵尾不同（an 与 ai），意思是改换、转换。", "变快": "变快（biànkuài）与变坏（biànhuài）声母不同（k 与 h），意思是速度变快。"}, "sentence_index": null, "correct_answer": "变坏"}, "level_3": {"options": [{"text": "变坏", "is_correct": true, "explanation": "正确：“变坏”表示心情转坏，与后句“一句话也不说”相符。"}, {"text": "变甜", "is_correct": false, "explanation": "搭配：“甜”说的是味道，心情不说变甜，也不符合句意。"}, {"text": "变长", "is_correct": false, "explanation": "语义：心情不会变长，与句意不符。"}, {"text": "变远", "is_correct": false, "explanation": "语义：“远”说的是距离，心情不会变远。"}], "explanations": {"变坏": "正确：“变坏”表示心情转坏，与后句“一句话也不说”相符。", "变甜": "搭配：“甜”说的是味道，心情不说变甜，也不符合句意。", "变长": "语义：心情不会变长，与句意不符。", "变远": "语义：“远”说的是距离，心情不会变远。"}, "sentence_index": 0, "correct_answer": "变坏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭店的营业时间变坏了，客人越来越少。", "explanation": "这里应该用〈延长〉。营业时间的调整说“延长”或“缩短”；“变坏”指事物性质转坏，不用于时间。"}, {"text": "他这个月变坏了好几公斤。", "explanation": "这里应该用〈变瘦〉。体重减少要说“变瘦”，不说“变坏”。"}, {"text": "下午的影子变坏了。", "explanation": "这里应该用〈变长〉。影子的长短变化说“变长”，影子没有好坏之分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23270, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变坏", "is_correct": true, "explanation": "正确：眼睛变坏即视力下降，所以要戴眼镜，与句意相符。"}, {"text": "变轻", "is_correct": false, "explanation": "语义：眼睛不会“变轻”，与视力下降的语境不符。"}, {"text": "变凉", "is_correct": false, "explanation": "语义：眼睛不会“变凉”，也不能说明需要戴眼镜。"}, {"text": "变涨", "is_correct": false, "explanation": "搭配：“涨”用于价格、水位，不说眼睛变涨。"}], "explanations": {"变坏": "正确：眼睛变坏即视力下降，所以要戴眼镜，与句意相符。", "变轻": "语义：眼睛不会“变轻”，与视力下降的语境不符。", "变凉": "语义：眼睛不会“变凉”，也不能说明需要戴眼镜。", "变涨": "搭配：“涨”用于价格、水位，不说眼睛变涨。"}, "sentence_index": 6, "correct_answer": "变坏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵树一年变坏了两米。", "explanation": "这里应该用〈变高〉。树长高是高度的增加，不是变好或变坏，应说“变高”。"}, {"text": "春天到了，草地变坏了。", "explanation": "这里应该用〈变绿〉。草地变绿是颜色的变化，不表示变坏，应说“变绿”。"}, {"text": "全市的人口变坏了不少。", "explanation": "这里应该用〈增加〉。人口数量增多说“增加”，人口不能“变坏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23270, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的情绪很变坏了，大家都很担心。", "corrected_sentence": "他的情绪慢慢变坏了，大家都很担心。", "error_description": "副词“很”不能修饰动作动词“变坏”，应说“慢慢变坏了”，不说“很变坏了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23270, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店开了十年，服务变坏着。", "corrected_sentence": "这家店开了十年，服务变坏了。", "error_description": "“变坏”表示已经发生的变化，要用“了”；“着”表示持续的状态，不能说“变坏着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
