INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23272, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "坐车、坐船、坐飞机。", "primary_collocate": null, "pronunciation": "chéng zuò", "ipa": "ʈʂʰɤŋ˧˥ tswo˥˩", "syllable_count": 2, "sentences": [{"text": "去北京可以乘坐高铁，也可以坐飞机。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他乘坐大船去了海上的小岛。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人乘坐公共汽车不用买票。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没乘坐过船。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乘坐这趟火车要三个小时。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，她乘坐出租车回家。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乘坐地铁去机场又快又便宜。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们乘坐旅游车参观了老城。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乘坐飞机前，要先检查行李。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请乘坐下一班车，这辆车已经满了。", "target_word": "乘坐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "乘坐了", "label": "体标"}, {"form": "乘坐过", "label": "体标"}, {"form": "乘坐着", "label": "体标"}], "register": "中性", "sense_fingerprint": "坐车、坐船、坐飞机", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6d1d209-2497-4689-a3ce-946e569e7ac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23272, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乘坐", "is_correct": true, "explanation": "乘坐：搭乘交通工具前往，此处指坐高铁去北京。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修复，句中要表达的是去北京的出行方式。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”带的是货物，不能说搬运高铁去北京。"}, {"text": "检修", "is_correct": false, "explanation": "语义：“检修”指检查维修，与去北京的意思不符。"}], "explanations": {"乘坐": "乘坐：搭乘交通工具前往，此处指坐高铁去北京。", "修理": "语义：“修理”指修复，句中要表达的是去北京的出行方式。", "搬运": "搭配：“搬运”带的是货物，不能说搬运高铁去北京。", "检修": "语义：“检修”指检查维修，与去北京的意思不符。"}, "sentence_index": 0, "correct_answer": "乘坐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在屋里乘坐椅子看书。", "explanation": "这里应该用〈坐〉。乘坐的宾语须是交通工具，椅子不是，应说“坐在椅子上”。"}, {"text": "我每天乘坐马上学。", "explanation": "这里应该用〈骑〉。乘坐指坐在交通工具里，骑马要说〈骑〉。"}, {"text": "他把行李乘坐上楼。", "explanation": "这里应该用〈搬〉。乘坐的对象是交通工具，行李应说〈搬〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23272, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乘坐", "is_correct": true, "explanation": "乘坐：搭乘交通工具出行，此处指乘地铁去机场。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”指在水中活动，地铁不能游泳，与句意不合。"}, {"text": "维修", "is_correct": false, "explanation": "语义：“维修”指修理保养，与去机场的出行意思不符。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”带的是货物，不能说搬运地铁去机场。"}], "explanations": {"乘坐": "乘坐：搭乘交通工具出行，此处指乘地铁去机场。", "游泳": "语义：“游泳”指在水中活动，地铁不能游泳，与句意不合。", "维修": "语义：“维修”指修理保养，与去机场的出行意思不符。", "搬运": "搭配：“搬运”带的是货物，不能说搬运地铁去机场。"}, "sentence_index": 6, "correct_answer": "乘坐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我乘坐那辆车开回家，车很快。", "explanation": "这里应该用〈驾驶〉。乘坐指作为乘客坐车，句中说“开”，应说〈驾驶〉。"}, {"text": "我们乘坐了一个小时的快乐。", "explanation": "这里应该用〈享受〉。乘坐的对象是交通工具，快乐不能被乘坐，应说〈享受〉。"}, {"text": "他乘坐一只狗去学校。", "explanation": "这里应该用〈牵〉。乘坐的宾语是交通工具，狗不是，应说“牵着一只狗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23272, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去上海可以乘坐了高铁，也可以乘坐飞机。", "corrected_sentence": "去上海可以乘坐高铁，也可以乘坐飞机。", "error_description": "“了”应删去。“可以”表示可能，后面的动词不能带表示完成的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23272, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们明天乘坐了旅游车去参观老城。", "corrected_sentence": "他们明天乘坐旅游车去参观老城。", "error_description": "“了”应删去。“明天”指将来，动作尚未发生，不能用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
