INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23274, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23274, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "自己管住自己，不让自己做不该做的事。", "primary_collocate": null, "pronunciation": "zì zhì", "ipa": "tsɨ˥˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "老师说，学会自制才能少犯错误。", "target_word": "自制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想玩手机，但还是自制，先写作业。", "target_word": "自制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她努力自制，没有乱买东西。", "target_word": "自制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生气就骂人，很难自制。", "target_word": "自制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛输了，他很难过，却能自制。", "target_word": "自制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "减肥的人要自制，不能总吃甜食。", "target_word": "自制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，大人也要自制，不能总发脾气。", "target_word": "自制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对游戏，小孩往往不能自制。", "target_word": "自制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一时冲动想打人，最后自制了。", "target_word": "自制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "越是着急，越要自制，不要乱说话。", "target_word": "自制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自制力", "label": "复合"}, {"form": "自制了", "label": "体标"}], "register": "中性", "sense_fingerprint": "管住自己，不做不该做的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01eeaa98-ccee-411a-b977-696f87b61517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23274, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自制", "is_correct": true, "explanation": "正确。“学会自制”指管住自己，与“少犯错误”的语境相符。"}, {"text": "放纵", "is_correct": false, "explanation": "语义：“放纵”是不加约束，与“才能少犯错误”的因果关系相反。"}, {"text": "拖延", "is_correct": false, "explanation": "语义：“拖延”是推迟做事，与“少犯错误”没有合理的因果关系。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：「吵闹」是喧哗，与「少犯错误」没有因果联系，句意不通。"}], "explanations": {"自制": "正确。“学会自制”指管住自己，与“少犯错误”的语境相符。", "放纵": "语义：“放纵”是不加约束，与“才能少犯错误”的因果关系相反。", "拖延": "语义：“拖延”是推迟做事，与“少犯错误”没有合理的因果关系。", "吵闹": "语义：「吵闹」是喧哗，与「少犯错误」没有因果联系，句意不通。"}, "sentence_index": 0, "correct_answer": "自制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头很难自制。", "explanation": "这里应该用〈搬动〉。自制的主语只能是人，石头管不住自己，应说很难搬动。"}, {"text": "他很快自制住了局面。", "explanation": "这里应该用〈控制〉。自制只指约束自己，不能用来指控制局面。"}, {"text": "他总是自制地抢别人的东西。", "explanation": "这里应该用〈随便〉。自制指克制自己，不能修饰“抢别人的东西”这类失去约束的行为，表示行为随意要说随便。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23274, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自制", "is_correct": true, "explanation": "正确。“大人也要自制”指管住自己，与“不能总发脾气”相呼应。"}, {"text": "撒谎", "is_correct": false, "explanation": "语义：“撒谎”与“不能总发脾气”的劝诫语境不相关，句子读成了劝人撒谎。"}, {"text": "失控", "is_correct": false, "explanation": "语义：“失控”与“不能总发脾气”的要求相反，读起来自相矛盾。"}, {"text": "伤害", "is_correct": false, "explanation": "语义：「伤害」指损害他人，与「不能总发脾气」的劝诫语境不符，句子读不通。"}], "explanations": {"自制": "正确。“大人也要自制”指管住自己，与“不能总发脾气”相呼应。", "撒谎": "语义：“撒谎”与“不能总发脾气”的劝诫语境不相关，句子读成了劝人撒谎。", "失控": "语义：“失控”与“不能总发脾气”的要求相反，读起来自相矛盾。", "伤害": "语义：「伤害」指损害他人，与「不能总发脾气」的劝诫语境不符，句子读不通。"}, "sentence_index": 6, "correct_answer": "自制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一见到蛇就很自制地大哭起来。", "explanation": "这里应该用〈害怕〉。自制指克制自己，与“大哭”的失控反应相矛盾，表示恐惧要说害怕。"}, {"text": "他很会自制孩子。", "explanation": "这里应该用〈照顾〉。自制只能约束自己，不能以他人为对象。"}, {"text": "他拒绝了朋友的邀请，还把朋友自制住了。", "explanation": "这里应该用〈拦住〉。自制只能约束自己，不能以别人为对象，应说拦住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23274, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想多玩一会儿，但最后还是自制了住。", "corrected_sentence": "他想多玩一会儿，但最后还是自制住了。", "error_description": "错误：“了”放错了位置。结果补语“住”要先于“了”，应说“自制住了”，不能说“自制了住”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23274, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他想说话，但最后还是把自制住了。", "corrected_sentence": "他想说话，但最后还是自制住了。", "error_description": "错误：多加了“把”。“把”字句需要宾语，“自制住了”后没有宾语，应删去“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
