INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23280, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "很多人挤在一起。", "primary_collocate": null, "pronunciation": "yōng jǐ", "ipa": "jʊŋ˥ tɕi˨˩˦", "syllable_count": 2, "sentences": [{"text": "大家都拥挤在门口，想早点进去。", "target_word": "拥挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，学生们拥挤着走出教室。", "target_word": "拥挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日的早上，很多人拥挤在车站里。", "target_word": "拥挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家不要拥挤，排好队。", "target_word": "拥挤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人们拥挤在小店门前买东西。", "target_word": "拥挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们拥挤在窗边看雪。", "target_word": "拥挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "顾客们拥挤在商店门口。", "target_word": "拥挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家不要拥挤，一个一个上车。", "target_word": "拥挤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球迷们拥挤在体育场外面等着进去。", "target_word": "拥挤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁到站了，乘客们拥挤着往外走。", "target_word": "拥挤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拥挤着", "label": "体标"}], "register": "中性", "sense_fingerprint": "很多人一起挤在某个地方的动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fc364ef-91e2-4a9c-a8b0-536cd27ed751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23280, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拥挤", "is_correct": true, "explanation": "拥挤：很多人挤在一起，与“大家都在门口、想早点进去”的语境相符。"}, {"text": "散开", "is_correct": false, "explanation": "语义：“散开”指向四处分开，与人们聚在门口想早点进去的语境矛盾。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”指悠闲地走动，与人们挤在门口想早点进去的语境不符。"}, {"text": "休息", "is_correct": false, "explanation": "搭配：“休息在门口”不是自然说法，而且与“想早点进去”的语义不协调。"}], "explanations": {"拥挤": "拥挤：很多人挤在一起，与“大家都在门口、想早点进去”的语境相符。", "散开": "语义：“散开”指向四处分开，与人们聚在门口想早点进去的语境矛盾。", "散步": "语义：“散步”指悠闲地走动，与人们挤在门口想早点进去的语境不符。", "休息": "搭配：“休息在门口”不是自然说法，而且与“想早点进去”的语义不协调。"}, "sentence_index": 0, "correct_answer": "拥挤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个人拥挤在角落里，吃着面包。", "explanation": "这里应该用〈蜷缩〉。“拥挤”指很多人挤在一起，只有一个人时不能用“拥挤”。"}, {"text": "大家按顺序拥挤上车。", "explanation": "这里应该用〈排队〉。“拥挤”指杂乱地挤在一起，不能和“按顺序”搭配，应说“排队”。"}, {"text": "街上只有我们两个人，却显得很拥挤。", "explanation": "这里应该用〈空旷〉。“拥挤”指很多人挤在一起，街上只有两人却说拥挤，应说“空旷”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23280, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拥挤", "is_correct": true, "explanation": "拥挤：很多人挤在一起，与“顾客们在商店门口”的语境相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：顾客在商店门口“睡觉”与购物的语境不符，句子意思明显不对。"}, {"text": "跑步", "is_correct": false, "explanation": "搭配：“跑步”是个人运动，不用来描写一群人聚在商店门口的状态。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”需要水域，与商店门口的场景完全不符。"}], "explanations": {"拥挤": "拥挤：很多人挤在一起，与“顾客们在商店门口”的语境相符。", "睡觉": "语义：顾客在商店门口“睡觉”与购物的语境不符，句子意思明显不对。", "跑步": "搭配：“跑步”是个人运动，不用来描写一群人聚在商店门口的状态。", "游泳": "语义：“游泳”需要水域，与商店门口的场景完全不符。"}, "sentence_index": 6, "correct_answer": "拥挤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "广场上很拥挤，一个人也没有。", "explanation": "这里应该用〈空旷〉。“拥挤”指人多、空间小，和“一个人也没有”矛盾。"}, {"text": "下水道拥挤了，水流不下去。", "explanation": "这里应该用〈堵塞〉。“拥挤”指人或车辆密集，不能用来形容管道不通。"}, {"text": "垃圾拥挤在路边，没有人来清理。", "explanation": "这里应该用〈堆积〉。“拥挤”指人群挤在一起，不用来形容垃圾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23280, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家拥挤了在车门口，都想先上车。", "corrected_sentence": "大家拥挤在车门口，都想先上车。", "error_description": "错误：“拥挤”表示持续的动作状态，后面不能加“了”再接处所词。应去掉“了”，说“拥挤在车门口”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23280, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "观众们拥挤入口，等着检票。", "corrected_sentence": "观众们拥挤在入口，等着检票。", "error_description": "错误：“拥挤”后面表示处所时要用介词“在”，应说“拥挤在入口”，不说“拥挤入口”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
