INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23288, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "心里感到的样子，比如开心或者难过。", "primary_collocate": null, "pronunciation": "xīn qíng", "ipa": "ɕin˥˥ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "放假了，大家的心情都很好。", "target_word": "心情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今天心情不太好，一直不说话。", "target_word": "心情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想知道你现在是什么心情。", "target_word": "心情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈生病了，我的心情很难过。", "target_word": "心情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收到礼物，他的心情马上变好了。", "target_word": "心情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的心情我能明白。", "target_word": "心情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出去走一走，心情会轻松一点儿。", "target_word": "心情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看起来心情很不错。", "target_word": "心情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班回家路上，我的心情很愉快。", "target_word": "心情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把坏心情带回家。", "target_word": "心情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "好心情", "label": "复合"}, {"form": "坏心情", "label": "复合"}], "register": "中性", "sense_fingerprint": "心情：心里开心或难过的感觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fc364ef-91e2-4a9c-a8b0-536cd27ed751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23288, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "心情", "is_correct": true, "explanation": "心情指心里开心或难过的感觉，是本词的读音与词义。"}, {"text": "心惊", "is_correct": false, "explanation": "jīng 与 qíng 声母、声调都不同，意思是受惊、害怕。"}, {"text": "心形", "is_correct": false, "explanation": "xíng 与 qíng 只有声母不同（x 与 q），声调相同，意思是心的形状。"}, {"text": "性情", "is_correct": false, "explanation": "xìngqíng 的首音节 xìng 与 xīn 韵母不同（ing 与 in），声调也不同，意思是性格、脾气。"}], "explanations": {"心情": "心情指心里开心或难过的感觉，是本词的读音与词义。", "心惊": "jīng 与 qíng 声母、声调都不同，意思是受惊、害怕。", "心形": "xíng 与 qíng 只有声母不同（x 与 q），声调相同，意思是心的形状。", "性情": "xìngqíng 的首音节 xìng 与 xīn 韵母不同（ing 与 in），声调也不同，意思是性格、脾气。"}, "sentence_index": null, "correct_answer": "心情"}, "level_3": {"options": [{"text": "心情", "is_correct": true, "explanation": "此处“心情”指心里的感受，与“放假了，大家的……都很好”语境一致。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不会有“很好”的心里感受，“大家的月亮都很好”说不通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是心里的感受，“大家的天空都很好”语义不通。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：“大家的……都很好”不与“河流”搭配，这样说不通。"}], "explanations": {"心情": "此处“心情”指心里的感受，与“放假了，大家的……都很好”语境一致。", "月亮": "语义：月亮不会有“很好”的心里感受，“大家的月亮都很好”说不通。", "天空": "语义：天空不是心里的感受，“大家的天空都很好”语义不通。", "河流": "搭配：“大家的……都很好”不与“河流”搭配，这样说不通。"}, "sentence_index": 0, "correct_answer": "心情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她对工作的心情很专业。", "explanation": "这里应该用〈态度〉。“专业”形容做事的水平，“心情”指暂时的情绪，不能这样说。"}, {"text": "这位医生很重视病人的心情健康。", "explanation": "这里应该用〈心理〉。“心理健康”指心理状态良好；“心情”是暂时的情绪，不说“健康”。"}, {"text": "他有一条心情。", "explanation": "量词错误：“条”用于细长的东西，“心情”应用“种”，如“一种心情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23288, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "心情", "is_correct": true, "explanation": "心情指心里开心或难过的感觉，是本词的读音与词义。"}, {"text": "心灵", "is_correct": false, "explanation": "líng 与 qíng 只有声母不同（l 与 q），声调相同，意思是心灵、精神。"}, {"text": "亲情", "is_correct": false, "explanation": "qīn 与 xīn 只有声母不同（q 与 x），意思是亲人之间的感情。"}, {"text": "辛勤", "is_correct": false, "explanation": "qín 与 qíng 只差韵尾（n 与 ng），意思是勤劳。"}, {"text": "心性", "is_correct": false, "explanation": "xìng 与 qíng 声母不同（x 与 q），声调也不同，意思是心地、性情。"}], "explanations": {"心情": "心情指心里开心或难过的感觉，是本词的读音与词义。", "心灵": "líng 与 qíng 只有声母不同（l 与 q），声调相同，意思是心灵、精神。", "亲情": "qīn 与 xīn 只有声母不同（q 与 x），意思是亲人之间的感情。", "辛勤": "qín 与 qíng 只差韵尾（n 与 ng），意思是勤劳。", "心性": "xìng 与 qíng 声母不同（x 与 q），声调也不同，意思是心地、性情。"}, "sentence_index": null, "correct_answer": "心情"}, "level_3": {"options": [{"text": "心情", "is_correct": true, "explanation": "此处“心情”是主语，指心里的感受，与“会轻松一点儿”搭配。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子没有心情，“桌子会轻松一点儿”语义不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有心理感受，“石头会轻松一点儿”说不通。"}, {"text": "大海", "is_correct": false, "explanation": "搭配：“会轻松一点儿”不与“大海”搭配，这样说不通。"}], "explanations": {"心情": "此处“心情”是主语，指心里的感受，与“会轻松一点儿”搭配。", "桌子": "语义：桌子没有心情，“桌子会轻松一点儿”语义不通。", "石头": "语义：石头没有心理感受，“石头会轻松一点儿”说不通。", "大海": "搭配：“会轻松一点儿”不与“大海”搭配，这样说不通。"}, "sentence_index": 6, "correct_answer": "心情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子的心情很外向。", "explanation": "这里应该用〈性格〉。“外向”描述人的性格，心情只是暂时的情绪，不能说“外向”。"}, {"text": "他对家乡的心情很深。", "explanation": "这里应该用〈感情〉。“感情很深”指长期的情感，“心情”是暂时的情绪，不说“深”。"}, {"text": "他心里有一根心情。", "explanation": "量词错误：“根”用于细长的东西，“心情”应用“种”，不能说“一根心情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23288, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "看到这样的场景，我有一只很温暖的心情。", "corrected_sentence": "看到这样的场景，我有一种很温暖的心情。", "error_description": "量词错误：“心情”前应用“种”（一种心情），“只”用于动物或成对的物品，不能用于心情。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23288, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次考试以后，我的心情好下来了。", "corrected_sentence": "这次考试以后，我的心情好起来了。", "error_description": "补语错误：表示心情变好的开始要说“好起来”，不能说“好下来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
