INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23290, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "花是长在植物上、有颜色和香味的东西。", "primary_collocate": null, "pronunciation": "huā", "ipa": "xwa˥", "syllable_count": 1, "sentences": [{"text": "这种花很香。", "target_word": "花", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "窗外的花红红的，闻起来很香。", "target_word": "花", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小女孩手里拿着一朵花。", "target_word": "花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家阳台上有几盆花。", "target_word": "花", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这朵花又大又香，颜色也漂亮。", "target_word": "花", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过生日的时候，朋友送给我一束花。", "target_word": "花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花谢了以后，树上长出了果子。", "target_word": "花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天给花浇水。", "target_word": "花", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蝴蝶停在那朵花上。", "target_word": "花", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天到了，山上的花都开了。", "target_word": "花", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "朵", "label": "量词"}, {"form": "盆", "label": "量词"}, {"form": "花朵", "label": "复合"}, {"form": "花园", "label": "复合"}], "register": "中性", "sense_fingerprint": "长在植物上、有颜色和香味的花", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T1: 3 words above tier T1 (max 2): 树上 (Zipf 3.82), 长出 (Zipf 3.18), 果子 (Zipf 3.45)']::text[], '3fc364ef-91e2-4a9c-a8b0-536cd27ed751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23290, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "花", "is_correct": true, "explanation": "花（huā）指长在植物上、有颜色和香味的东西，是本词的读音与词义。"}, {"text": "画", "is_correct": false, "explanation": "huà（第四声）与 huā（第一声）声调不同，意思是图画。"}, {"text": "瓜", "is_correct": false, "explanation": "guā 与 huā 只有声母不同（g 与 h），意思是瓜类。"}, {"text": "夸", "is_correct": false, "explanation": "kuā 与 huā 只有声母不同（k 与 h），意思是夸奖。"}, {"text": "滑", "is_correct": false, "explanation": "huá（第二声）与 huā（第一声）声调不同，意思是光滑。"}], "explanations": {"花": "花（huā）指长在植物上、有颜色和香味的东西，是本词的读音与词义。", "画": "huà（第四声）与 huā（第一声）声调不同，意思是图画。", "瓜": "guā 与 huā 只有声母不同（g 与 h），意思是瓜类。", "夸": "kuā 与 huā 只有声母不同（k 与 h），意思是夸奖。", "滑": "huá（第二声）与 huā（第一声）声调不同，意思是光滑。"}, "sentence_index": null, "correct_answer": "花"}, "level_3": {"options": [{"text": "花", "is_correct": true, "explanation": "此处“花”指植物的花，有香味，与“很香”搭配。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有香味，“这种石头很香”说不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会散发香味，不能用“很香”描述。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：“很香”不与“玻璃”搭配，这样说不通。"}], "explanations": {"花": "此处“花”指植物的花，有香味，与“很香”搭配。", "石头": "语义：石头没有香味，“这种石头很香”说不通。", "桌子": "语义：桌子不会散发香味，不能用“很香”描述。", "玻璃": "搭配：“很香”不与“玻璃”搭配，这样说不通。"}, "sentence_index": 0, "correct_answer": "花"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家阳台上的花每天早上七点就跑去学校上课。", "explanation": "这里应该用〈孩子〉。“跑去学校上课”的主语是人，“花”指植物的花朵，不能去学校。"}, {"text": "那盆花又快又灵活，一下子就跑到了屋顶上。", "explanation": "这里应该用〈猫〉。“跑到屋顶上”是动物的动作，“花”指植物的花朵，不能用来指动物。"}, {"text": "窗台上的花昨天给我写了一封信，说它很想念我。", "explanation": "这里应该用〈朋友〉。“写信、想念”的主语是人，“花”指植物的花朵，不能作这类动作的主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23290, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "花", "is_correct": true, "explanation": "花（huā）指长在植物上、有颜色和香味的东西，是本词的读音与词义。"}, {"text": "华", "is_correct": false, "explanation": "huá（第二声）与 huā（第一声）声调不同，意思是中华、华丽。"}, {"text": "化", "is_correct": false, "explanation": "huà（第四声）与 huā 声调不同，意思是变化。"}, {"text": "话", "is_correct": false, "explanation": "huà（第四声）与 huā 声调不同，意思是话语。"}, {"text": "挂", "is_correct": false, "explanation": "guà 与 huā 声母、声调都不同，意思是悬挂。"}], "explanations": {"花": "花（huā）指长在植物上、有颜色和香味的东西，是本词的读音与词义。", "华": "huá（第二声）与 huā（第一声）声调不同，意思是中华、华丽。", "化": "huà（第四声）与 huā 声调不同，意思是变化。", "话": "huà（第四声）与 huā 声调不同，意思是话语。", "挂": "guà 与 huā 声母、声调都不同，意思是悬挂。"}, "sentence_index": null, "correct_answer": "花"}, "level_3": {"options": [{"text": "花", "is_correct": true, "explanation": "此处“花”是主语，“花谢”指花朵凋落，与“谢”搭配。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“谢”用于花朵凋落，不能说“雨谢了”。"}, {"text": "孩子", "is_correct": false, "explanation": "语义：孩子不会“谢”，“孩子谢了以后”语义不通。"}, {"text": "火焰", "is_correct": false, "explanation": "语义：火焰熄灭，不说“谢”，这里说不通。"}], "explanations": {"花": "此处“花”是主语，“花谢”指花朵凋落，与“谢”搭配。", "雨": "搭配：“谢”用于花朵凋落，不能说“雨谢了”。", "孩子": "语义：孩子不会“谢”，“孩子谢了以后”语义不通。", "火焰": "语义：火焰熄灭，不说“谢”，这里说不通。"}, "sentence_index": 6, "correct_answer": "花"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏天到了，桃树上结满了花。", "explanation": "这里应该用〈果子〉。“结”的对象是果实，花是开出来的，不能说“结花”。"}, {"text": "我家阳台上有一根花。", "explanation": "量词错误：“根”用于细长的东西，花应用“朵”“束”“盆”等，不能说“一根花”。"}, {"text": "妈妈买了一张花送给我。", "explanation": "量词错误：“张”用于平面的东西，花应用“朵”“束”等，不能说“一张花”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23290, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家阳台上摆着一个花。", "corrected_sentence": "我家阳台上摆着一盆花。", "error_description": "量词错误：“花”前应用“盆”（一盆花）或“朵”（一朵花），不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23290, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这朵花开的很大。", "corrected_sentence": "这朵花开得很大。", "error_description": "补语错误：表示程度的补语要用“得”，不能用“的”，应说“开得很大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23294, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "长", "is_correct": true, "explanation": "长：与“短”构成反义，指时间长久，与“这个假期太短”相对。"}, {"text": "宽", "is_correct": false, "explanation": "宽：与“窄”相对，不与“短”构成反义。"}, {"text": "高", "is_correct": false, "explanation": "高：与“低”相对，不与“短”构成反义。"}, {"text": "厚", "is_correct": false, "explanation": "厚：与“薄”相对，不与“短”构成反义。"}], "correct_answer": "长", "explanations": {"长": "长：与“短”构成反义，指时间长久，与“这个假期太短”相对。", "宽": "宽：与“窄”相对，不与“短”构成反义。", "高": "高：与“低”相对，不与“短”构成反义。", "厚": "厚：与“薄”相对，不与“短”构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23294, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "长", "is_correct": true, "explanation": "长：与“短”构成反义，指长度大，与“很短的裙子”相对。"}, {"text": "快", "is_correct": false, "explanation": "快：与“慢”相对，不与“短”构成反义。"}, {"text": "重", "is_correct": false, "explanation": "重：与“轻”相对，不与“短”构成反义。"}, {"text": "深", "is_correct": false, "explanation": "深：与“浅”相对，不与“短”构成反义。"}], "correct_answer": "长", "explanations": {"长": "长：与“短”构成反义，指长度大，与“很短的裙子”相对。", "快": "快：与“慢”相对，不与“短”构成反义。", "重": "重：与“轻”相对，不与“短”构成反义。", "深": "深：与“浅”相对，不与“短”构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23294, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "长度小，不长久。", "primary_collocate": null, "pronunciation": "duǎn", "ipa": "twan˨˩˦", "syllable_count": 1, "sentences": [{"text": "这条裤子太短了。", "target_word": "短", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的头发很短。", "target_word": "短", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "冬天白天短，晚上长。", "target_word": "短", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个假期太短，我哪里也没去。", "target_word": "短", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这根绳子太短，不够用。", "target_word": "短", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "人的一生很短，要做喜欢的事。", "target_word": "短", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路比那条短五百米。", "target_word": "短", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在这家公司工作的时间很短。", "target_word": "短", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次开会时间很短，十分钟就完了。", "target_word": "短", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她穿着一条很短的裙子。", "target_word": "短", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "短短", "label": "重叠"}, {"form": "短期", "label": "复合"}, {"form": "缩短", "label": "复合"}], "register": "中性", "sense_fingerprint": "短：长度小，时间不长久", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff9aa646-c282-401f-987c-01e17fcc7300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23294, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "短", "is_correct": true, "explanation": "短（第三声）：长度小，时间不长久。"}, {"text": "断", "is_correct": false, "explanation": "duàn（第四声）与 duǎn（第三声）声调不同，意思是切断、断开。"}, {"text": "端", "is_correct": false, "explanation": "duān（第一声）与 duǎn（第三声）声调不同，意思是端正、物体的一头。"}, {"text": "管", "is_correct": false, "explanation": "guǎn 与 duǎn 声母不同（g 与 d），意思是管子、管理。"}, {"text": "暖", "is_correct": false, "explanation": "nuǎn 与 duǎn 声母不同（n 与 d），意思是温暖。"}, {"text": "胆", "is_correct": false, "explanation": "dǎn 与 duǎn 韵母不同（少了 u 介音），意思是胆子。"}], "explanations": {"短": "短（第三声）：长度小，时间不长久。", "断": "duàn（第四声）与 duǎn（第三声）声调不同，意思是切断、断开。", "端": "duān（第一声）与 duǎn（第三声）声调不同，意思是端正、物体的一头。", "管": "guǎn 与 duǎn 声母不同（g 与 d），意思是管子、管理。", "暖": "nuǎn 与 duǎn 声母不同（n 与 d），意思是温暖。", "胆": "dǎn 与 duǎn 韵母不同（少了 u 介音），意思是胆子。"}, "sentence_index": null, "correct_answer": "短"}, "level_3": {"options": [{"text": "短", "is_correct": true, "explanation": "短：长度小，与“太……了”搭配，表示裤子不够长。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”形容人的心情，不能用来形容裤子。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的智力，不能用来形容裤子。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不能说裤子太甜。"}], "explanations": {"短": "短：长度小，与“太……了”搭配，表示裤子不够长。", "高兴": "语义：“高兴”形容人的心情，不能用来形容裤子。", "聪明": "语义：“聪明”形容人的智力，不能用来形容裤子。", "甜": "搭配：“甜”形容味道，不能说裤子太甜。"}, "sentence_index": 0, "correct_answer": "短"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小孩比同学短很多。", "explanation": "这里应该用〈矮〉。短指长度小，说人的身高低要用矮。"}, {"text": "学校离我家很短。", "explanation": "这里应该用〈近〉。短指长度或时间小，说距离远近要用近。"}, {"text": "这间房子很短。", "explanation": "这里应该用〈小〉。短指长度小，说房间的大小要用小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23294, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "短", "is_correct": true, "explanation": "短（第三声）：长度小，时间不长久。"}, {"text": "段", "is_correct": false, "explanation": "duàn（第四声）与 duǎn（第三声）声调不同，意思是段落、一段。"}, {"text": "软", "is_correct": false, "explanation": "ruǎn 与 duǎn 声母不同（r 与 d），意思是柔软。"}, {"text": "款", "is_correct": false, "explanation": "kuǎn 与 duǎn 声母不同（k 与 d），意思是款项、款式。"}], "explanations": {"短": "短（第三声）：长度小，时间不长久。", "段": "duàn（第四声）与 duǎn（第三声）声调不同，意思是段落、一段。", "软": "ruǎn 与 duǎn 声母不同（r 与 d），意思是柔软。", "款": "kuǎn 与 duǎn 声母不同（k 与 d），意思是款项、款式。"}, "sentence_index": null, "correct_answer": "短"}, "level_3": {"options": [{"text": "短", "is_correct": true, "explanation": "短：长度小，与“比那条……五百米”搭配，表示这条路更短。"}, {"text": "快", "is_correct": false, "explanation": "语义：“快”形容速度，不能用来表示五百米的长度差。"}, {"text": "重", "is_correct": false, "explanation": "搭配：“重”说重量，不用来比较路的长度，不能说重五百米。"}, {"text": "厚", "is_correct": false, "explanation": "语义：“厚”形容物体的厚度，不能用来比较两条路的长度。"}], "explanations": {"短": "短：长度小，与“比那条……五百米”搭配，表示这条路更短。", "快": "语义：“快”形容速度，不能用来表示五百米的长度差。", "重": "搭配：“重”说重量，不用来比较路的长度，不能说重五百米。", "厚": "语义：“厚”形容物体的厚度，不能用来比较两条路的长度。"}, "sentence_index": 6, "correct_answer": "短"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个班的学生很短，只有十个人。", "explanation": "这里应该用〈少〉。短指长度小，说人数多少要用少。"}, {"text": "这口井很短，绳子放下去也摸不到水。", "explanation": "这里应该用〈深〉。短指长度，井的深度要用深。"}, {"text": "这栋楼很短，站在楼下看不到顶。", "explanation": "这里应该用〈高〉。短指长度，建筑物的高度要用高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warning