INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23294, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件衬衫的袖子短很。", "corrected_sentence": "这件衬衫的袖子很短。", "error_description": "错误：“短很”。程度副词“很”要放在形容词前面，应为“很短”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23294, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了一根很短地带子。", "corrected_sentence": "我买了一根很短的带子。", "error_description": "错误：“很短地带子”。修饰名词“带子”要用“的”，“地”用于修饰动词，应为“很短的带子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '125344ee-cad4-462f-bb64-db511f3c68ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23296, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "恶劣", "is_correct": true, "explanation": "反义：“恶劣”与“良好”意义相反，指条件或品质很差，用于“天气”时正好相对。"}, {"text": "复杂", "is_correct": false, "explanation": "无关：“复杂”说构成繁多，与“良好”没有反义关系。"}, {"text": "巨大", "is_correct": false, "explanation": "无关：“巨大”说规模或程度大，与“良好”不是反义词。"}, {"text": "清晰", "is_correct": false, "explanation": "无关：“清晰”说清楚、分明，与“良好”没有反义关系。"}], "correct_answer": "恶劣", "explanations": {"恶劣": "反义：“恶劣”与“良好”意义相反，指条件或品质很差，用于“天气”时正好相对。", "复杂": "无关：“复杂”说构成繁多，与“良好”没有反义关系。", "巨大": "无关：“巨大”说规模或程度大，与“良好”不是反义词。", "清晰": "无关：“清晰”说清楚、分明，与“良好”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
