INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23296, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示一个人或事物让人满意或觉得不错。", "primary_collocate": null, "pronunciation": "liáng hǎo", "ipa": "liɑŋ˧˥ xɑʊ˧˩˦", "syllable_count": 2, "sentences": [{"text": "他给大家留下了良好的印象。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器目前运行良好。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的身体情况良好。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "良好的天气让比赛顺利进行。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子在学校表现良好。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的秩序一直良好。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们两家公司的合作非常良好。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有良好的工作习惯。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手术后，爷爷恢复良好。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理希望大家保持良好的状态。", "target_word": "良好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "良好：人或事物令人满意、不错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fc364ef-91e2-4a9c-a8b0-536cd27ed751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23296, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "良好", "is_correct": true, "explanation": "正确：“良好”形容给人的印象令人满意，与“留下了……的印象”搭配。"}, {"text": "鲜艳", "is_correct": false, "explanation": "搭配：“鲜艳”形容颜色，不能用来修饰“印象”。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”说空气或物体含水分多，不能用来修饰“印象”。"}, {"text": "漫长", "is_correct": false, "explanation": "语义：“漫长”说时间很长，不能用来修饰印象。"}], "explanations": {"良好": "正确：“良好”形容给人的印象令人满意，与“留下了……的印象”搭配。", "鲜艳": "搭配：“鲜艳”形容颜色，不能用来修饰“印象”。", "潮湿": "语义：“潮湿”说空气或物体含水分多，不能用来修饰“印象”。", "漫长": "语义：“漫长”说时间很长，不能用来修饰印象。"}, "sentence_index": 0, "correct_answer": "良好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她长得很良好，穿上这件裙子非常显眼。", "explanation": "这里应该用〈漂亮〉。良好不用来形容人的外貌。"}, {"text": "听到这个消息，他非常良好。", "explanation": "这里应该用〈激动〉。良好说事物或状况，不用来表示人的情绪。"}, {"text": "那是一段非常良好的时光。", "explanation": "这里应该用〈美好〉。良好说状况达到标准，形容时光和回忆的感受要用美好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23296, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "良好", "is_correct": true, "explanation": "正确：“良好”形容合作的状况令人满意，与“非常”搭配自然。"}, {"text": "漆黑", "is_correct": false, "explanation": "搭配：“漆黑”说光线或颜色，不能用来形容合作。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”说人的性格，不能用来形容两家公司的合作。"}, {"text": "笨重", "is_correct": false, "explanation": "语义：“笨重”说物体沉重、不灵活，不能用来形容合作。"}], "explanations": {"良好": "正确：“良好”形容合作的状况令人满意，与“非常”搭配自然。", "漆黑": "搭配：“漆黑”说光线或颜色，不能用来形容合作。", "懒惰": "语义：“懒惰”说人的性格，不能用来形容两家公司的合作。", "笨重": "语义：“笨重”说物体沉重、不灵活，不能用来形容合作。"}, "sentence_index": 6, "correct_answer": "良好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家得知比赛获胜后都很良好。", "explanation": "这里应该用〈快乐〉。良好不用来描述人的心情。"}, {"text": "他是一位良好的画家，作品很有名。", "explanation": "这里应该用〈伟大〉。良好不用来评价人的卓越成就。"}, {"text": "雨下得很良好，路面全湿了。", "explanation": "这里应该用〈大〉。“良好”说状况达到标准，不用来形容降雨的强弱，应说“下得很大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23296, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学生们良好的完成了作业。", "corrected_sentence": "学生们良好地完成了作业。", "error_description": "结构错误：“良好”作状语修饰动词“完成”要用“地”，应说“良好地完成”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23296, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家餐厅的服务态度很良好地。", "corrected_sentence": "这家餐厅的服务态度很良好。", "error_description": "结构错误：“良好”作谓语形容词时后面不加“地”，“地”只用于修饰动词，应说“很良好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
