INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23298, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地铁是跑在地下的火车，能带很多人去不同的地方。", "primary_collocate": null, "pronunciation": "dì tiě", "ipa": "ti˥˩ tʰje˨˩˦", "syllable_count": 2, "sentences": [{"text": "我每天坐地铁上班。", "target_word": "地铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁离我家很近，走路五分钟。", "target_word": "地铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上的地铁里人很多。", "target_word": "地铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐地铁去机场要一个小时。", "target_word": "地铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下了地铁，你往右走就到了。", "target_word": "地铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的地铁很方便。", "target_word": "地铁", "complexity_tier": "T3", "furigana": "zhè zuò chéngshì de dìtiě hěn fāngbiàn.", "sentence_source": "generated"}, {"text": "地铁比公共汽车快，也不堵车。", "target_word": "地铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在地铁上看书。", "target_word": "地铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "末班地铁十一点就开走了。", "target_word": "地铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我坐过一次北京的地铁。", "target_word": "地铁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "地铁站", "label": "复合词"}, {"form": "地铁线", "label": "复合词"}], "register": "中性", "sense_fingerprint": "城市里在地下行驶的轨道交通工具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d813a3-5c7c-4c35-a022-bcb120b67276') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23298, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地铁", "is_correct": true, "explanation": "地铁是城市里在地下行驶的交通工具，“我每天坐地铁上班”符合语境。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是家具，不是上班的交通工具，“坐沙发上班”不通。"}, {"text": "板凳", "is_correct": false, "explanation": "语义：板凳是坐具，不能用来通勤，句子不通。"}, {"text": "草地", "is_correct": false, "explanation": "搭配：“坐草地”不是交通方式，不能与“上班”搭配。"}], "explanations": {"地铁": "地铁是城市里在地下行驶的交通工具，“我每天坐地铁上班”符合语境。", "沙发": "语义：沙发是家具，不是上班的交通工具，“坐沙发上班”不通。", "板凳": "语义：板凳是坐具，不能用来通勤，句子不通。", "草地": "搭配：“坐草地”不是交通方式，不能与“上班”搭配。"}, "sentence_index": 0, "correct_answer": "地铁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市有一本地铁。", "explanation": "这里应该用〈条〉或〈列〉。地铁线路用“条”，车用“列”，不用“本”（多用于书）。"}, {"text": "我每天坐地铁上楼，很方便。", "explanation": "这里应该用〈电梯〉。电梯用于上下楼，地铁在地下沿轨道行驶，不能用来“上楼”。"}, {"text": "我住在地铁里。", "explanation": "这里应该用〈地下室〉。地下室是可以住人的房间，地铁是交通工具，不能用来居住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23298, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地铁", "is_correct": true, "explanation": "地铁可以与公共汽车比较速度，也可以说不堵车，符合语境。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是房间，不能与公共汽车比较快慢和交通状况。"}, {"text": "人行道", "is_correct": false, "explanation": "语义：人行道供人步行，不能与公共汽车比较速度。"}, {"text": "饮料", "is_correct": false, "explanation": "配价：“比”字句的主语应是可以比较的交通工具，饮料不能与公共汽车比较。"}], "explanations": {"地铁": "地铁可以与公共汽车比较速度，也可以说不堵车，符合语境。", "厨房": "语义：厨房是房间，不能与公共汽车比较快慢和交通状况。", "人行道": "语义：人行道供人步行，不能与公共汽车比较速度。", "饮料": "配价：“比”字句的主语应是可以比较的交通工具，饮料不能与公共汽车比较。"}, "sentence_index": 6, "correct_answer": "地铁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我下班后打了地铁回家。", "explanation": "这里应该用〈出租车〉。“打”用于出租车，地铁是公共交通，要说“坐地铁”，不能说“打地铁”。"}, {"text": "我感冒了，今天去地铁看病。", "explanation": "这里应该用〈医院〉。看病要去医院，地铁是交通工具，不能去“看病”。"}, {"text": "他把地铁骑来骑去。", "explanation": "这里应该用〈自行车〉。“骑”用于自行车、摩托车，地铁要说“坐”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23298, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天坐一张地铁上学。", "corrected_sentence": "他每天坐一列地铁上学。", "error_description": "“坐”地铁时，“地铁”的量词应用“列”，不用“张”。“张”用于平面的东西，错误形式是“一张地铁”，正确形式是“一列地铁”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23298, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们做地铁去了公园。", "corrected_sentence": "我们坐地铁去了公园。", "error_description": "错误：「地铁」要用动词「坐」，不能用「做」。错误形式是「做地铁」，正确形式是「坐地铁」。「做」不用于乘坐交通工具。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
