INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23300, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指一个地方。", "primary_collocate": null, "pronunciation": "dì diǎn", "ipa": "ti˥˩ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个地点很安静，适合看书。", "target_word": "地点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们换一个地点再聊吧。", "target_word": "地点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地点在山里，很难找到。", "target_word": "地点", "complexity_tier": "T3", "furigana": "zhè ge dì diǎn zài shān lǐ, hěn nán zhǎo dào。", "sentence_source": "generated"}, {"text": "旅行的地点由大家一起决定。", "target_word": "地点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个很适合野餐的地点。", "target_word": "地点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个地点太吵了，我们不想去。", "target_word": "地点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们找到了一个有山有水的地点，风景很好。", "target_word": "地点", "complexity_tier": "T3", "furigana": "wǒ men zhǎo dào le yí gè yǒu shān yǒu shuǐ de dì diǎn, fēng jǐng hěn hǎo。", "sentence_source": "generated"}, {"text": "请在地图上找一下这个地点。", "target_word": "地点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地点我以前来过，很漂亮。", "target_word": "地点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "约会的地点不要太远。", "target_word": "地点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "旅行地点", "label": "复合"}, {"form": "地點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "泛指一个地方，可以挑选、更换或在地图上找到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c3c5e83-a0c2-440b-9507-b34a7eadbfc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23300, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地点", "is_correct": true, "explanation": "正确。“这个地点”指一个地方，可以安静，适合看书。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指钱数，不能是安静、适合看书的地方。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：“早餐”是食物，不能说“安静，适合看书”。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“安静”一般不用来形容天气，“天气很安静，适合看书”不通。"}], "explanations": {"地点": "正确。“这个地点”指一个地方，可以安静，适合看书。", "价格": "语义：“价格”指钱数，不能是安静、适合看书的地方。", "早餐": "语义：“早餐”是食物，不能说“安静，适合看书”。", "天气": "搭配：“安静”一般不用来形容天气，“天气很安静，适合看书”不通。"}, "sentence_index": 0, "correct_answer": "地点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个信封的地点很贵。", "explanation": "这里应该用〈价格〉。说东西贵不贵要用“价格”，“地点”指一个地方，不指价钱。"}, {"text": "他的汉语已经提高到这个地点了。", "explanation": "这里应该用〈水平〉。语言能力的高低说“水平”，“提高到”说水平或程度，“地点”指一个地方，不能指水平。"}, {"text": "我们把约会的地点定在下午三点。", "explanation": "这里应该用〈时间〉。定在某个时刻要用“时间”，“地点”指一个地方，不指时刻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23300, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地点", "is_correct": true, "explanation": "正确。“一个有山有水的地点”指一处地方，风景好，符合句意。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”指时刻，不能是有山有水的，也不能被“找到”。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”是内心感受，不是可以找到的地方。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”只指人或动物的体形，不能形容地方。"}], "explanations": {"地点": "正确。“一个有山有水的地点”指一处地方，风景好，符合句意。", "时间": "语义：“时间”指时刻，不能是有山有水的，也不能被“找到”。", "心情": "语义：“心情”是内心感受，不是可以找到的地方。", "身材": "体貌：“身材”只指人或动物的体形，不能形容地方。"}, "sentence_index": 6, "correct_answer": "地点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的存款一年就涨到了这个地点。", "explanation": "这里应该用〈数额〉。存款增长到多少要说“数额”，“地点”指一个地方，不指金额。"}, {"text": "用这个地点来解决问题。", "explanation": "这里应该用〈方法〉。解决问题要说“用某种方法”，“地点”指一个地方，不指做事的方式。"}, {"text": "事情已经糟糕到这个地点了。", "explanation": "这里应该用〈地步〉。说情况糟到某种程度要用“地步”，“地点”指一个地方，不指程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23300, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把聚会的地点选湖边。", "corrected_sentence": "我们把聚会的地点选在湖边。", "error_description": "语法错误：“选”后带处所要用“选在”，说“把聚会的地点选在湖边”。漏掉“在”，说“选湖边”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23300, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们选了一条好地点。", "corrected_sentence": "我们选了一个好地点。", "error_description": "量词错误：“地点”应搭配量词“个”，说“一个好地点”；“条”用于线状事物，不能用于地点。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
