INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23302, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很多人住在一起的地方。", "primary_collocate": null, "pronunciation": "zhù zhái qū", "ipa": "tʂu˥˩ tʂaɪ˧˥ tɕʰy˥˥", "syllable_count": 3, "sentences": [{"text": "这个住宅区住着几千个人。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个住宅区的门口夜里有保安。", "target_word": "住宅区", "complexity_tier": "T3", "furigana": "zhù zhái qū", "sentence_source": "generated"}, {"text": "住宅区里的孩子常在一起玩儿。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸每天走路穿过住宅区去上班。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新住宅区的房子卖得很快。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住宅区中间有一个大花园。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个住宅区的邻居都很热情。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递员把包裹送到了住宅区。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城东有一个很大的住宅区。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住宅区里不能大声放音乐。", "target_word": "住宅区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "住宅區", "label": "繁体"}, {"form": "个", "label": "量词"}, {"form": "片", "label": "量词"}], "register": "中性", "sense_fingerprint": "住宅区：很多人聚居的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fc364ef-91e2-4a9c-a8b0-536cd27ed751') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23302, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "住宅区", "is_correct": true, "explanation": "正确：“住宅区”是很多人聚居的地方，与“住着几千个人”搭配。"}, {"text": "书店", "is_correct": false, "explanation": "语义：书店是卖书的场所，不是供几千人居住的地方。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园是供人游览的地方，不能用来居住。"}, {"text": "花瓶", "is_correct": false, "explanation": "搭配：“花瓶”是器物，不能与“住着几千个人”搭配。"}], "explanations": {"住宅区": "正确：“住宅区”是很多人聚居的地方，与“住着几千个人”搭配。", "书店": "语义：书店是卖书的场所，不是供几千人居住的地方。", "公园": "语义：公园是供人游览的地方，不能用来居住。", "花瓶": "搭配：“花瓶”是器物，不能与“住着几千个人”搭配。"}, "sentence_index": 0, "correct_answer": "住宅区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个住宅区的病床都住满了病人。", "explanation": "这里应该用〈医院〉。住宅区是供人居住的地方，住满病人、摆着病床的要说医院。"}, {"text": "我住的住宅区只有一间卧室。", "explanation": "这里应该用〈住宅〉。住宅区指很多人聚居的地方；只有一间卧室的要说住宅。"}, {"text": "这个住宅区的跑道很长，飞机起降不断。", "explanation": "这里应该用〈机场〉。住宅区是供人居住的地方，跑道、飞机起降的要说机场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23302, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "住宅区", "is_correct": true, "explanation": "正确：“住宅区”里住着很多人，邻居之间有往来，与“邻居都很热情”搭配。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，没有邻居，不能说“邻居都很热情”。"}, {"text": "衣柜", "is_correct": false, "explanation": "语义：衣柜是家具，没有邻居，不能这样说。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“的邻居”需要有人群居住的地方，汽车不能与之搭配。"}], "explanations": {"住宅区": "正确：“住宅区”里住着很多人，邻居之间有往来，与“邻居都很热情”搭配。", "钢琴": "语义：钢琴是乐器，没有邻居，不能说“邻居都很热情”。", "衣柜": "语义：衣柜是家具，没有邻居，不能这样说。", "汽车": "搭配：“的邻居”需要有人群居住的地方，汽车不能与之搭配。"}, "sentence_index": 6, "correct_answer": "住宅区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "住宅区的站台上挤满了旅客，列车正在进站。", "explanation": "这里应该用〈车站〉。住宅区是供人居住的地方，站台、列车进站的要说车站。"}, {"text": "住宅区的教室里坐满了学生，老师在讲课。", "explanation": "这里应该用〈学校〉。住宅区是供人居住的地方，有教室、老师讲课的要说学校。"}, {"text": "住宅区的跑道上有很多选手在比赛，观众席坐满了人。", "explanation": "这里应该用〈体育场〉。住宅区是居住场所，选手比赛、观众席的要说体育场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23302, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "城西新建了一只大型住宅区。", "corrected_sentence": "城西新建了一片大型住宅区。", "error_description": "量词错误：“住宅区”应用“片”或“个”，“只”用于动物或成对的物品，应说“一片大型住宅区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23302, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我舅舅住在一个很大住宅区里。", "corrected_sentence": "我舅舅住在一个很大的住宅区里。", "error_description": "结构错误：“很大”修饰名词“住宅区”时要加“的”，应说“一个很大的住宅区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46025e0-91a7-43ce-adc3-cceebf0e6ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23304, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "打击", "is_correct": true, "explanation": "打击与“鼓励”意思相反，指使人失去信心，是这一义项的反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步是日常活动，与“鼓励”没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡觉是作息行为，与“鼓励”没有反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "写字是书写动作，与“鼓励”没有反义关系。"}], "correct_answer": "打击", "explanations": {"打击": "打击与“鼓励”意思相反，指使人失去信心，是这一义项的反义关系。", "散步": "散步是日常活动，与“鼓励”没有反义关系。", "睡觉": "睡觉是作息行为，与“鼓励”没有反义关系。", "写字": "写字是书写动作，与“鼓励”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23304, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "打击", "is_correct": true, "explanation": "打击与“鼓励”意思相反，指使人失去信心，是这一义项的反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步是体育活动，与“鼓励”没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌是文娱活动，与“鼓励”没有反义关系。"}, {"text": "洗澡", "is_correct": false, "explanation": "洗澡是日常生活行为，与“鼓励”没有反义关系。"}], "correct_answer": "打击", "explanations": {"打击": "打击与“鼓励”意思相反，指使人失去信心，是这一义项的反义关系。", "跑步": "跑步是体育活动，与“鼓励”没有反义关系。", "唱歌": "唱歌是文娱活动，与“鼓励”没有反义关系。", "洗澡": "洗澡是日常生活行为，与“鼓励”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23304, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让别人觉得有信心、想去做一件事。", "primary_collocate": null, "pronunciation": "gǔ lì", "ipa": "ku˨˩˦ li˥˩", "syllable_count": 2, "sentences": [{"text": "老师鼓励我多说汉语。", "target_word": "鼓励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的话鼓励了我。", "target_word": "鼓励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈总是鼓励孩子自己做事。", "target_word": "鼓励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他考得不好，我们应该鼓励他。", "target_word": "鼓励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司鼓励大家骑车上班。", "target_word": "鼓励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球迷大声鼓励着运动员。", "target_word": "鼓励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸鼓励弟弟参加比赛。", "target_word": "鼓励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别批评他，多鼓励他吧。", "target_word": "鼓励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校鼓励学生每天读书。", "target_word": "鼓励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着鼓励我别怕，试试看。", "target_word": "鼓励", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "鼓励了", "label": "完成体"}, {"form": "鼓励着", "label": "持续体"}, {"form": "鼓励过", "label": "经历体"}, {"form": "鼓励鼓励", "label": "重叠"}], "register": "中性", "sense_fingerprint": "用话或行动给人信心，让人愿意去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d813a3-5c7c-4c35-a022-bcb120b67276') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23304, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "鼓励", "is_correct": true, "explanation": "正确答案。鼓励 gǔlì 指用话或行动给人信心，让人愿意去做事。"}, {"text": "努力", "is_correct": false, "explanation": "努力 nǔlì 与 gǔlì 声母不同（n 与 g），意思是尽力做事，不是给人信心。"}, {"text": "武力", "is_correct": false, "explanation": "武力 wǔlì 与 gǔlì 首音不同（w 与 g），意思是武装力量。"}, {"text": "苦力", "is_correct": false, "explanation": "苦力 kǔlì 与 gǔlì 声母不同（k 与 g），意思是出卖体力的劳动者。"}], "explanations": {"鼓励": "正确答案。鼓励 gǔlì 指用话或行动给人信心，让人愿意去做事。", "努力": "努力 nǔlì 与 gǔlì 声母不同（n 与 g），意思是尽力做事，不是给人信心。", "武力": "武力 wǔlì 与 gǔlì 首音不同（w 与 g），意思是武装力量。", "苦力": "苦力 kǔlì 与 gǔlì 声母不同（k 与 g），意思是出卖体力的劳动者。"}, "sentence_index": null, "correct_answer": "鼓励"}, "level_3": {"options": [{"text": "鼓励", "is_correct": true, "explanation": "鼓励指让学生有信心多说汉语，符合语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”与“我多说汉语”不能搭配，句子不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”不能带“我多说汉语”这样的宾语，句子不成立。"}, {"text": "写", "is_correct": false, "explanation": "配价：“写”的宾语应是文字或文章，不能直接接“我”作宾语。"}], "explanations": {"鼓励": "鼓励指让学生有信心多说汉语，符合语境。", "吃": "语义：“吃”与“我多说汉语”不能搭配，句子不通。", "唱": "语义：“唱”不能带“我多说汉语”这样的宾语，句子不成立。", "写": "配价：“写”的宾语应是文字或文章，不能直接接“我”作宾语。"}, "sentence_index": 0, "correct_answer": "鼓励"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他决定转学，我们应该鼓励他的决定。", "explanation": "这里应该用〈支持〉。对别人的决定表示赞成应说“支持”；“鼓励”强调让人有信心去做某事，不说“鼓励他的决定”。"}, {"text": "这个周末天气很好，我们应该鼓励这个天气。", "explanation": "这里应该用〈享受〉。“鼓励”是让人有信心去做事，不能用于天气，应说“享受这个天气”。"}, {"text": "我很同情他的遭遇，也很鼓励他的遭遇。", "explanation": "这里“鼓励”被当作“对遭遇表示关切、怜悯”的意思使用。“鼓励”指让人有信心去做事，不能用于遭遇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23304, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "鼓励", "is_correct": true, "explanation": "正确答案。鼓励 gǔlì 指用话或行动给人信心，让人愿意去做事。"}, {"text": "孤立", "is_correct": false, "explanation": "孤立 gūlì 与 gǔlì 第一个音节声调不同（第一声与第三声），意思是脱离群体、单独存在。"}, {"text": "主力", "is_correct": false, "explanation": "主力 zhǔlì 与 gǔlì 声母不同（zh 与 g），意思是主要的力量。"}, {"text": "古礼", "is_correct": false, "explanation": "古礼 gǔlǐ 与 gǔlì 第二个音节声调不同（第三声与第四声），意思是古代的礼仪。"}], "explanations": {"鼓励": "正确答案。鼓励 gǔlì 指用话或行动给人信心，让人愿意去做事。", "孤立": "孤立 gūlì 与 gǔlì 第一个音节声调不同（第一声与第三声），意思是脱离群体、单独存在。", "主力": "主力 zhǔlì 与 gǔlì 声母不同（zh 与 g），意思是主要的力量。", "古礼": "古礼 gǔlǐ 与 gǔlì 第二个音节声调不同（第三声与第四声），意思是古代的礼仪。"}, "sentence_index": null, "correct_answer": "鼓励"}, "level_3": {"options": [{"text": "鼓励", "is_correct": true, "explanation": "鼓励指让弟弟有信心去参加比赛，符合语境。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：打扫是清洁房间，不能用来指让弟弟参加比赛。"}, {"text": "熨", "is_correct": false, "explanation": "配价：熨的对象是衣物，不能接“弟弟”作宾语。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗弟弟参加比赛”搭配不通，句子不成立。"}], "explanations": {"鼓励": "鼓励指让弟弟有信心去参加比赛，符合语境。", "打扫": "语义：打扫是清洁房间，不能用来指让弟弟参加比赛。", "熨": "配价：熨的对象是衣物，不能接“弟弟”作宾语。", "洗": "语义：“洗弟弟参加比赛”搭配不通，句子不成立。"}, "sentence_index": 6, "correct_answer": "鼓励"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她笑着鼓励我撒谎，别怕。", "explanation": "这里应该用〈教唆〉。“鼓励”指让人有信心去做正面的事，用于撒谎这类不当行为时，应说“教唆”或“纵容”。"}, {"text": "这句话鼓励了他的感情。", "explanation": "这里应该用〈伤害〉。“鼓励”让人有信心，不能用于感情；这句话伤了他的感情，应说“伤害”。"}, {"text": "老师鼓励我们在课上吵闹。", "explanation": "这里应该用〈禁止〉。“鼓励”表示让人去做正面的事，课上吵闹应用“禁止”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23304, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们大声鼓励了着运动员。", "corrected_sentence": "同学们大声鼓励着运动员。", "error_description": "“鼓励”后面的“了”和“着”不能同时使用。表示持续状态只用“着”，错误形式是“鼓励了着”，正确形式是“鼓励着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23304, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师鼓励让我参加比赛。", "corrected_sentence": "老师鼓励我参加比赛。", "error_description": "错误：「鼓励」本身已含有“使人去做”的意思，后面不能再加「让」。错误形式是「鼓励让我」，正确形式是「鼓励我」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
