INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23308, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "自行车道是给自行车走的路。", "primary_collocate": null, "pronunciation": "zì xíng chē dào", "ipa": "tsɨ˥˩ ɕiŋ˧˥ ʈʂʰɤ˥ tau˥˩", "syllable_count": 4, "sentences": [{"text": "自行车道是给自行车走的路。", "target_word": "自行车道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校门口新画了一条自行车道。", "target_word": "自行车道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走路的人不要走自行车道。", "target_word": "自行车道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条自行车道很长，一直到河边。", "target_word": "自行车道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，自行车道上有很多水。", "target_word": "自行车道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢在河边的自行车道上骑车。", "target_word": "自行车道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路中间的自行车道用绿色标出来。", "target_word": "自行车道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里没有自行车道，骑车很危险。", "target_word": "自行车道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在自行车道上骑得很慢。", "target_word": "自行车道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府打算再修两条自行车道。", "target_word": "自行车道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "自行车道路", "label": "复合"}, {"form": "自行車道", "label": "繁体"}], "register": "中性", "sense_fingerprint": "给自行车走的路，行人和汽车不走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c3c5e83-a0c2-440b-9507-b34a7eadbfc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23308, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自行车道", "is_correct": true, "explanation": "正确。“自行车道”就是给自行车走的路，与定义相符。"}, {"text": "公交车", "is_correct": false, "explanation": "语义：“公交车”是车辆，不是给自行车走的路。"}, {"text": "停车场", "is_correct": false, "explanation": "语义：“停车场”是停放车辆的地方，不是走的路。"}, {"text": "行人", "is_correct": false, "explanation": "配价：“行人”是人，不能作“路”来说“是给自行车走的路”。"}], "explanations": {"自行车道": "正确。“自行车道”就是给自行车走的路，与定义相符。", "公交车": "语义：“公交车”是车辆，不是给自行车走的路。", "停车场": "语义：“停车场”是停放车辆的地方，不是走的路。", "行人": "配价：“行人”是人，不能作“路”来说“是给自行车走的路”。"}, "sentence_index": 0, "correct_answer": "自行车道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "飞机就在这条自行车道上起飞。", "explanation": "这里应该用〈跑道〉。飞机起降的道路叫“跑道”，自行车道是给自行车走的路，飞机不能在上面起飞。"}, {"text": "这条自行车道是给汽车开的。", "explanation": "这里应该用〈机动车道〉。自行车道供自行车行驶，汽车应走机动车道。"}, {"text": "这条自行车道用来停汽车。", "explanation": "这里应该用〈停车场〉。自行车道供骑行，不作停车用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23308, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自行车道", "is_correct": true, "explanation": "正确。“路中间的自行车道用绿色标出来”指路上的专用车道被标出，符合句意。"}, {"text": "交警", "is_correct": false, "explanation": "语义：“交警”是人，不能用绿色标在路上，句意不通。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：“食堂”是室内的建筑，不能说“路中间的食堂用绿色标出来”，句意不通。"}, {"text": "路人", "is_correct": false, "explanation": "配价：“路人”是人，不是可以用颜色标出来的东西。"}], "explanations": {"自行车道": "正确。“路中间的自行车道用绿色标出来”指路上的专用车道被标出，符合句意。", "交警": "语义：“交警”是人，不能用绿色标在路上，句意不通。", "食堂": "语义：“食堂”是室内的建筑，不能说“路中间的食堂用绿色标出来”，句意不通。", "路人": "配价：“路人”是人，不是可以用颜色标出来的东西。"}, "sentence_index": 6, "correct_answer": "自行车道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们在这条自行车道上跳舞。", "explanation": "这里应该用〈广场〉。在开阔处跳舞要说“广场”，“自行车道”是给自行车走的路，不能用来跳舞。"}, {"text": "这些自行车道专门给行人走。", "explanation": "这里应该用〈人行道〉。自行车道供自行车行驶，行人走的是人行道。"}, {"text": "这条自行车道上有很多商店。", "explanation": "这里应该用〈步行街〉。商店集中、供行人购物的是“步行街”，“自行车道”只供自行车行驶，不能说上面有商店。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23308, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公园门口的一个自行车道被车堵住了。", "corrected_sentence": "公园门口的一条自行车道被车堵住了。", "error_description": "量词错误：“自行车道”是线状道路，应搭配量词“条”，说“一条自行车道”；“个”不能用于道路。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23308, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市政府把自行车道设河边。", "corrected_sentence": "市政府把自行车道设在河边。", "error_description": "语法错误：“设”带处所宾语时要说“设在”，即“把自行车道设在河边”。漏掉“在”，说“设河边”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
