INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23314, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23314, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "是列车停靠的地方，人们可以在这里上车或下车。", "primary_collocate": null, "pronunciation": "dì tiě zhàn", "ipa": "ti˥˩ tʰjɛ˨˩˦ ʈʂan˥˩", "syllable_count": 3, "sentences": [{"text": "车到了地铁站，门一开，人们就下车了。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们约好八点在地铁站见面。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁站的牌子上写着站名。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天早上走到地铁站坐车上班。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在地铁站等车，手里拿着一杯咖啡。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地铁站很干净，也很安全。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁站里有地铁线路图，你可以先看看。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下车以后，我在地铁站里找到了出口。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末地铁站里有很多去玩的人。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的地铁站离公园很近，去玩很方便。", "target_word": "地铁站", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "地铁站台", "label": "复合"}, {"form": "地鐵站", "label": "繁体"}], "register": "中性", "sense_fingerprint": "列车停靠、人们上下车的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c3c5e83-a0c2-440b-9507-b34a7eadbfc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23314, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地铁站", "is_correct": true, "explanation": "正确：列车停靠、乘客上下车的地方，与“车到了……门一开”的语境一致。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：车不会开到厨房，“车到了”后接的应是停靠点。"}, {"text": "卧室", "is_correct": false, "explanation": "语义：车不能开进卧室，与句意相矛盾。"}, {"text": "旅客", "is_correct": false, "explanation": "配价：“车到了”要求处所作宾语，“旅客”是人，不能作为停靠的地点。"}], "explanations": {"地铁站": "正确：列车停靠、乘客上下车的地方，与“车到了……门一开”的语境一致。", "厨房": "语义：车不会开到厨房，“车到了”后接的应是停靠点。", "卧室": "语义：车不能开进卧室，与句意相矛盾。", "旅客": "配价：“车到了”要求处所作宾语，“旅客”是人，不能作为停靠的地点。"}, "sentence_index": 0, "correct_answer": "地铁站"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个地铁站从市中心一直修到了郊区。", "explanation": "这里应该用〈地铁线〉。“修到郊区”说的是线路，地铁站只是一个站点，不能这样说。"}, {"text": "我每天早上坐地铁站上班。", "explanation": "这里应该用〈列车〉。“坐”的对象是列车等交通工具，地铁站是停靠点，不能坐。"}, {"text": "他骑着地铁站去上班。", "explanation": "这里应该用〈自行车〉。“骑”的对象是自行车、摩托车等可以骑的车，地铁站是站点，不能骑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23314, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地铁站", "is_correct": true, "explanation": "正确：地铁站内张贴线路图，与句意相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱里不会有地铁线路图，句意不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头里放不下线路图，与句意相矛盾。"}, {"text": "老师", "is_correct": false, "explanation": "配价：“里”要求处所，“老师”是人，不能作为存放线路图的地方。"}], "explanations": {"地铁站": "正确：地铁站内张贴线路图，与句意相符。", "冰箱": "语义：冰箱里不会有地铁线路图，句意不通。", "石头": "语义：石头里放不下线路图，与句意相矛盾。", "老师": "配价：“里”要求处所，“老师”是人，不能作为存放线路图的地方。"}, "sentence_index": 6, "correct_answer": "地铁站"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他沿着地铁站走了三公里。", "explanation": "这里应该用〈地铁线〉。“沿着……走”指沿路线行走，地铁站是一个点，不是路线。"}, {"text": "这个地铁站停在了三楼。", "explanation": "这里应该用〈电梯〉。“停”可用于电梯，地铁站是车站，不能停在某一楼层。"}, {"text": "他开着地铁站去上班。", "explanation": "这里应该用〈汽车〉。“开”的对象是车辆，地铁站是车站，不能开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23314, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们坐的车到了一辆地铁站，门一开大家就下车了。", "corrected_sentence": "我们坐的车到了一个地铁站，门一开大家就下车了。", "error_description": "量词错误：“地铁站”应使用量词“个”，不能用“辆”（“辆”用于车辆）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23314, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在一条地铁站门口等我。", "corrected_sentence": "他在一个地铁站门口等我。", "error_description": "量词错误：“地铁站”应使用量词“个”，不能用“条”（“条”用于狭长的事物）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
