INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23318, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "坐完一种车，再坐另一种车。", "primary_collocate": null, "pronunciation": "huàn chéng", "ipa": "xwan˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "先坐公交车，再换乘地铁，就能到学校。", "target_word": "换乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里可以换乘去机场的车。", "target_word": "换乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢换乘，最好能一次坐到终点。", "target_word": "换乘", "complexity_tier": "T3", "furigana": "wǒ bù xǐhuan huànchéng, zuìhǎo néng yí cì zuòdào zhōngdiǎn.", "sentence_source": "generated"}, {"text": "下了火车，我又换乘了一辆大巴。", "target_word": "换乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，去动物园要在哪里换乘？", "target_word": "换乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "换乘需要走一段路，大概十分钟。", "target_word": "换乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友告诉我，三号线可以换乘五号线。", "target_word": "换乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带着孩子换乘，所以走得很慢。", "target_word": "换乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在这一站下车，然后换乘公交。", "target_word": "换乘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机地图说，我们得换乘两次才能到。", "target_word": "换乘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "换乘了", "label": "体标"}, {"form": "换乘站", "label": "复合"}, {"form": "換乘", "label": "繁体"}], "register": "中性", "sense_fingerprint": "先坐一种车，下车后再坐另一种车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c3c5e83-a0c2-440b-9507-b34a7eadbfc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23318, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "换乘", "is_correct": true, "explanation": "“换乘”指先坐一种车，再换坐另一种车，符合“先坐公交车，再……地铁”的语境。"}, {"text": "驾驶", "is_correct": false, "explanation": "语义：“驾驶”指操纵车辆，而句中的人是乘客，“驾驶地铁”句意不通。"}, {"text": "修补", "is_correct": false, "explanation": "语义：“修补”指修复破损的东西，与“坐车到学校”的语境无关，句意不通。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”需要可买的商品作宾语，地铁是服务，不能说购买地铁。"}], "explanations": {"换乘": "“换乘”指先坐一种车，再换坐另一种车，符合“先坐公交车，再……地铁”的语境。", "驾驶": "语义：“驾驶”指操纵车辆，而句中的人是乘客，“驾驶地铁”句意不通。", "修补": "语义：“修补”指修复破损的东西，与“坐车到学校”的语境无关，句意不通。", "购买": "搭配：“购买”需要可买的商品作宾语，地铁是服务，不能说购买地铁。"}, "sentence_index": 0, "correct_answer": "换乘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天在学校门口换乘我回家。", "explanation": "这里应该用〈接〉。“换乘”指乘客更换交通工具，不能用于接送人。"}, {"text": "我把旧手机换乘了新的。", "explanation": "此处指更换物品，但“换乘”只用于乘车时在交通工具之间转换。"}, {"text": "我们在会议上换乘了意见。", "explanation": "此处指交换看法，但“换乘”只指交通工具之间的转换，不能用于意见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23318, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "换乘", "is_correct": true, "explanation": "“换乘”指在两条线路之间换车，符合“三号线可以换乘五号线”的语境。"}, {"text": "拥有", "is_correct": false, "explanation": "语义：“拥有”指占有某物，不能说线路之间可以拥有，句意不通。"}, {"text": "欢迎", "is_correct": false, "explanation": "配价：“欢迎”的对象是人或来客，不能以线路作宾语，句子不通。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修复坏掉的物件，与线路之间的换乘无关，句意不通。"}], "explanations": {"换乘": "“换乘”指在两条线路之间换车，符合“三号线可以换乘五号线”的语境。", "拥有": "语义：“拥有”指占有某物，不能说线路之间可以拥有，句意不通。", "欢迎": "配价：“欢迎”的对象是人或来客，不能以线路作宾语，句子不通。", "修理": "语义：“修理”指修复坏掉的物件，与线路之间的换乘无关，句意不通。"}, "sentence_index": 6, "correct_answer": "换乘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这辆车换乘给了朋友。", "explanation": "此处指转让物品，但“换乘”只用于乘客在交通工具之间转换，不能用于转让。"}, {"text": "我们换乘了一下座位。", "explanation": "此处指调换座位，但“换乘”只用于交通工具之间的转换，不能用于座位。"}, {"text": "这场比赛，教练换乘了主力队员。", "explanation": "此处指替换队员，但“换乘”只用于交通工具之间的转换，不能用于人员替换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23318, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在深圳北站换乘一本地铁去机场。", "corrected_sentence": "他在深圳北站换乘一班地铁去机场。", "error_description": "量词错误：“地铁”不能用量词“本”（“本”用于书册）。应使用“班”或“列”，正确形式是“换乘一班地铁”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23318, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朋友说，去机场要在东站换乘了一次。", "corrected_sentence": "朋友说，去机场要在东站换乘一次。", "error_description": "时态矛盾：“要”表示将来，而“了”表示已完成，“换乘了一次”与将来语境冲突；应去掉“了”，改为“要换乘一次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd44805a8-1132-420f-ba64-f300448752ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23320, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短暂", "is_correct": true, "explanation": "反义：“短暂”指时间很短、持续不久，与“长远”的持续很久相反。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：“清楚”指明白、分明，与“长远”没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "无关：“热闹”形容场面或气氛，与“长远”的时间意义无关。"}, {"text": "复杂", "is_correct": false, "explanation": "无关：“复杂”指事物头绪多，与“长远”不构成反义。"}], "correct_answer": "短暂", "explanations": {"短暂": "反义：“短暂”指时间很短、持续不久，与“长远”的持续很久相反。", "清楚": "无关：“清楚”指明白、分明，与“长远”没有反义关系。", "热闹": "无关：“热闹”形容场面或气氛，与“长远”的时间意义无关。", "复杂": "无关：“复杂”指事物头绪多，与“长远”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23320, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短暂", "is_correct": true, "explanation": "反义：“短暂”指时间很短、持续不久，与“长远”的持续很久相反。"}, {"text": "干净", "is_correct": false, "explanation": "无关：“干净”指没有污物，与“长远”没有反义关系。"}, {"text": "冷清", "is_correct": false, "explanation": "无关：“冷清”形容场面冷落，与“长远”的时间意义无关。"}, {"text": "粗糙", "is_correct": false, "explanation": "无关：“粗糙”形容质地不光滑，与“长远”不构成反义。"}], "correct_answer": "短暂", "explanations": {"短暂": "反义：“短暂”指时间很短、持续不久，与“长远”的持续很久相反。", "干净": "无关：“干净”指没有污物，与“长远”没有反义关系。", "冷清": "无关：“冷清”形容场面冷落，与“长远”的时间意义无关。", "粗糙": "无关：“粗糙”形容质地不光滑，与“长远”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23320, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "意思是时间很长，很久。", "primary_collocate": null, "pronunciation": "cháng yuǎn", "ipa": "ʈʂʰɑŋ˧˥ ɥɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这件事的影响会很长远。", "target_word": "长远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是想得很长远，不喜欢只看今天。", "target_word": "长远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要为孩子长远的将来做准备。", "target_word": "长远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条新路会给小城带来长远的好处。", "target_word": "长远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她读书是为了长远的进步，不只是为了考试。", "target_word": "长远", "complexity_tier": "T3", "furigana": "tā dú shū shì wèi le cháng yuǎn de jìn bù, bù zhǐ shì wèi le kǎo shì.", "sentence_source": "generated"}, {"text": "老师说，好习惯对一生都有长远的作用。", "target_word": "长远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司想得长远，所以一直在培养新人。", "target_word": "长远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法只能解决眼前的问题，不是长远之计。", "target_word": "长远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房子是长远的事，我们要慢慢想。", "target_word": "长远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次改革的好处要过几年才能看到，影响很长远。", "target_word": "长远", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "長遠", "label": "繁体"}], "register": "中性", "sense_fingerprint": "长远|形容词|时间很长，影响持续很久", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06416bc7-081c-4962-af33-9fe357ea7f64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23320, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长远", "is_correct": true, "explanation": "正确：“影响很长远”指影响持续很久，符合句意。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，不能用来形容影响的程度。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”形容质地，不能修饰“影响”。"}, {"text": "方便", "is_correct": false, "explanation": "语义：“方便”指使用起来便利，与“影响”的意义不合。"}], "explanations": {"长远": "正确：“影响很长远”指影响持续很久，符合句意。", "漂亮": "体貌：“漂亮”形容外貌，不能用来形容影响的程度。", "柔软": "搭配：“柔软”形容质地，不能修饰“影响”。", "方便": "语义：“方便”指使用起来便利，与“影响”的意义不合。"}, "sentence_index": 0, "correct_answer": "长远"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店长远地开了二十年，大家都认识它。", "explanation": "这里应该用〈长期〉。长远多用于计划和影响，描述某店铺已经经营的一段时间要用〈长期〉。"}, {"text": "这种胶水的粘性很长远。", "explanation": "这里应该用〈持久〉。粘性、效果的持续要用〈持久〉，长远不用于描述这类性质。"}, {"text": "这把剪刀的锋利很长远。", "explanation": "这里不能用“长远”。长远只说时间的长久或将来的跨度，不能用来形容锋利这类刃口性质，应说“这把剪刀很锋利”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23320, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长远", "is_correct": true, "explanation": "正确：“想得长远”指考虑问题着眼长远，与后文一直培养新人相符。"}, {"text": "浅", "is_correct": false, "explanation": "语义：“想得浅”指想得不深，与后文“一直在培养新人”的长期投入相矛盾。"}, {"text": "短", "is_correct": false, "explanation": "搭配：“想得短”不是常用说法，“短”不能用来形容思考的范围。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”说场面或气氛，不能用来形容“想”的程度。"}], "explanations": {"长远": "正确：“想得长远”指考虑问题着眼长远，与后文一直培养新人相符。", "浅": "语义：“想得浅”指想得不深，与后文“一直在培养新人”的长期投入相矛盾。", "短": "搭配：“想得短”不是常用说法，“短”不能用来形容思考的范围。", "热闹": "搭配：“热闹”说场面或气氛，不能用来形容“想”的程度。"}, "sentence_index": 6, "correct_answer": "长远"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的老家在长远的小山村。", "explanation": "这里应该用〈遥远〉。长远只说时间的跨度，不用于空间距离；说地方远要用〈遥远〉。"}, {"text": "这段等待的过程十分长远。", "explanation": "这里应该用〈漫长〉。长远着眼将来，不用来形容令人觉得拖沓的时间，这里要用〈漫长〉。"}, {"text": "这个节日有长远的传统。", "explanation": "这里应该用〈悠久〉。长远指将来的时间跨度，不用来描述已经存在很久的传统，这里要用〈悠久〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23320, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家企业定战略时考虑很长远。", "corrected_sentence": "这家企业定战略时考虑得很长远。", "error_description": "错误：“考虑很长远”；正确：“考虑得很长远”。动词后作程度补语时要用“得”连接形容词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23320, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师长远的安排着学生的成长。", "corrected_sentence": "老师长远地安排着学生的成长。", "error_description": "错误：“长远的安排着”；正确：“长远地安排着”。“长远”修饰的是动词“安排”，修饰动词要用“地”，“的”只用于修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
