INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23324, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "班次的意思是车、船、飞机等出发的时间安排。", "primary_collocate": null, "pronunciation": "bān cì", "ipa": "pan˥˥ tsʰɨ˥˩", "syllable_count": 2, "sentences": [{"text": "你知道去机场的班次吗？", "target_word": "班次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班次太早，我起不来。", "target_word": "班次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐了下午两点的班次回家。", "target_word": "班次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天来的人多，船的班次也多了。", "target_word": "班次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们换一个晚一点的班次吧。", "target_word": "班次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场大巴每半小时有一个班次。", "target_word": "班次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下大雨，今天的班次都推迟了。", "target_word": "班次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我最后一个班次是几点。", "target_word": "班次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的班次很少，你要早点出发。", "target_word": "班次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上能查到最新的班次。", "target_word": "班次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "班次表", "label": "复合"}], "register": "中性", "sense_fingerprint": "班次|名词|车船飞机出发的时间安排", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06416bc7-081c-4962-af33-9fe357ea7f64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23324, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "班次", "is_correct": true, "explanation": "正确。“去机场的班次”指车船出发的时间安排，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色说的是外观色彩，不是出发安排，“去机场的颜色”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的体型特征，不能用于“去机场”的事物。"}, {"text": "作者", "is_correct": false, "explanation": "搭配：作者是写作的人，不能说“去机场的作者”。"}], "explanations": {"班次": "正确。“去机场的班次”指车船出发的时间安排，符合句意。", "颜色": "语义：颜色说的是外观色彩，不是出发安排，“去机场的颜色”说不通。", "身高": "体貌：身高是人的体型特征，不能用于“去机场”的事物。", "作者": "搭配：作者是写作的人，不能说“去机场的作者”。"}, "sentence_index": 0, "correct_answer": "班次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天坐班次上班，很方便。", "explanation": "这里应该用〈班车〉。班次是出发的时间安排，不是车辆，不能说“坐班次”。"}, {"text": "我们坐了一条班次。", "explanation": "这里不能用“条”。“条”用于细长的东西，班次不能用“条”来数，应说“我们坐了一班车”。"}, {"text": "他翻开班次看了一会儿。", "explanation": "这里应该用〈时刻表〉。班次指车船出发的时间，不是可以翻开的书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23324, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "班次", "is_correct": true, "explanation": "正确。“今天的班次都推迟了”指车船出发安排被延后，符合句意。"}, {"text": "口味", "is_correct": false, "explanation": "语义：口味说的是味道偏好，不能被“推迟”。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格是人的心理特征，不能用“推迟”来说。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材是人的体型，不能和“推迟”搭配。"}], "explanations": {"班次": "正确。“今天的班次都推迟了”指车船出发安排被延后，符合句意。", "口味": "语义：口味说的是味道偏好，不能被“推迟”。", "性格": "语义：性格是人的心理特征，不能用“推迟”来说。", "身材": "体貌：身材是人的体型，不能和“推迟”搭配。"}, "sentence_index": 6, "correct_answer": "班次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们吃了这个班次，还是很饿。", "explanation": "这里应该用〈面包〉。班次是车船出发的时间安排，不是可以吃的东西，“吃”的对象应是食物。"}, {"text": "我们等了一张班次。", "explanation": "这里不能用“张”。“张”用于平面的东西，班次不能用“张”来数，应说“我们等了一班车”。"}, {"text": "他坐在班次里看书。", "explanation": "这里应该用〈车厢〉。人是坐在车厢里的，班次不是可以坐的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23324, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆班次很早就满了。", "corrected_sentence": "这个班次很早就满了。", "error_description": "“班次”前用了量词“辆”。“辆”只用于车辆本身，班次不能用“辆”来数，应说“这个班次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23324, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们坐的是最早的班次的。", "corrected_sentence": "我们坐的是最早的班次。", "error_description": "“班次”后面多加了一个“的”。“的”用在定语后面，句末“班次的”没有中心语，是错误的形式，应去掉，说“最早的班次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
