INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23328, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很多人搬到城市里住，城市就变大了。", "primary_collocate": null, "pronunciation": "chéng shì huà", "ipa": "ʈʂʰɤŋ˧˥ ʂʐ̩˥˩ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "城市化使这座小城变大了。", "target_word": "城市化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年轻人去大城市工作，这就是城市化。", "target_word": "城市化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市化以后，我们村变成了城区。", "target_word": "城市化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市化让街上的人越来越多。", "target_word": "城市化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为城市化，城市周围的农田少了。", "target_word": "城市化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家乡的城市化很快，楼房越来越多。", "target_word": "城市化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市化以后，爷爷家附近有了地铁。", "target_word": "城市化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市化使城市越来越大。", "target_word": "城市化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市化的结果是城市里人多车多。", "target_word": "城市化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年城市化很快，老城区也变大了。", "target_word": "城市化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "城市化进程", "label": "复合"}, {"form": "逆城市化", "label": "复合"}], "register": "书面", "sense_fingerprint": "人搬进城市、城市变大的现象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '393bfa21-a379-477d-b422-bab907e99afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23328, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "城市化", "is_correct": true, "explanation": "正确：「城市化使这座小城变大了」中，「城市化」指人口集中、城市扩大，与句义相合。"}, {"text": "沙漠化", "is_correct": false, "explanation": "语义：「沙漠化」使土地荒芜，不能使城市变大，与句义相反。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气变化不能使城市变大，与「小城变大」的因果不合。"}, {"text": "道德", "is_correct": false, "explanation": "搭配：「使……变大」的主语应是可以扩张的事物，「道德」是抽象概念，不搭配。"}], "explanations": {"城市化": "正确：「城市化使这座小城变大了」中，「城市化」指人口集中、城市扩大，与句义相合。", "沙漠化": "语义：「沙漠化」使土地荒芜，不能使城市变大，与句义相反。", "天气": "语义：天气变化不能使城市变大，与「小城变大」的因果不合。", "道德": "搭配：「使……变大」的主语应是可以扩张的事物，「道德」是抽象概念，不搭配。"}, "sentence_index": 0, "correct_answer": "城市化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的城市化越来越好，成绩提高了。", "explanation": "这里应该用〈学习〉。城市化指地区与人口的转变，不用于个人的学习。"}, {"text": "这个孩子城市化了，变得很高。", "explanation": "这里应该用〈长大〉。城市化指地区与人口的转变，不用于人的生长。"}, {"text": "这套房子城市化了，很漂亮。", "explanation": "这里应该用〈装修〉。城市化用于地区和人口，不用于房屋的装饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23328, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "城市化", "is_correct": true, "explanation": "正确：「城市化以后」指城市化之后，地区变化带来了地铁，与句义相合。"}, {"text": "贫困化", "is_correct": false, "explanation": "语义：「贫困化」指变穷，与句中「有了地铁」的发展迹象相矛盾。"}, {"text": "荒漠化", "is_correct": false, "explanation": "语义：「荒漠化」指土地变成荒漠，之后不会出现地铁，与句义不合。"}, {"text": "饮食", "is_correct": false, "explanation": "搭配：「饮食以后」指吃饭之后，不指地区的变化，不能与「以后，……有了地铁」搭配。"}], "explanations": {"城市化": "正确：「城市化以后」指城市化之后，地区变化带来了地铁，与句义相合。", "贫困化": "语义：「贫困化」指变穷，与句中「有了地铁」的发展迹象相矛盾。", "荒漠化": "语义：「荒漠化」指土地变成荒漠，之后不会出现地铁，与句义不合。", "饮食": "搭配：「饮食以后」指吃饭之后，不指地区的变化，不能与「以后，……有了地铁」搭配。"}, "sentence_index": 6, "correct_answer": "城市化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老人的城市化越来越快，身体也好多了。", "explanation": "这里应该用〈康复〉。城市化不用于人的身体恢复。"}, {"text": "这批货物的城市化很快就到了。", "explanation": "这里应该用〈运输〉。城市化不用于货物的运送。"}, {"text": "这门课的城市化很大，学生都学不会。", "explanation": "这里应该用〈难度〉。城市化不用于形容课程的难易。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23328, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几年城市化了很快，村子变成了城区。", "corrected_sentence": "这几年城市化很快，村子变成了城区。", "error_description": "错误形式在「城市化」后加了「了」。「很快」在此作谓语，「城市化很快」是主谓结构，「了」不能加在「城市化」后面。正确形式为「城市化很快」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23328, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "城市化的以后，农村的变化很大。", "corrected_sentence": "城市化以后，农村的变化很大。", "error_description": "错误形式在「城市化」后多加了「的」，「以后」前不应加「的」。正确形式为「城市化以后，……」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
