INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23330, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情正在向前发展、变化的过程。", "primary_collocate": null, "pronunciation": "jìn chéng", "ipa": "tɕin˥˩ tʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "战争拖慢了这个国家的发展进程。", "target_word": "进程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "改革的进程比我们想的要快。", "target_word": "进程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国谈判的进程一直很顺利。", "target_word": "进程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新技术加快了城市化进程。", "target_word": "进程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨打乱了事情的进程。", "target_word": "进程", "complexity_tier": "T3", "furigana": "jìnchéng", "sentence_source": "generated"}, {"text": "老师每周检查一次学习进程。", "target_word": "进程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛的进程十分紧张。", "target_word": "进程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济发展的进程中，会遇到很多问题。", "target_word": "进程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他详细讲了公司合作的进程。", "target_word": "进程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类历史的进程不会因为一个人而停下。", "target_word": "进程", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "历史进程", "label": "复合"}, {"form": "城市化进程", "label": "复合"}], "register": "中性", "sense_fingerprint": "事情向前发展、变化所经历的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20be542-fd2b-4af9-92a3-e1943594c231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23330, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "进程", "is_correct": true, "explanation": "正确：“拖慢”可以用于事情向前发展的过程，与“发展进程”相符。"}, {"text": "方向", "is_correct": false, "explanation": "搭配：“拖慢”说的是速度或过程，不能用来说方向。"}, {"text": "成果", "is_correct": false, "explanation": "语义：“成果”是已经取得的结果，不能被“拖慢”。"}, {"text": "规则", "is_correct": false, "explanation": "语义：“规则”是制度或约定，不指发展的过程，不能被“拖慢”。"}], "explanations": {"进程": "正确：“拖慢”可以用于事情向前发展的过程，与“发展进程”相符。", "方向": "搭配：“拖慢”说的是速度或过程，不能用来说方向。", "成果": "语义：“成果”是已经取得的结果，不能被“拖慢”。", "规则": "语义：“规则”是制度或约定，不指发展的过程，不能被“拖慢”。"}, "sentence_index": 0, "correct_answer": "进程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆汽车的进程很快。", "explanation": "这里应该用〈速度〉。进程指事情向前发展的过程，不能用来形容车辆的快慢。"}, {"text": "这次事故的进程很严重。", "explanation": "这里应该用〈程度〉。进程指事情向前发展的过程，表示事故严重的程度要用“程度”。"}, {"text": "这支队伍的进程很整齐。", "explanation": "这里应该用〈行进〉。进程指事情的发展过程，描述队伍向前走的动作要用“行进”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc82110-a7fa-4448-8b51-2c6a20f47e0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23330, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进程", "is_correct": true, "explanation": "正确：“十分紧张”可以形容比赛的发展过程，与句意相符。"}, {"text": "步骤", "is_correct": false, "explanation": "搭配：“十分紧张”说的是气氛或局势，不能用来形容“步骤”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能用“紧张”来形容，句中不合。"}, {"text": "次数", "is_correct": false, "explanation": "语义：“次数”是计量的数目，不能用“紧张”来形容。"}], "explanations": {"进程": "正确：“十分紧张”可以形容比赛的发展过程，与句意相符。", "步骤": "搭配：“十分紧张”说的是气氛或局势，不能用来形容“步骤”。", "颜色": "语义：“颜色”不能用“紧张”来形容，句中不合。", "次数": "语义：“次数”是计量的数目，不能用“紧张”来形容。"}, "sentence_index": 6, "correct_answer": "进程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次旅行是我最难忘的进程。", "explanation": "这里应该用〈经历〉。进程指事情向前发展的过程，人的亲身遭遇要用“经历”。"}, {"text": "他对朋友的进程很深。", "explanation": "这里应该用〈感情〉。进程指事情的发展过程，不能用来形容对人的情感深浅。"}, {"text": "从这里到学校的进程很远。", "explanation": "这里应该用〈路程〉。进程指事情的发展过程，不指距离的远近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc82110-a7fa-4448-8b51-2c6a20f47e0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23330, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条进程比预期的慢得多。", "corrected_sentence": "这个进程比预期的慢得多。", "error_description": "错误：量词“条”用于细长的物体，不能用来修饰“进程”。正确：“这个进程”，“进程”是抽象的过程，应使用通用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc82110-a7fa-4448-8b51-2c6a20f47e0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23330, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把进程比我想象的复杂。", "corrected_sentence": "这个进程比我想象的复杂。", "error_description": "错误形式：“这把进程”。正确形式：“这个进程”。“把”是用于有柄器具的量词，进程应使用通用量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc82110-a7fa-4448-8b51-2c6a20f47e0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
