INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23334, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "身体各部分能做的事情。", "primary_collocate": null, "pronunciation": "jī néng", "ipa": "tɕi˥ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "身体的每个部分都有自己的机能。", "target_word": "机能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人老了，身体机能会变弱。", "target_word": "机能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "眼睛的机能是看东西。", "target_word": "机能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "耳朵的机能是听声音。", "target_word": "机能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病以后，身体机能变差了。", "target_word": "机能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多运动能让身体机能更好。", "target_word": "机能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长大了，身体的机能也在变好。", "target_word": "机能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手脚受伤后，要慢慢恢复机能。", "target_word": "机能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生检查了我的心肺机能。", "target_word": "机能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡得不好，身体的机能就会下降。", "target_word": "机能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "機能", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "身体各个部分能够做的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569bc8cf-48c5-4326-bc0a-b2a00dd42f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23334, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "机能", "is_correct": true, "explanation": "正确。“身体的每个部分都有自己的机能”指各部分各自的功能，与语境相符。"}, {"text": "性情", "is_correct": false, "explanation": "语义：“性情”指人的性格脾气，身体的部分没有性情，句子读不通。"}, {"text": "学问", "is_correct": false, "explanation": "语义：身体的部分没有学问，“都有自己的学问”读不通。"}, {"text": "名声", "is_correct": false, "explanation": "搭配：“名声”通常针对人或机构，不能说身体的部分有名声。"}], "explanations": {"机能": "正确。“身体的每个部分都有自己的机能”指各部分各自的功能，与语境相符。", "性情": "语义：“性情”指人的性格脾气，身体的部分没有性情，句子读不通。", "学问": "语义：身体的部分没有学问，“都有自己的学问”读不通。", "名声": "搭配：“名声”通常针对人或机构，不能说身体的部分有名声。"}, "sentence_index": 0, "correct_answer": "机能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的机能是打印文件。", "explanation": "这里应该用〈功能〉。“机能”只用于人和动物的身体，机器要说“功能”。"}, {"text": "这种肥料的机能很好。", "explanation": "这里应该用〈效果〉。“机能”指身体器官的作用，肥料的作用要说“效果”。"}, {"text": "这项措施的机能很大。", "explanation": "这里应该用〈作用〉。“机能”指身体器官的功能，措施的影响要说“作用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23334, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "机能", "is_correct": true, "explanation": "正确。“孩子长大了，身体的机能也在变好”指身体的功能在提升，与语境相符。"}, {"text": "口音", "is_correct": false, "explanation": "语义：“口音”指说话的发音特点，身体没有口音，“身体的口音也在变好”读不通。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”是数值，不能用“变好”来描述。"}, {"text": "性格", "is_correct": false, "explanation": "语义：身体没有性格，“身体的性格也在变好”读不通。"}], "explanations": {"机能": "正确。“孩子长大了，身体的机能也在变好”指身体的功能在提升，与语境相符。", "口音": "语义：“口音”指说话的发音特点，身体没有口音，“身体的口音也在变好”读不通。", "身高": "搭配：“身高”是数值，不能用“变好”来描述。", "性格": "语义：身体没有性格，“身体的性格也在变好”读不通。"}, "sentence_index": 6, "correct_answer": "机能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的机能很好。", "explanation": "这里应该用〈性能〉。“机能”用于人和动物的身体，车辆的效能要说“性能”。"}, {"text": "他身体里有一座机能。", "explanation": "这里应该用〈种〉。“座”用于大型建筑，机能应当用“种”。"}, {"text": "这个方案的机能很高。", "explanation": "这里应该用〈效率〉。“机能”指身体器官的功能，方案的工作效果要说“效率”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23334, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "眼睛的机能消灭了。", "corrected_sentence": "眼睛的机能恢复了。", "error_description": "搭配错误：「消灭」的对象是敌人、害虫等，机能不能被消灭。这里应改为「恢复」，正确句为「眼睛的机能恢复了。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23334, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种训练能增强老年人的身体机能的。", "corrected_sentence": "这种训练能增强老年人的身体机能。", "error_description": "助词多余：句末的“的”是错误的，正确说法是“增强老年人的身体机能”，“机能”后面不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
