INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23336, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "环境效益就是做一件事对大自然有没有好处。", "primary_collocate": null, "pronunciation": "huán jìng xiào yì", "ipa": "xwan˧˥ tɕiŋ˥˩ ɕjaʊ˥˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "少用塑料袋的环境效益很高。", "target_word": "环境效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做这件事的环境效益好不好，要先算一算。", "target_word": "环境效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐公交车比开车的环境效益更好。", "target_word": "环境效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们看一个办法好不好，也要看环境效益。", "target_word": "环境效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回收旧衣服有很好的环境效益。", "target_word": "环境效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳能灯的环境效益比电灯高。", "target_word": "环境效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路的环境效益不高，因为砍了很多树。", "target_word": "环境效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我们：骑自行车的环境效益是什么？", "target_word": "环境效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在作业里写了种花的环境效益。", "target_word": "环境效益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂减少了污水，环境效益明显提高。", "target_word": "环境效益", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "環境效益", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做一件事对大自然有没有好处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5714203-90c7-4816-b5d4-4f7aff98a03b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23336, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "垃圾量", "is_correct": false, "explanation": "语义：“少用塑料袋”应使垃圾减少，说“垃圾量很高”与句意相反。"}, {"text": "环境效益", "is_correct": true, "explanation": "正确：“少用塑料袋”带来对环境的好处，“很高”形容效果好，符合句意。"}, {"text": "碳排放", "is_correct": false, "explanation": "语义：少用塑料袋应降低碳排放，说“碳排放很高”与“少用”矛盾。"}, {"text": "纸箱", "is_correct": false, "explanation": "搭配：“纸箱很高”只能说箱子的高度，与“少用塑料袋”的环境效果无关。"}], "explanations": {"垃圾量": "语义：“少用塑料袋”应使垃圾减少，说“垃圾量很高”与句意相反。", "环境效益": "正确：“少用塑料袋”带来对环境的好处，“很高”形容效果好，符合句意。", "碳排放": "语义：少用塑料袋应降低碳排放，说“碳排放很高”与“少用”矛盾。", "纸箱": "搭配：“纸箱很高”只能说箱子的高度，与“少用塑料袋”的环境效果无关。"}, "sentence_index": 0, "correct_answer": "环境效益"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老人的环境效益很高大，邻居们都很喜欢他。", "explanation": "这里应该用〈身材〉。“高大”形容实体的形体，环境效益指做事对大自然的好处，不能这样形容。"}, {"text": "这条河的环境效益很严重。", "explanation": "这里应该用〈污染〉。“很严重”说的是坏的情况，环境效益是好处，不能用“严重”形容。"}, {"text": "城市的环境效益面积增加了。", "explanation": "这里应该用〈绿地〉。绿地可以用面积衡量，环境效益是抽象的效果，不能说“面积增加”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23336, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "环境效益", "is_correct": true, "explanation": "正确：“这条路的……不高”指的是环境方面的效果，与“因为砍了很多树”的语境相符。"}, {"text": "环境危害", "is_correct": false, "explanation": "语义：砍树会加重危害，说“危害不高”与“因为砍了很多树”的因果矛盾。"}, {"text": "垃圾量", "is_correct": false, "explanation": "语义：砍树与垃圾量没有因果关系，“垃圾量不高，因为砍了很多树”说不通。"}, {"text": "学费", "is_correct": false, "explanation": "搭配：“学费”与道路和砍树毫无关系，“这条路的学费不高”说不通。"}], "explanations": {"环境效益": "正确：“这条路的……不高”指的是环境方面的效果，与“因为砍了很多树”的语境相符。", "环境危害": "语义：砍树会加重危害，说“危害不高”与“因为砍了很多树”的因果矛盾。", "垃圾量": "语义：砍树与垃圾量没有因果关系，“垃圾量不高，因为砍了很多树”说不通。", "学费": "搭配：“学费”与道路和砍树毫无关系，“这条路的学费不高”说不通。"}, "sentence_index": 6, "correct_answer": "环境效益"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂的环境效益让附近的居民很烦恼。", "explanation": "这里应该用〈噪音〉。效益是好处，不会让居民烦恼；让人烦恼的是噪音。"}, {"text": "环境效益堆在路边，没人清理。", "explanation": "这里应该用〈垃圾〉。“堆”和“清理”针对的是实物垃圾，环境效益是抽象的效果，不能这样处理。"}, {"text": "工厂用了很多环境效益。", "explanation": "这里应该用〈原料〉。“用”的对象是原料等物质，效益是抽象的效果，不能被使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23336, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要环境效益放在第一位。", "corrected_sentence": "我们要把环境效益放在第一位。", "error_description": "把字句漏掉“把”：要处置“环境效益”并放在某处时，需用“把”引出宾语，应说“把环境效益放在第一位”，不能直接说“环境效益放在第一位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23336, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个办法有很好地环境效益。", "corrected_sentence": "这个办法有很好的环境效益。", "error_description": "结构助词错误：修饰名词“环境效益”要用“的”，“地”用于修饰动词、形容词。正确的说法是“很好的环境效益”，错误的说法是“很好地环境效益”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
