INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23338, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想一个办法做出新的东西。", "primary_collocate": null, "pronunciation": "shè jì", "ipa": "ʂɤ˥˩ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "他想自己设计一件新衣服。", "target_word": "设计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座桥是一位老工程师设计的。", "target_word": "设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你帮我设计一张生日卡片。", "target_word": "设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们正在设计学校的新标志。", "target_word": "设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢设计各种好看的鞋子。", "target_word": "设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王为小孩设计了一个很安全的玩具。", "target_word": "设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机是怎么设计出来的？", "target_word": "设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你来设计，房子会是什么样？", "target_word": "设计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他花了三个月设计这辆自行车。", "target_word": "设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司请他设计一个新的网站。", "target_word": "设计", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "设计了", "label": "体标"}, {"form": "设计过", "label": "体标"}, {"form": "设计师", "label": "复合"}, {"form": "设计图", "label": "复合"}], "register": "中性", "sense_fingerprint": "设计：动脑筋想办法，做出新的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675cfc97-fbfc-4651-bf94-1c49f7b53f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23338, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "设计", "is_correct": true, "explanation": "正确选项：设计（shè jì），指想办法做出新的东西。"}, {"text": "射击", "is_correct": false, "explanation": "jī（第一声）与 jì（第四声）声调不同，意思是用枪或弓对准目标发射。"}, {"text": "涉及", "is_correct": false, "explanation": "jí（第二声）与 jì（第四声）声调不同，意思是牵涉到某个方面。"}, {"text": "舍己", "is_correct": false, "explanation": "shě（第三声）与 shè（第四声）、jǐ（第三声）与 jì（第四声）声调不同，意思是舍弃自己的利益。"}], "explanations": {"设计": "正确选项：设计（shè jì），指想办法做出新的东西。", "射击": "jī（第一声）与 jì（第四声）声调不同，意思是用枪或弓对准目标发射。", "涉及": "jí（第二声）与 jì（第四声）声调不同，意思是牵涉到某个方面。", "舍己": "shě（第三声）与 shè（第四声）、jǐ（第三声）与 jì（第四声）声调不同，意思是舍弃自己的利益。"}, "sentence_index": null, "correct_answer": "设计"}, "level_3": {"options": [{"text": "拜访", "is_correct": false, "explanation": "搭配：“拜访”的对象应该是人，不能拜访衣服。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，后面不能直接带“一件新衣服”这样的宾语。"}, {"text": "设计", "is_correct": true, "explanation": "正确：设计指想办法做出新东西，“想自己”做的正是衣服。"}, {"text": "咨询", "is_correct": false, "explanation": "语义：“咨询”是向别人请教，与“自己”做衣服的语境不合。"}], "explanations": {"拜访": "搭配：“拜访”的对象应该是人，不能拜访衣服。", "散步": "配价：“散步”是不及物动词，后面不能直接带“一件新衣服”这样的宾语。", "设计": "正确：设计指想办法做出新东西，“想自己”做的正是衣服。", "咨询": "语义：“咨询”是向别人请教，与“自己”做衣服的语境不合。"}, "sentence_index": 0, "correct_answer": "设计"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈设计了一锅粥，全家人都喝了。", "explanation": "这里应该用〈煮〉。做饭煮粥要说“煮”，“设计”指想办法做出新的样式或方案。"}, {"text": "他用抹布设计桌子，很快就干净了。", "explanation": "这里应该用〈擦〉。用抹布清洁桌子要说“擦”，“设计”不能用于清洁。"}, {"text": "他设计了一件脏衣服，晾在了阳台上。", "explanation": "这里应该用〈洗〉。把脏衣服弄干净要说“洗”，“设计”不能用来处理脏衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8b32aaa-68bf-436c-bb1a-69d9defbf86c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23338, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，手机不能被唱出来。"}, {"text": "熬", "is_correct": false, "explanation": "语义：“熬”多用于煮药、熬粥，手机不是熬出来的。"}, {"text": "设计", "is_correct": true, "explanation": "正确：设计是想办法做出新东西，“怎么……出来的”问的正是设计过程。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，后面不能带“手机”这样的宾语。"}], "explanations": {"唱": "语义：“唱”的对象是歌曲，手机不能被唱出来。", "熬": "语义：“熬”多用于煮药、熬粥，手机不是熬出来的。", "设计": "正确：设计是想办法做出新东西，“怎么……出来的”问的正是设计过程。", "睡": "配价：“睡”是不及物动词，后面不能带“手机”这样的宾语。"}, "sentence_index": 6, "correct_answer": "设计"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用手机设计了一张照片。", "explanation": "这里应该用〈拍〉。用手机拍摄照片要说“拍”，“设计”不能用于拍照。"}, {"text": "她把课文设计完了，就去睡觉。", "explanation": "这里应该用〈背〉。把课文记在脑子里要说“背”，“设计”指想办法做出新东西。"}, {"text": "他把这篇文章设计成了英文。", "explanation": "这里应该用〈翻译〉。把文章转成另一种语言要用〈翻译〉，“设计”指想办法做出新的东西，不用于语言转换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8b32aaa-68bf-436c-bb1a-69d9defbf86c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23338, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套房子是他设计来的。", "corrected_sentence": "这套房子是他设计出来的。", "error_description": "结果补语错误：“设计”后要接“出来”，表示设计并做成，应说“设计出来”，不能只说“设计来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8b32aaa-68bf-436c-bb1a-69d9defbf86c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23338, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天我设计一张新的生日卡片。", "corrected_sentence": "昨天我设计了一张新的生日卡片。", "error_description": "“了”缺失：句中有表示过去的时间词“昨天”，表示已完成的动作时动词后要加“了”，应说“昨天我设计了一张新的生日卡片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8b32aaa-68bf-436c-bb1a-69d9defbf86c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
