INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23340, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大自然中的动物和植物数量刚刚好，不会太多也不会太少。", "primary_collocate": null, "pronunciation": "shēng tài píng héng", "ipa": "ʂɤŋ˥ tʰaɪ˥˩ pʰiŋ˧˥ xɤŋ˧˥", "syllable_count": 4, "sentences": [{"text": "草、兔子和狼的数量刚刚好，这就是生态平衡。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "池塘里的鱼不多不少，生态平衡很好。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昆虫太少，鸟没有吃的，生态平衡也会受影响。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，大自然需要生态平衡。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们过度打猎，生态平衡就变坏了。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个岛上的生态平衡一直很好。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保持生态平衡，动植物就都能活下去。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草原上羊太多，会影响生态平衡。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要爱护动物，保护生态平衡。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里放了太多鱼，生态平衡出了问题。", "target_word": "生态平衡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生態平衡", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大自然中动植物数量刚刚好、不多不少的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5714203-90c7-4816-b5d4-4f7aff98a03b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23340, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动物园", "is_correct": false, "explanation": "语义：前句讲的是动植物数量刚刚好，“这就是动物园”与句意不符。"}, {"text": "生态平衡", "is_correct": true, "explanation": "正确：“这就是生态平衡”概括前句中草、兔、狼数量刚好的状态，合乎语境。"}, {"text": "考试成绩", "is_correct": false, "explanation": "语义：前句说的是动植物的数量关系，考试成绩与之无关。"}, {"text": "大锅饭", "is_correct": false, "explanation": "语义：“大锅饭”指平均分配、不论差别的制度，与动植物的数量关系无关，“这就是大锅饭”句意不通。"}], "explanations": {"动物园": "语义：前句讲的是动植物数量刚刚好，“这就是动物园”与句意不符。", "生态平衡": "正确：“这就是生态平衡”概括前句中草、兔、狼数量刚好的状态，合乎语境。", "考试成绩": "语义：前句说的是动植物的数量关系，考试成绩与之无关。", "大锅饭": "语义：“大锅饭”指平均分配、不论差别的制度，与动植物的数量关系无关，“这就是大锅饭”句意不通。"}, "sentence_index": 0, "correct_answer": "生态平衡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "草原上的羊很多，生态平衡也很多。", "explanation": "这个词不这么用：“很多”修饰可以计数的数量，“生态平衡”是状态，不能说“多”。"}, {"text": "我在商店买了一些生态平衡。", "explanation": "这个词不这么用：“买”的对象应是商品，生态平衡是抽象状态，买不到。"}, {"text": "湖边有一只生态平衡，很美。", "explanation": "量词：〈只〉用于动物等个体，“生态平衡”是抽象名词，不能用“只”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23340, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "搭配：“保持”多接状态、秩序，不接“作业”，“保持作业”不成立。"}, {"text": "生态平衡", "is_correct": true, "explanation": "正确：“保持生态平衡”是常用搭配，与后句“动植物就都能活下去”前后相承。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋不能被保持，句子讲的是自然环境，与动植物生存相关。"}, {"text": "身高", "is_correct": false, "explanation": "语义：动植物能否活下去与身高无关，“保持身高”与句意不符。"}], "explanations": {"作业": "搭配：“保持”多接状态、秩序，不接“作业”，“保持作业”不成立。", "生态平衡": "正确：“保持生态平衡”是常用搭配，与后句“动植物就都能活下去”前后相承。", "鸡蛋": "语义：鸡蛋不能被保持，句子讲的是自然环境，与动植物生存相关。", "身高": "语义：动植物能否活下去与身高无关，“保持身高”与句意不符。"}, "sentence_index": 6, "correct_answer": "生态平衡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个湖的生态平衡有三层楼高。", "explanation": "这个词不这么用：“高”用于可以测量高度的事物，生态平衡是状态，不能用“楼”来计量高度。"}, {"text": "他的生态平衡跑得很快。", "explanation": "搭配：“跑”的主语应是人或车辆，“生态平衡”是状态，不会跑。"}, {"text": "这些草的生态平衡有五十块钱。", "explanation": "这个词不这么用：“块钱”只能计量有价格的物品，生态平衡是状态，没有价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23340, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片林子的生态平衡慢慢吃了。", "corrected_sentence": "这片林子的生态平衡慢慢恢复了。", "error_description": "搭配：“吃”不能与“生态平衡”搭配，应改为“恢复”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23340, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个岛上的生态平衡吃得很好。", "corrected_sentence": "这个岛上的生态平衡保持得很好。", "error_description": "搭配：“吃”的对象应是人或动物，“生态平衡”不能“吃得很好”，应改为“保持得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23344, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23344, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23344, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指距离很长，从前面到后面很深。", "primary_collocate": null, "pronunciation": "zòng shēn", "ipa": "tsʊŋ˥˩ ʂən˥", "syllable_count": 2, "sentences": [{"text": "这个院子纵深很长，有三个门。", "target_word": "纵深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店的纵深很大，里面像个仓库。", "target_word": "纵深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山洞的纵深有一百多米。", "target_word": "纵深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条胡同很窄，纵深却有几百米。", "target_word": "纵深", "complexity_tier": "T3", "furigana": "zòng shēn", "sentence_source": "generated"}, {"text": "舞台纵深太短，演员不能跑。", "target_word": "纵深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套房子宽度小，但是纵深很长。", "target_word": "纵深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走进森林的纵深，天都黑了。", "target_word": "纵深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室的纵深不够，后面的同学看不清。", "target_word": "纵深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座庙的纵深很大，一进一进的。", "target_word": "纵深", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子纵深很长，光线进不来。", "target_word": "纵深", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "纵深处", "label": "复合"}, {"form": "縱深", "label": "繁体"}], "register": "书面", "sense_fingerprint": "空间从前到后的长度很深", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '393bfa21-a379-477d-b422-bab907e99afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23344, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "纵深", "is_correct": true, "explanation": "正确：「纵深」zòng shēn，指距离很长，从前面到后面很深。"}, {"text": "终身", "is_correct": false, "explanation": "zhōng（第一声）与 zòng（第四声）声母与声调都不同，「终身」意思是一辈子，与「纵深」不同。"}, {"text": "重申", "is_correct": false, "explanation": "chóng（第二声）与 zòng（第四声）声母 ch 与 z 不同、声调也不同，「重申」意思是再次声明，与「纵深」不同。"}, {"text": "纵声", "is_correct": false, "explanation": "shēng 与 shēn 的韵母 eng 与 en 不同，「纵声」意思是放开嗓门，与「纵深」不同。"}], "explanations": {"纵深": "正确：「纵深」zòng shēn，指距离很长，从前面到后面很深。", "终身": "zhōng（第一声）与 zòng（第四声）声母与声调都不同，「终身」意思是一辈子，与「纵深」不同。", "重申": "chóng（第二声）与 zòng（第四声）声母 ch 与 z 不同、声调也不同，「重申」意思是再次声明，与「纵深」不同。", "纵声": "shēng 与 shēn 的韵母 eng 与 en 不同，「纵声」意思是放开嗓门，与「纵深」不同。"}, "sentence_index": null, "correct_answer": "纵深"}, "level_3": {"options": [{"text": "纵深", "is_correct": true, "explanation": "正确：「这个院子纵深很长」指院子从前到后很长，有三个门，与句义相合。"}, {"text": "宽度", "is_correct": false, "explanation": "语义：「宽度」指左右距离，与句中「从前到后」的长度不符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「颜色」不能说「很长」，与「很长」搭配不通。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：「脾气」是人的性格，不能用「很长」修饰院子。"}], "explanations": {"纵深": "正确：「这个院子纵深很长」指院子从前到后很长，有三个门，与句义相合。", "宽度": "语义：「宽度」指左右距离，与句中「从前到后」的长度不符。", "颜色": "搭配：「颜色」不能说「很长」，与「很长」搭配不通。", "脾气": "搭配：「脾气」是人的性格，不能用「很长」修饰院子。"}, "sentence_index": 0, "correct_answer": "纵深"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座庙的纵深很高，一层一层的。", "explanation": "这里应该用〈高度〉。纵深指前后的深度，不指竖直方向的高矮。"}, {"text": "这条路的纵深很宽，两边都是树。", "explanation": "这里应该用〈宽度〉。宽度指左右之间的距离；纵深指从前到后的距离，不说路的纵深很宽。"}, {"text": "这块石头的纵深很贵，我买不起。", "explanation": "这里应该用〈价格〉。价格指买卖的钱数；纵深指距离，不能说「很贵」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23344, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纵深", "is_correct": true, "explanation": "正确：「走进森林的纵深」指走进森林深处，与「天都黑了」的语境相合。"}, {"text": "名字", "is_correct": false, "explanation": "语义：「名字」是称呼，不能指走进的地方，与句义不合。"}, {"text": "价格", "is_correct": false, "explanation": "语义：「价格」与走进森林的空间位置无关，不能用于此处。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：「走进」后接「声音」不通，不说「走进森林的声音」指空间位置。"}], "explanations": {"纵深": "正确：「走进森林的纵深」指走进森林深处，与「天都黑了」的语境相合。", "名字": "语义：「名字」是称呼，不能指走进的地方，与句义不合。", "价格": "语义：「价格」与走进森林的空间位置无关，不能用于此处。", "声音": "搭配：「走进」后接「声音」不通，不说「走进森林的声音」指空间位置。"}, "sentence_index": 6, "correct_answer": "纵深"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块布的纵深很大，能盖住床。", "explanation": "这里应该用〈面积〉。面积指平面的大小，纵深指空间从前到后的距离。"}, {"text": "这个箱子的纵深很重，要两个人抬。", "explanation": "这里应该用〈重量〉。重量指轻重，纵深指距离，不能说「很重」。"}, {"text": "这根绳子的纵深很长，能绕一圈。", "explanation": "这里应该用〈长度〉。长度指线状物的长短；纵深指空间中从前到后的深处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23344, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座老宅的纵深长很，穿过院子才能到后门。", "corrected_sentence": "这座老宅的纵深很长，穿过院子才能到后门。", "error_description": "错误形式把「很」放在「长」之后。形容词谓语前应加「很」，正确形式为「纵深很长」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23344, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间屋子的一个纵深不够，放不下一张大床。", "corrected_sentence": "这间屋子的纵深不够，放不下一张大床。", "error_description": "错误形式用「一个」修饰「纵深」。「纵深」指空间从前到后的深度，表示范围而非可以逐个计数的事物，不能用「一个」修饰。正确形式为「这间屋子的纵深不够」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
