INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23350, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "城市里跑的火车，可以带很多人去不同的地方。", "primary_collocate": null, "pronunciation": "guǐ dào jiāo tōng", "ipa": "kweɪ̯˨˩˦ tɑʊ̯˥˩ tɕjɑʊ̯˥ tʰʊŋ˥", "syllable_count": 4, "sentences": [{"text": "我家附近有轨道交通。", "target_word": "轨道交通", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "坐轨道交通去机场很方便。", "target_word": "轨道交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "轨道交通每天载着很多人。", "target_word": "轨道交通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上轨道交通里人特别多。", "target_word": "轨道交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座城市的轨道交通很发达。", "target_word": "轨道交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我每天坐轨道交通去学校。", "target_word": "轨道交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "轨道交通比公共汽车快。", "target_word": "轨道交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨天，很多人选择轨道交通。", "target_word": "轨道交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们公司离轨道交通很近。", "target_word": "轨道交通", "complexity_tier": "T3", "furigana": "guǐ dào jiāo tōng", "sentence_source": "generated"}, {"text": "这座城市去年修了轨道交通。", "target_word": "轨道交通", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "城市轨道交通", "label": "复合"}, {"form": "軌道交通", "label": "繁体"}], "register": "中性", "sense_fingerprint": "城市里载很多乘客的地铁、轻轨类列车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5714203-90c7-4816-b5d4-4f7aff98a03b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23350, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心情", "is_correct": false, "explanation": "语义：“附近有”后接的是地点或设施，心情不能位于附近。"}, {"text": "轨道交通", "is_correct": true, "explanation": "正确：“我家附近有轨道交通”是常见说法，表示车站或线路靠近住所。"}, {"text": "语法", "is_correct": false, "explanation": "语义：语法不是可以位于附近的事物，与句意不符。"}, {"text": "晚饭", "is_correct": false, "explanation": "搭配：“附近有”多接地点或设施，晚饭不能说“附近有”。"}], "explanations": {"心情": "语义：“附近有”后接的是地点或设施，心情不能位于附近。", "轨道交通": "正确：“我家附近有轨道交通”是常见说法，表示车站或线路靠近住所。", "语法": "语义：语法不是可以位于附近的事物，与句意不符。", "晚饭": "搭配：“附近有”多接地点或设施，晚饭不能说“附近有”。"}, "sentence_index": 0, "correct_answer": "轨道交通"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的好朋友就是轨道交通，我们每天一起玩。", "explanation": "这个词不这么用：〈轨道交通〉指运送乘客的城市列车系统，不能指人，也不能当“朋友”。"}, {"text": "门口停着一只轨道交通。", "explanation": "量词：〈只〉用于动物，火车、地铁一般用〈列〉，这里用“只”是错误的。"}, {"text": "我们坐轨道交通去北京。", "explanation": "这里应该用〈列车〉。轨道交通只在城市内运行，去北京要乘坐城际列车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23350, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：作业不是交通工具，无法与公共汽车比较速度。"}, {"text": "轨道交通", "is_correct": true, "explanation": "正确：轨道交通速度快，与公共汽车比较，符合常识。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋不能与公共汽车比较速度，与句意不符。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“快”用于可以移动的事物，身高不能说“比……快”。"}], "explanations": {"作业": "语义：作业不是交通工具，无法与公共汽车比较速度。", "轨道交通": "正确：轨道交通速度快，与公共汽车比较，符合常识。", "鸡蛋": "语义：鸡蛋不能与公共汽车比较速度，与句意不符。", "身高": "搭配：“快”用于可以移动的事物，身高不能说“比……快”。"}, "sentence_index": 6, "correct_answer": "轨道交通"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "火车沿着轨道交通前进。", "explanation": "这里应该用〈轨道〉。轨道交通指运送乘客的城市列车系统，不是铁轨本身，「沿着」后面要说铁轨。"}, {"text": "这座城市把轨道交通吃光了。", "explanation": "这个词不这么用：“吃”的对象应是食物，轨道交通是运输设施，不能吃。"}, {"text": "这座城市的轨道交通每天都在睡觉。", "explanation": "搭配：“睡觉”的主语应是人或动物，轨道交通是运输系统，不会睡觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23350, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "轨道交通比公共汽车很快得多。", "corrected_sentence": "轨道交通比公共汽车快得多。", "error_description": "语法错误：“比”字句的谓语前不能再加“很”，应说“比公共汽车快得多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23350, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城市的轨道交通们非常发达。", "corrected_sentence": "这座城市的轨道交通非常发达。", "error_description": "用词错误：“们”一般只加在指人的名词后，轨道交通是设施，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
