INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23352, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "动脉是身体里把血液从心脏送到全身的管子。", "primary_collocate": null, "pronunciation": "dòng mài", "ipa": "tʊŋ˥˩ maɪ˥˩", "syllable_count": 2, "sentences": [{"text": "动脉是把血液送到全身的管子。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心脏里的血先流进动脉，再到手和脚。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士在他的手腕上找到了动脉。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动脉的血从心脏出发，静脉的血回到心脏。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用手指按着他的动脉，数了数心跳。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步以后，我能摸到手腕动脉在跳。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动脉里的血流得很快，受伤了很危险。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说爷爷的动脉变硬了，要少吃肉。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动脉和静脉都是血管，但是血流的方向不同。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不小心割到了动脉，马上去了医院。", "target_word": "动脉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "主动脉", "label": "复合"}, {"form": "動脈", "label": "繁体"}], "register": "中性", "sense_fingerprint": "身体里把血液从心脏送到全身的管子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5714203-90c7-4816-b5d4-4f7aff98a03b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23352, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "静脉", "is_correct": false, "explanation": "语义：静脉把血液从身体各处送回心脏，与“送到全身”的方向相反。"}, {"text": "动脉", "is_correct": true, "explanation": "正确：动脉是把血液从心脏送往全身的血管，与定义相符。"}, {"text": "心脏", "is_correct": false, "explanation": "语义：心脏是器官，不是把血液送到全身的管子。"}, {"text": "食管", "is_correct": false, "explanation": "搭配：食管输送的是食物，不能说它把血液送到全身。"}], "explanations": {"静脉": "语义：静脉把血液从身体各处送回心脏，与“送到全身”的方向相反。", "动脉": "正确：动脉是把血液从心脏送往全身的血管，与定义相符。", "心脏": "语义：心脏是器官，不是把血液送到全身的管子。", "食管": "搭配：食管输送的是食物，不能说它把血液送到全身。"}, "sentence_index": 0, "correct_answer": "动脉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "动脉的血从身体各处回到心脏。", "explanation": "这里应该用〈静脉〉。静脉把血从身体各处送回心脏，动脉则把血从心脏送出去，方向不同。"}, {"text": "我在手腕上摸到了一只动脉。", "explanation": "这里应该用〈条〉。动脉是血管，量词用“条”，“只”多用于动物。"}, {"text": "血液在动脉里交换氧气和二氧化碳。", "explanation": "这里应该用〈毛细血管〉。氧气和二氧化碳的交换发生在毛细血管里，动脉主要负责输送血液。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23352, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神经", "is_correct": false, "explanation": "语义：神经里不装血液，“神经里的血流得很快”说不通。"}, {"text": "动脉", "is_correct": true, "explanation": "正确：动脉是输送血液的血管，血流快、受伤危险都与之相符。"}, {"text": "食管", "is_correct": false, "explanation": "搭配：食管是输送食物的管道，不能说它里面的血流得很快。"}, {"text": "脉搏", "is_correct": false, "explanation": "语义：脉搏指跳动的感觉，不是装血的管道，不能说“脉搏里的血”。"}], "explanations": {"神经": "语义：神经里不装血液，“神经里的血流得很快”说不通。", "动脉": "正确：动脉是输送血液的血管，血流快、受伤危险都与之相符。", "食管": "搭配：食管是输送食物的管道，不能说它里面的血流得很快。", "脉搏": "语义：脉搏指跳动的感觉，不是装血的管道，不能说“脉搏里的血”。"}, "sentence_index": 6, "correct_answer": "动脉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "动脉负责把疼痛的信号传给大脑。", "explanation": "这里应该用〈神经〉。传递信号的是神经，动脉的作用是输送血液。"}, {"text": "动脉负责过滤身体里的废物。", "explanation": "这里应该用〈肾脏〉。过滤和排出废物是肾脏的作用，动脉不承担这项功能。"}, {"text": "动脉负责消化身体里的食物。", "explanation": "这里应该用〈胃〉。消化食物是胃的作用，动脉不负责消化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23352, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的颈上有一个很粗的动脉。", "corrected_sentence": "他的颈上有一条很粗的动脉。", "error_description": "量词错误：动脉是血管，应用量词“条”，不能用“个”。正确的说法是“一条很粗的动脉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23352, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的动脉比毛细血管很粗。", "corrected_sentence": "他的动脉比毛细血管粗。", "error_description": "比较错误：“比”字句的谓语前不能再加“很”，应说“比毛细血管粗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23354, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "公共", "is_correct": true, "explanation": "反义：「私人」指属于个人的，「公共」指属于大家的，二者相对。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线或颜色，与「私人」不构成反义。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚形容事物明白或字迹分明，与「私人」不构成反义。"}, {"text": "温暖", "is_correct": false, "explanation": "温暖形容气温或感情，与「私人」不构成反义。"}], "correct_answer": "公共", "explanations": {"公共": "反义：「私人」指属于个人的，「公共」指属于大家的，二者相对。", "明亮": "明亮形容光线或颜色，与「私人」不构成反义。", "清楚": "清楚形容事物明白或字迹分明，与「私人」不构成反义。", "温暖": "温暖形容气温或感情，与「私人」不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23354, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "寒冷", "is_correct": false, "explanation": "寒冷形容温度低，与「私人」不构成反义。"}, {"text": "公共", "is_correct": true, "explanation": "反义：「私人」指属于个人的，「公共」指属于大家的，二者相对。"}, {"text": "迅速", "is_correct": false, "explanation": "迅速形容速度快，与「私人」不构成反义。"}, {"text": "严格", "is_correct": false, "explanation": "严格形容要求或管理的程度，与「私人」不构成反义。"}], "correct_answer": "公共", "explanations": {"寒冷": "寒冷形容温度低，与「私人」不构成反义。", "公共": "反义：「私人」指属于个人的，「公共」指属于大家的，二者相对。", "迅速": "迅速形容速度快，与「私人」不构成反义。", "严格": "严格形容要求或管理的程度，与「私人」不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23354, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指一个人自己的，不是公家的。", "primary_collocate": null, "pronunciation": "sī rén", "ipa": "sɨ˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "这是我的私人电话，请不要乱打。", "target_word": "私人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在家里有一间私人书房。", "target_word": "私人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是私人的事，你别问了。", "target_word": "私人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他开着一辆私人汽车来上班。", "target_word": "私人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家私人医院的环境很好。", "target_word": "私人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要看别人的私人信件。", "target_word": "私人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园是大家的，不是私人的地方。", "target_word": "私人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他有一个私人司机，每天送他上班。", "target_word": "私人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条海边的路是私人的，外人不能进。", "target_word": "私人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板用公司的钱买私人用品，这样不对。", "target_word": "私人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "私人的", "label": "的字结构"}, {"form": "私人医院", "label": "复合"}, {"form": "私人电话", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容词，属于个人的、非公家或集体的，多修饰名词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fef3691-c05f-4979-b766-4af9a742d3ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23354, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寂静", "is_correct": false, "explanation": "语义：「寂静」形容环境安静，不能修饰电话，与「我的」所有关系也不符。"}, {"text": "私人", "is_correct": true, "explanation": "私人：属于个人的，不是公家或集体的。这里指说话人自己的电话，正确。"}, {"text": "公用", "is_correct": false, "explanation": "语义：公用电话属于公共，与“我的”所表示的个人所有相矛盾。"}, {"text": "陌生", "is_correct": false, "explanation": "搭配：「陌生」多指来历不明的来电，不能与表示所属的「我的」搭配。"}], "explanations": {"寂静": "语义：「寂静」形容环境安静，不能修饰电话，与「我的」所有关系也不符。", "私人": "私人：属于个人的，不是公家或集体的。这里指说话人自己的电话，正确。", "公用": "语义：公用电话属于公共，与“我的”所表示的个人所有相矛盾。", "陌生": "搭配：「陌生」多指来历不明的来电，不能与表示所属的「我的」搭配。"}, "sentence_index": 0, "correct_answer": "私人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一位私人的市长，负责管理全市的事务。", "explanation": "这里应该用〈公职〉。「私人」指不是公家的，市长属于公职，二者矛盾，不能说“私人的市长”。"}, {"text": "这条私人的马路是市政府修建的，所有车辆都可以通行。", "explanation": "这里应该用〈公共〉。「私人」指不是公家的，市政府修建、所有人都能通行的马路属于公共，二者矛盾。"}, {"text": "这所私人的医院是省里办的，所有人都能免费看病。", "explanation": "这里应该用〈公办〉。「私人」指不是公家的，“省里办的”属于公办，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23354, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小气", "is_correct": false, "explanation": "搭配：「小气」形容人的性格，不能用来修饰「地方」。"}, {"text": "私人", "is_correct": true, "explanation": "私人：属于个人的、不是公家的。这里说公园不是个人的地方，正确。"}, {"text": "高傲", "is_correct": false, "explanation": "搭配：「高傲」形容人的态度，不能修饰「地方」。"}, {"text": "狡猾", "is_correct": false, "explanation": "语义：「狡猾」指人的心机，与公园的性质不符。"}], "explanations": {"小气": "搭配：「小气」形容人的性格，不能用来修饰「地方」。", "私人": "私人：属于个人的、不是公家的。这里说公园不是个人的地方，正确。", "高傲": "搭配：「高傲」形容人的态度，不能修饰「地方」。", "狡猾": "语义：「狡猾」指人的心机，与公园的性质不符。"}, "sentence_index": 6, "correct_answer": "私人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家私人的银行由国家设立，负责管理全国的货币。", "explanation": "这里应该用〈国有〉。「私人」指不是公家的，由国家设立、管理货币的银行属于国有，二者矛盾。"}, {"text": "我们要尊重每个人的私人。", "explanation": "这里应该用〈隐私〉。「私人」是形容词，不能单独作名词指个人的秘密。"}, {"text": "我们反对私人主义。", "explanation": "这里应该用〈个人〉。「个人主义」是固定说法，不能说“私人主义”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23354, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老板有一个私人汽车。", "corrected_sentence": "这位老板有一辆私人汽车。", "error_description": "量词错误：「汽车」应搭配量词「辆」，不能用「个」，应说“一辆私人汽车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23354, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他请了一位私人地司机。", "corrected_sentence": "他请了一位私人司机。", "error_description": "结构助词错误：「私人」是形容词，直接修饰名词时中间不加“地”，“地”只用于修饰动词、形容词等状语。应为“他请了一位私人司机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
