INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23364, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23364, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "燃油是机器或汽车用来跑的油。", "primary_collocate": null, "pronunciation": "rán yóu", "ipa": "ɻan˧˥ joʊ̯˧˥", "syllable_count": 2, "sentences": [{"text": "我的车没有燃油了。", "target_word": "燃油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "燃油太贵，我们少开车。", "target_word": "燃油", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电动车不需要燃油。", "target_word": "燃油", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他去加油站买燃油。", "target_word": "燃油", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这辆车很省燃油。", "target_word": "燃油", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "卡车一次要加很多燃油。", "target_word": "燃油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "发动机没有燃油就不能工作。", "target_word": "燃油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些燃油是给拖拉机用的。", "target_word": "燃油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "摩托车的燃油用完了。", "target_word": "燃油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开慢一点可以节约燃油。", "target_word": "燃油", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "燃油车", "label": "复合"}, {"form": "燃油费", "label": "复合"}], "register": "中性", "sense_fingerprint": "汽车、机器靠它运转的油", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5714203-90c7-4816-b5d4-4f7aff98a03b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23364, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "燃油", "is_correct": true, "explanation": "正确：“没有燃油了”说的是汽车的油已用完，符合句意。"}, {"text": "面包", "is_correct": false, "explanation": "语义：汽车不能靠面包运转，“没有面包了”说的是食物，与汽车无关。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：汽车不靠咖啡运转，“没有咖啡了”与汽车的状态无关。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“没有空气”多用于轮胎，说车子“没有空气了”不成立。"}], "explanations": {"燃油": "正确：“没有燃油了”说的是汽车的油已用完，符合句意。", "面包": "语义：汽车不能靠面包运转，“没有面包了”说的是食物，与汽车无关。", "咖啡": "语义：汽车不靠咖啡运转，“没有咖啡了”与汽车的状态无关。", "空气": "搭配：“没有空气”多用于轮胎，说车子“没有空气了”不成立。"}, "sentence_index": 0, "correct_answer": "燃油"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的轴承要定期加燃油。", "explanation": "这里应该用〈润滑油〉。轴承需要润滑，燃油是机器用来燃烧的液体燃料，不用于润滑。"}, {"text": "厨房里用燃油做饭。", "explanation": "这里应该用〈食用油〉。“燃油”是机器用的燃料，不能用于烹饪，做饭应说“食用油”。"}, {"text": "这辆车加了一张燃油。", "explanation": "量词错误：燃油是液体，应用〈升〉〈桶〉等计量，不能用〈张〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23364, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "燃油", "is_correct": true, "explanation": "正确：发动机靠燃油燃烧工作，“没有燃油就不能工作”符合常识。"}, {"text": "眼睛", "is_correct": false, "explanation": "体貌：发动机没有眼睛，“眼睛”是人的器官，不能用来描述机器，句子不通。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：颜料与发动机工作无关，“没有颜料就不能工作”不成立。"}, {"text": "地图", "is_correct": false, "explanation": "语义：发动机不靠地图运转，“没有地图就不能工作”与句意不符。"}], "explanations": {"燃油": "正确：发动机靠燃油燃烧工作，“没有燃油就不能工作”符合常识。", "眼睛": "体貌：发动机没有眼睛，“眼睛”是人的器官，不能用来描述机器，句子不通。", "颜料": "语义：颜料与发动机工作无关，“没有颜料就不能工作”不成立。", "地图": "语义：发动机不靠地图运转，“没有地图就不能工作”与句意不符。"}, "sentence_index": 6, "correct_answer": "燃油"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汽车水箱里要加燃油。", "explanation": "这里应该用〈冷却液〉。水箱需要冷却液，燃油只用于燃烧，加进水箱会损坏发动机。"}, {"text": "他用燃油擦皮鞋，把鞋子擦得很亮。", "explanation": "这里应该用〈鞋油〉。擦鞋要用“鞋油”，“燃油”是机器、汽车用来跑的油，不用于擦鞋。"}, {"text": "钢笔里要加燃油。", "explanation": "这里应该用〈墨水〉。钢笔要加墨水，燃油是机器用的液体燃料，不能用于书写工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23364, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆车加了一个燃油。", "corrected_sentence": "这辆车加了一升燃油。", "error_description": "错误：燃油是液体，量词应用“升”“桶”等，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23364, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把燃油们倒进了油箱。", "corrected_sentence": "我把燃油倒进了油箱。", "error_description": "用词错误：“们”一般只加在指人的名词后，燃油是液体，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac33e917-ac39-42e0-8c99-cfb5585fcd2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23366, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23366, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23366, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "颗粒物是很小很小的东西，比如灰尘或烟，可以飘在空气里。", "primary_collocate": null, "pronunciation": "kē lì wù", "ipa": "kʰɤ˥ li˥˩ u˥˩", "syllable_count": 3, "sentences": [{"text": "风一吹，颗粒物就飘在空气里。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里的颗粒物多，我一打扫就咳嗽。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阳光下能看见空中的颗粒物。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抽烟会产生很多颗粒物。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家安装了空气净化器，用来清除颗粒物。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙尘天气里，颗粒物特别多。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "颗粒物太小了，口罩能挡住一部分。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子咳嗽，可能是吸入了颗粒物。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻里说，今天颗粒物超标了。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水能把空气中的颗粒物洗掉。", "target_word": "颗粒物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "细颗粒物", "label": "复合"}, {"form": "可吸入颗粒物", "label": "复合"}, {"form": "顆粒物", "label": "繁体"}], "register": "书面", "sense_fingerprint": "飘在空气里的很小的东西，如灰尘或烟", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d73da08-f1e3-4736-83d2-b9a3a45c59eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23366, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颗粒物", "is_correct": true, "explanation": "正确：颗粒物是飘在空气里很小的东西，风一吹就会飘起来。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是固体块状物，不会因为风吹就飘在空气里，句义不通。"}, {"text": "石头", "is_correct": false, "explanation": "体貌：石头又重又大，风吹不起来，与“飘在空气里”的描述矛盾。"}, {"text": "汽车", "is_correct": false, "explanation": "体貌：汽车体积太大，风吹不会让它飘在空气里。"}], "explanations": {"颗粒物": "正确：颗粒物是飘在空气里很小的东西，风一吹就会飘起来。", "玻璃": "语义：玻璃是固体块状物，不会因为风吹就飘在空气里，句义不通。", "石头": "体貌：石头又重又大，风吹不起来，与“飘在空气里”的描述矛盾。", "汽车": "体貌：汽车体积太大，风吹不会让它飘在空气里。"}, "sentence_index": 0, "correct_answer": "颗粒物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "花园里开满了颗粒物。", "explanation": "这里应该用〈鲜花〉。“开满”用于花，颗粒物是细小微粒，不会开放。"}, {"text": "他一口气喝了三杯颗粒物。", "explanation": "这里应该用〈水〉。“喝”的对象是液体或饮料，颗粒物是飘在空气里的微粒，不能喝。"}, {"text": "他早上把颗粒物穿在身上就出门了。", "explanation": "这里应该用〈衣服〉。“穿”的对象是衣服，颗粒物是飘在空气里的微粒，不能穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23366, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颗粒物", "is_correct": true, "explanation": "正确：颗粒物很小，口罩能挡住其中一部分，句义通顺。"}, {"text": "大树", "is_correct": false, "explanation": "体貌：大树体积很大，不会说“太小了”，与句中的描述矛盾。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，与口罩挡住的对象无关，句义不通。"}, {"text": "篮球", "is_correct": false, "explanation": "体貌：篮球并不算太小，而且不会飘在空气里被口罩挡住，与句义不符。"}], "explanations": {"颗粒物": "正确：颗粒物很小，口罩能挡住其中一部分，句义通顺。", "大树": "体貌：大树体积很大，不会说“太小了”，与句中的描述矛盾。", "冰箱": "语义：冰箱是家用电器，与口罩挡住的对象无关，句义不通。", "篮球": "体貌：篮球并不算太小，而且不会飘在空气里被口罩挡住，与句义不符。"}, "sentence_index": 6, "correct_answer": "颗粒物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子在教室里唱颗粒物。", "explanation": "这里应该用〈歌〉。“唱”的对象是歌曲，颗粒物不能唱。"}, {"text": "妈妈在厨房里用颗粒物包饺子。", "explanation": "这里应该用〈面皮〉。包饺子要用面皮和馅料，颗粒物不是食材。"}, {"text": "他在院子里种下了一些颗粒物。", "explanation": "这里应该用〈种子〉。“种下”的对象是种子或植株，颗粒物是飘在空气里的微粒，不能种。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23366, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一带的空气里飘着一只颗粒物。", "corrected_sentence": "这一带的空气里飘着大量颗粒物。", "error_description": "量词错误：颗粒物是许多细小微粒，不能用“只”计量，应该用“大量”或“一些”。正确说法是“飘着大量颗粒物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23366, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "清扫以后，屋里的颗粒物的减少了。", "corrected_sentence": "清扫以后，屋里的颗粒物减少了。", "error_description": "多了一个“的”：“颗粒物的减少”变成名词性短语，“了”没有可以附着的谓语，句子不通。应去掉这个“的”，说“屋里的颗粒物减少了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
