INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23368, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23368, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "有些东西会变成气体跑到空气里，比如水放久了会变少。", "primary_collocate": null, "pronunciation": "huī fā xìng", "ipa": "xweɪ̯˥ fa˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "酒精挥发性强，瓶盖要盖好。", "target_word": "挥发性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水放久了会变少，是因为有挥发性。", "target_word": "挥发性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "香水的挥发性大，味道很快就散了。", "target_word": "挥发性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汽油的挥发性很强，要远离火。", "target_word": "挥发性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这瓶药水挥发性强，用完要盖紧。", "target_word": "挥发性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "热水的挥发性比冷水强。", "target_word": "挥发性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "油的挥发性不高，放着也不会变少。", "target_word": "挥发性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，有挥发性的东西不要放在太阳下。", "target_word": "挥发性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糖没有挥发性，所以闻不到味道。", "target_word": "挥发性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你知道哪种液体的挥发性最强吗？", "target_word": "挥发性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "揮發性", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西变成气体跑到空气里的特点（名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62c45cbc-3149-46b9-a7c7-1923fe0f00ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23368, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "挥发性", "is_correct": true, "explanation": "正确。“酒精挥发性强”说明酒精容易变成气体，所以瓶盖要盖好。"}, {"text": "纯度", "is_correct": false, "explanation": "搭配：“纯度”说高低要用“高”，不说“强”；而且纯度与瓶盖要盖好无关。"}, {"text": "硬度", "is_correct": false, "explanation": "语义：酒精是液体，没有硬度，“酒精硬度强”不成立。"}, {"text": "密度", "is_correct": false, "explanation": "搭配：“密度”一般说“大”或“高”，不说“强”，句子不通。"}], "explanations": {"挥发性": "正确。“酒精挥发性强”说明酒精容易变成气体，所以瓶盖要盖好。", "纯度": "搭配：“纯度”说高低要用“高”，不说“强”；而且纯度与瓶盖要盖好无关。", "硬度": "语义：酒精是液体，没有硬度，“酒精硬度强”不成立。", "密度": "搭配：“密度”一般说“大”或“高”，不说“强”，句子不通。"}, "sentence_index": 0, "correct_answer": "挥发性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "糖的挥发性很好，放进水里很快就化了。", "explanation": "这里应该用〈溶解性〉。放进水里很快化掉说的是溶解，挥发性指变成气体跑到空气里。"}, {"text": "铜的挥发性很好，常用来做电线。", "explanation": "这里应该用〈导电性〉。做电线是因为铜能导电，挥发性与做电线无关。"}, {"text": "这个人的挥发性很强，一说话就发脾气。", "explanation": "挥发性只用于物质，指东西变成气体的特点，不能用来形容人的脾气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23368, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "挥发性", "is_correct": true, "explanation": "正确。“油的挥发性不高”说明油不容易变成气体，所以放着也不会变少。"}, {"text": "弹性", "is_correct": false, "explanation": "语义：“弹性”指物体恢复原状的能力，油没有这种性质，句子不通。"}, {"text": "韧性", "is_correct": false, "explanation": "搭配：“韧性”用来形容材料不易折断，不能用来描述油放着会不会变少。"}, {"text": "延展性", "is_correct": false, "explanation": "语义：“延展性”指材料能被拉长或压薄，与油放着会不会变少无关。"}], "explanations": {"挥发性": "正确。“油的挥发性不高”说明油不容易变成气体，所以放着也不会变少。", "弹性": "语义：“弹性”指物体恢复原状的能力，油没有这种性质，句子不通。", "韧性": "搭配：“韧性”用来形容材料不易折断，不能用来描述油放着会不会变少。", "延展性": "语义：“延展性”指材料能被拉长或压薄，与油放着会不会变少无关。"}, "sentence_index": 6, "correct_answer": "挥发性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种糖浆的挥发性很大，倒出来很慢。", "explanation": "这里应该用〈黏度〉。倒出来很慢说明的是黏稠程度，挥发性指变成气体的特点。"}, {"text": "酒精的挥发性是七十八摄氏度，加热要小心。", "explanation": "这里应该用〈沸点〉。七十八摄氏度是酒精开始沸腾的温度，挥发性不能用温度数字来表示。"}, {"text": "老师让我们比较一块挥发性的强弱。", "explanation": "这里应该用〈种〉。“挥发性”是抽象的特点，不能用〈块〉来计量，应说“一种挥发性”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23368, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这罐喷雾地挥发性很强，用完要拧紧。", "corrected_sentence": "这罐喷雾的挥发性很强，用完要拧紧。", "error_description": "错误形式：“喷雾地挥发性”，“地”用于修饰动词，修饰名词“挥发性”前应用“的”。正确形式：“喷雾的挥发性很强”，“的”连接名词与其修饰语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23368, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种香精是挥发性，用完要盖紧。", "corrected_sentence": "这种香精有挥发性，用完要盖紧。", "error_description": "错误形式：“是挥发性”，“是”用于判断，不能直接接表示性质的名词；表示物质具有某种性质应用“有”。正确形式：“有挥发性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
