INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23370, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "启动和停止的意思。", "primary_collocate": null, "pronunciation": "qǐ tíng", "ipa": "tɕʰi˨˩˦ tʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这台机器可以一键启停。", "target_word": "启停", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他用遥控器启停风扇。", "target_word": "启停", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "手机可以远程启停空调。", "target_word": "启停", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工人每天要启停水泵好几次。", "target_word": "启停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车在红灯前会自动启停。", "target_word": "启停", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个按钮用来启停发动机。", "target_word": "启停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教我们怎么启停这台机器。", "target_word": "启停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把洗衣机启停了好几次，还是不转。", "target_word": "启停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里别随便启停设备，会吵到邻居。", "target_word": "启停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电脑可以控制风扇自动启停。", "target_word": "启停", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "启停了", "label": "体标"}, {"form": "啟停", "label": "繁体"}], "register": "中性", "sense_fingerprint": "让机器设备启动并停止（动词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62c45cbc-3149-46b9-a7c7-1923fe0f00ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23370, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "启停", "is_correct": true, "explanation": "正确。“一键启停”指用一个按键控制设备的开和关。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：失眠是人的状态，机器不会失眠，与“一键”的操作语境不符。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：机器不呼吸，“一键呼吸”不能成立。"}, {"text": "思考", "is_correct": false, "explanation": "搭配：“一键”只与操作类动词搭配，不能与“思考”搭配。"}], "explanations": {"启停": "正确。“一键启停”指用一个按键控制设备的开和关。", "失眠": "语义：失眠是人的状态，机器不会失眠，与“一键”的操作语境不符。", "呼吸": "语义：机器不呼吸，“一键呼吸”不能成立。", "思考": "搭配：“一键”只与操作类动词搭配，不能与“思考”搭配。"}, "sentence_index": 0, "correct_answer": "启停"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个文件要启停后才能打开。", "explanation": "这里应该用〈启用〉。启停只指机器设备开始和停止工作，文件不能启停，应说“启用”。"}, {"text": "老师每天要启停学生好几次。", "explanation": "这里应该用〈制止〉。启停只用于机器设备，不能用来指人，人的停止要说“制止”。"}, {"text": "工人每天要启停天气好几次。", "explanation": "这里应该用〈改变〉。启停只能用于机器设备，天气不能被启停，应说“改变天气”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23370, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "启停", "is_correct": true, "explanation": "正确。“怎么启停这台机器”指教学生如何操作设备的开关。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”表示谢意，与教授操作的语境不符。"}, {"text": "原谅", "is_correct": false, "explanation": "语义：“原谅”表示宽恕，与教授操作的语境不符。"}, {"text": "讨好", "is_correct": false, "explanation": "搭配：“讨好”通常用于人，不能用来说讨好机器。"}], "explanations": {"启停": "正确。“怎么启停这台机器”指教学生如何操作设备的开关。", "感谢": "语义：“感谢”表示谢意，与教授操作的语境不符。", "原谅": "语义：“原谅”表示宽恕，与教授操作的语境不符。", "讨好": "搭配：“讨好”通常用于人，不能用来说讨好机器。"}, "sentence_index": 6, "correct_answer": "启停"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电脑可以控制老师自动启停。", "explanation": "这里应该用〈指挥〉。启停只用于机器设备，不能用来指人，指挥老师不能说“自动启停”。"}, {"text": "电脑可以自动启停天空。", "explanation": "这里应该用〈变化〉。启停只能用于机器设备，天空不能被启停，天空只会变化。"}, {"text": "电脑可以启停风扇的转速。", "explanation": "这里应该用〈调节〉。启停只表示开始和停止，不能用来改变转速，应说“调节转速”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23370, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人每天把启停水泵好几次。", "corrected_sentence": "工人每天启停水泵好几次。", "error_description": "错误：“把”字句中“把”后应接受事宾语再接动词，此句“把”后直接接动词“启停”，缺少受事；应删去“把”，说“启停水泵”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23370, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车间的水泵一天要启停着十几次。", "corrected_sentence": "车间的水泵一天要启停十几次。", "error_description": "体标错误：表示反复几次的动作不用“着”，“着”表示持续的状态，应说“启停十几次”，不能说“启停着十几次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
