INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23372, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23372, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "氮和氧的化合物的总称，是一类会污染空气的气体，汽车和工厂会排出它。", "primary_collocate": null, "pronunciation": "dàn yǎng huà wù", "ipa": "tan˥˩ jaŋ˨˩˦ xua˥˩ u˥˩", "syllable_count": 4, "sentences": [{"text": "汽车排出的氮氧化物会污染空气。", "target_word": "氮氧化物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂的烟里有很多氮氧化物。", "target_word": "氮氧化物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "氮氧化物是一种有害气体。", "target_word": "氮氧化物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "氮氧化物遇到水汽，会形成酸雨。", "target_word": "氮氧化物", "complexity_tier": "T3", "furigana": "dàn yǎng huà wù", "sentence_source": "generated"}, {"text": "马路边的氮氧化物比公园里多。", "target_word": "氮氧化物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，氮氧化物对人的肺不好。", "target_word": "氮氧化物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "少开车，就能减少氮氧化物。", "target_word": "氮氧化物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个机器能测出空气里的氮氧化物。", "target_word": "氮氧化物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "氮氧化物多的城市，天空常常是灰的。", "target_word": "氮氧化物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新规定要求工厂少排氮氧化物。", "target_word": "氮氧化物", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "科技", "sense_fingerprint": "汽车和工厂排出的、会污染空气的有害气体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d73da08-f1e3-4736-83d2-b9a3a45c59eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23372, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "氮氧化物", "is_correct": true, "explanation": "正确：氮氧化物是汽车排出的物质，会污染空气，与句义相符。"}, {"text": "氧气", "is_correct": false, "explanation": "语义：氧气不是汽车排出的有害物，也不会污染空气，与“污染空气”矛盾。"}, {"text": "电动车", "is_correct": false, "explanation": "语义：电动车是交通工具，不是排出的物质，句中“排出的……”后接的应当是气体。"}, {"text": "公共交通", "is_correct": false, "explanation": "搭配：“排出”后接的是物质，不能接“公共交通”这样的服务系统。"}], "explanations": {"氮氧化物": "正确：氮氧化物是汽车排出的物质，会污染空气，与句义相符。", "氧气": "语义：氧气不是汽车排出的有害物，也不会污染空气，与“污染空气”矛盾。", "电动车": "语义：电动车是交通工具，不是排出的物质，句中“排出的……”后接的应当是气体。", "公共交通": "搭配：“排出”后接的是物质，不能接“公共交通”这样的服务系统。"}, "sentence_index": 0, "correct_answer": "氮氧化物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民在地里撒了很多氮氧化物，庄稼长得特别好。", "explanation": "这里应该用〈化肥〉。撒在地里让庄稼长得好的是化肥；氮氧化物是有害的污染物，不能用来施肥。"}, {"text": "老人每天在公园里深深地呼吸氮氧化物。", "explanation": "这里应该用〈氧气〉。“呼吸”的对象是氧气或空气，氮氧化物是有害物质，不能这样呼吸。"}, {"text": "我每天早上都喝一杯氮氧化物。", "explanation": "这里应该用〈牛奶〉。“喝一杯”用于牛奶、水等饮料；氮氧化物是有害气体，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23372, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "氮氧化物", "is_correct": true, "explanation": "正确：少开车能减少的是汽车排出的氮氧化物，句义通顺。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“减少”后接的是数量或污染物，不能直接接“空气”，句子不通。"}, {"text": "人口", "is_correct": false, "explanation": "语义：少开车不会减少人口，句中的因果关系不成立。"}, {"text": "河水", "is_correct": false, "explanation": "语义：河水与开车无关，“少开车就能减少河水”与句义不符。"}], "explanations": {"氮氧化物": "正确：少开车能减少的是汽车排出的氮氧化物，句义通顺。", "空气": "搭配：“减少”后接的是数量或污染物，不能直接接“空气”，句子不通。", "人口": "语义：少开车不会减少人口，句中的因果关系不成立。", "河水": "语义：河水与开车无关，“少开车就能减少河水”与句义不符。"}, "sentence_index": 6, "correct_answer": "氮氧化物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冬天家里用氮氧化物取暖。", "explanation": "这里应该用〈煤〉。冬天取暖烧的是煤等燃料；氮氧化物是污染物，不能用来取暖。"}, {"text": "腌制食品时用了氮氧化物保鲜。", "explanation": "这里应该用〈亚硝酸盐〉。腌制食品时用的是亚硝酸盐类添加剂；氮氧化物不能用来保鲜。"}, {"text": "这个洞要用氮氧化物填平。", "explanation": "这里应该用〈水泥〉。填平坑洞要用水泥等建材；氮氧化物是有害气体，不能用来填充。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23372, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂的烟囱里排出了一只氮氧化物。", "corrected_sentence": "工厂的烟囱里排出了大量氮氧化物。", "error_description": "量词错误：氮氧化物是气体，不能用“只”计量，这里应该用“大量”表示数量。正确说法是“排出了大量氮氧化物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23372, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "汽车和工厂都会吃掉氮氧化物。", "corrected_sentence": "汽车和工厂都会排放氮氧化物。", "error_description": "动词错误：“吃”的对象是食物，氮氧化物是气体，不能吃；汽车和工厂排出它，应说“排放”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd7ef09-cde6-4a93-9b54-256566023fc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
