INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23374, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "车停着但发动机还在转的样子。", "primary_collocate": null, "pronunciation": "dài sù", "ipa": "taɪ̯˥˩ su˥˩", "syllable_count": 2, "sentences": [{"text": "车停在路边，发动机还在怠速。", "target_word": "怠速", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等红灯时，车子一直在怠速。", "target_word": "怠速", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "司机下车买水，车却怠速了十分钟。", "target_word": "怠速", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他让车怠速，自己进店取货。", "target_word": "怠速", "complexity_tier": "T3", "furigana": "dài sù", "sentence_source": "generated"}, {"text": "车子怠速太久会浪费油。", "target_word": "怠速", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "冬天车可以先怠速一会儿再走。", "target_word": "怠速", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "停车等人时，最好别让车怠速。", "target_word": "怠速", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把车停在门口，让它怠速等人。", "target_word": "怠速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车怠速的时候，仪表盘上的指针还在动。", "target_word": "怠速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卡车怠速时声音很大，邻居都睡不着。", "target_word": "怠速", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "怠速了", "label": "体标"}, {"form": "怠速运转", "label": "复合"}], "register": "中性", "sense_fingerprint": "车停着而发动机仍在空转（动词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62c45cbc-3149-46b9-a7c7-1923fe0f00ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23374, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "怠速", "is_correct": true, "explanation": "正确答案，指车停着而发动机仍在空转。"}, {"text": "代数", "is_correct": false, "explanation": "shù（第四声）与 sù（第四声）声母不同：sh 与 s，意思是代数。"}, {"text": "待续", "is_correct": false, "explanation": "xù（第四声）与 sù（第四声）声母不同：x 与 s，意思是待续。"}, {"text": "代付", "is_correct": false, "explanation": "fù（第四声）与 sù（第四声）声母不同：f 与 s，意思是代为付款。"}, {"text": "带路", "is_correct": false, "explanation": "lù（第四声）与 sù（第四声）声母不同：l 与 s，意思是带领道路。"}], "explanations": {"怠速": "正确答案，指车停着而发动机仍在空转。", "代数": "shù（第四声）与 sù（第四声）声母不同：sh 与 s，意思是代数。", "待续": "xù（第四声）与 sù（第四声）声母不同：x 与 s，意思是待续。", "代付": "fù（第四声）与 sù（第四声）声母不同：f 与 s，意思是代为付款。", "带路": "lù（第四声）与 sù（第四声）声母不同：l 与 s，意思是带领道路。"}, "sentence_index": null, "correct_answer": "怠速"}, "level_3": {"options": [{"text": "怠速", "is_correct": true, "explanation": "正确。“还在怠速”指车停着而发动机仍在空转，与“停在路边”相呼应。"}, {"text": "熄火", "is_correct": false, "explanation": "搭配：“还在”不能与“熄火”搭配，熄火说明发动机已经停了。"}, {"text": "停止", "is_correct": false, "explanation": "语义：发动机“停止”与“还在”的状态矛盾。"}, {"text": "滑行", "is_correct": false, "explanation": "语义：车已经停在路边，不会“滑行”。"}], "explanations": {"怠速": "正确。“还在怠速”指车停着而发动机仍在空转，与“停在路边”相呼应。", "熄火": "搭配：“还在”不能与“熄火”搭配，熄火说明发动机已经停了。", "停止": "语义：发动机“停止”与“还在”的状态矛盾。", "滑行": "语义：车已经停在路边，不会“滑行”。"}, "sentence_index": 0, "correct_answer": "怠速"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "车子陷在泥里，车轮却一直怠速。", "explanation": "这里应该用〈空转〉。怠速指车停着时发动机仍在运转，车轮不能说怠速。"}, {"text": "司机一踩油门，车子就怠速冲了出去。", "explanation": "这里应该用〈加速〉。怠速指车停着、发动机空转，踩油门后车子冲出去要说“加速”。"}, {"text": "熄火以后，车子还在怠速。", "explanation": "这里应该用〈滑行〉。熄火后发动机已经停止，“怠速”指发动机仍在空转，车子应说“滑行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23374, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "怠速", "is_correct": true, "explanation": "正确。“别让车怠速”指不要让停着的车空转，符合“停车等人”的语境。"}, {"text": "滑行", "is_correct": false, "explanation": "语义：“滑行”指车借惯性移动，与“停车等人”相矛盾。"}, {"text": "上路", "is_correct": false, "explanation": "语义：“上路”指车辆开始行驶，与“停车等人”相矛盾。"}, {"text": "加速", "is_correct": false, "explanation": "语义：“加速”指车速变快，与“停车等人”的状态相反。"}], "explanations": {"怠速": "正确。“别让车怠速”指不要让停着的车空转，符合“停车等人”的语境。", "滑行": "语义：“滑行”指车借惯性移动，与“停车等人”相矛盾。", "上路": "语义：“上路”指车辆开始行驶，与“停车等人”相矛盾。", "加速": "语义：“加速”指车速变快，与“停车等人”的状态相反。"}, "sentence_index": 6, "correct_answer": "怠速"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "车子怠速行驶，很快就到了目的地。", "explanation": "这里应该用〈开〉。怠速指车停着、发动机空转，车子开起来要说“开”，不能说怠速。"}, {"text": "司机把油门踩到底，车子却怠速。", "explanation": "这里应该用〈提速〉。怠速指不踩油门时的空转，油门踩到底后车子应说“提速”，不能说怠速。"}, {"text": "这辆车刚出厂，发动机还没转就怠速了。", "explanation": "这里应该用〈启动〉。发动机没转时不能说怠速，应说“刚启动”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23374, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "红灯亮了，车子先怠速的等一会儿。", "corrected_sentence": "红灯亮了，车子先怠速等一会儿。", "error_description": "“的”误加：“先怠速等一会儿”中动词“怠速”后不能加“的”，应说“先怠速等一会儿”，不能说“先怠速的等一会儿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23374, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车子很怠速，发动机已经停了。", "corrected_sentence": "车子不怠速，发动机已经停了。", "error_description": "副词错误：“怠速”是动词，不能用程度副词“很”修饰，表示否定应说“不怠速”，不能说“很怠速”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
