INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23376, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "光化学是研究光如何让东西发生化学变化。", "primary_collocate": null, "pronunciation": "guāng huà xué", "ipa": "kuaŋ˥ xu̯a˥˩ ɕɥe˧˥", "syllable_count": 3, "sentences": [{"text": "光化学研究光怎么改变东西。", "target_word": "光化学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学光化学，要先知道光是什么。", "target_word": "光化学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "光化学告诉我们，太阳光会让东西变色。", "target_word": "光化学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我最喜欢的课是光化学。", "target_word": "光化学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "光化学能解释衣服为什么晒久会变色。", "target_word": "光化学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老照片会变黄，这是光化学的问题。", "target_word": "光化学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在大学里教光化学。", "target_word": "光化学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "光化学跟光有很大的关系。", "target_word": "光化学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学习光化学的时候，他做了很多实验。", "target_word": "光化学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "植物靠光合作用长大，这和光化学有关系。", "target_word": "光化学", "complexity_tier": "T3", "furigana": "zhí wù kào guāng hé zuò yòng zhǎng dà, zhè hé guāng huà xué yǒu guān xi。", "sentence_source": "generated"}], "morphological_forms": [{"form": "光化学反应", "label": "复合"}, {"form": "光化学烟雾", "label": "复合"}], "register": "中性", "sense_fingerprint": "研究光怎样使物质发生化学变化的学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62c45cbc-3149-46b9-a7c7-1923fe0f00ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23376, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "光化学", "is_correct": true, "explanation": "正确：光化学是研究光怎样改变东西的学科，句中“研究光怎么改变东西”指的正是它。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是地方，不能作为研究光变化的学科。"}, {"text": "体育", "is_correct": false, "explanation": "语义：体育研究的是身体活动，与光怎样改变东西无关。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“研究”的主语应是人或学科，“面包”是食物，不能作研究的主体。"}], "explanations": {"光化学": "正确：光化学是研究光怎样改变东西的学科，句中“研究光怎么改变东西”指的正是它。", "厨房": "语义：厨房是地方，不能作为研究光变化的学科。", "体育": "语义：体育研究的是身体活动，与光怎样改变东西无关。", "面包": "搭配：“研究”的主语应是人或学科，“面包”是食物，不能作研究的主体。"}, "sentence_index": 0, "correct_answer": "光化学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老师用光化学解释汽车为什么会动。", "explanation": "这里应该用〈物理〉。物理研究力与运动，光化学研究光引起的化学变化，二者不能互换。"}, {"text": "我最喜欢的一把光化学很难学。", "explanation": "这里应该用〈门〉。〈把〉用于有柄的器具，学科应用〈门〉，应说“一门光化学”。"}, {"text": "这本书专门讲解细胞的分裂，是光化学的书。", "explanation": "这里应该用〈生物学〉。生物学研究细胞和生命现象，光化学研究光引起的化学变化，细胞分裂不属于光化学的范围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23376, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "光化学", "is_correct": true, "explanation": "正确：“她在大学里教光化学”，光化学是可以教授的学科，符合句意。"}, {"text": "烤箱", "is_correct": false, "explanation": "语义：烤箱是电器，不是可以被教授的知识，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能作为大学里被教授的内容。"}, {"text": "地板", "is_correct": false, "explanation": "搭配：“教”的对象应是知识或技能，“地板”是物体，不能与“教”搭配。"}], "explanations": {"光化学": "正确：“她在大学里教光化学”，光化学是可以教授的学科，符合句意。", "烤箱": "语义：烤箱是电器，不是可以被教授的知识，句意不通。", "天气": "语义：天气是自然现象，不能作为大学里被教授的内容。", "地板": "搭配：“教”的对象应是知识或技能，“地板”是物体，不能与“教”搭配。"}, "sentence_index": 6, "correct_answer": "光化学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "光化学老师在黑板上证明了一个定理，同学们都听懂了。", "explanation": "这里应该用〈数学〉。证明定理属于数学，光化学研究光引起的化学变化，不能用来证明数学定理。"}, {"text": "光化学研究的是人的情绪怎样变化，很有意思。", "explanation": "这里应该用〈心理学〉。心理学研究人的情绪与心理活动，光化学研究光引起的化学变化，不研究情绪。"}, {"text": "这门光化学研究电池里的电流，很有意思。", "explanation": "这里应该用〈电化学〉。电化学研究电与化学反应的关系，电池里的电流属于电化学；光化学研究光引起的化学变化，不研究电流。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23376, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想学一只光化学。", "corrected_sentence": "我想学一门光化学。", "error_description": "错误：“一只光化学”，“只”用于动物或成对物件中的一个，学科应用“门”。正确为“一门光化学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23376, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他光化学很有兴趣。", "corrected_sentence": "他对光化学很有兴趣。", "error_description": "错误：漏掉了介词“对”。“有兴趣”的对象要用“对……有兴趣”引出，应写作“对光化学很有兴趣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23382, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23382, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23382, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "是很多很小很小的脏东西飘在空气里，看起来像云一样，看不清远处的东西。", "primary_collocate": null, "pronunciation": "yān wù", "ipa": "jɛn˥ wu˥˩", "syllable_count": 2, "sentences": [{"text": "今天城里有烟雾，看不清远处。", "target_word": "烟雾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上的烟雾像云一样。", "target_word": "烟雾", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "烟雾太大，司机把车开得很慢。", "target_word": "烟雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气里有烟雾，我不想出门。", "target_word": "烟雾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "森林起火了，天空中全是烟雾。", "target_word": "烟雾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "烟雾里的灰尘很脏，对身体不好。", "target_word": "烟雾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风一吹，烟雾就散开了。", "target_word": "烟雾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在烟雾中走了很久。", "target_word": "烟雾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天空灰灰的，全是烟雾，没有蓝天。", "target_word": "烟雾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们看不见高楼，因为烟雾太浓。", "target_word": "烟雾", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "团", "label": "量词"}, {"form": "股", "label": "量词"}, {"form": "烟雾弹", "label": "复合"}, {"form": "煙霧", "label": "繁体"}], "register": "通用", "sense_fingerprint": "飘在空气里像云一样、让人看不清远处的细小脏东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a6dee57-3677-400c-a29a-64b4982be465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23382, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "烟雾", "is_correct": true, "explanation": "正确：烟雾飘在城里，让人看不清远处，句意成立。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光让人看得更清楚，与“看不清远处”矛盾。"}, {"text": "歌声", "is_correct": false, "explanation": "语义：歌声不影响视线，与“看不清远处”没有关系。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：“城里有”后接的是可以存在的事物，“尺寸”是度量，不能这样用。"}], "explanations": {"烟雾": "正确：烟雾飘在城里，让人看不清远处，句意成立。", "阳光": "语义：阳光让人看得更清楚，与“看不清远处”矛盾。", "歌声": "语义：歌声不影响视线，与“看不清远处”没有关系。", "尺寸": "搭配：“城里有”后接的是可以存在的事物，“尺寸”是度量，不能这样用。"}, "sentence_index": 0, "correct_answer": "烟雾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天上飘着一只烟雾，像云一样。", "explanation": "这里量词应用〈团〉或〈股〉，不用“只”。烟雾不用“只”计量。"}, {"text": "这团烟雾很干净，我很喜欢看它。", "explanation": "这里应该用〈浑浊〉。烟雾是浑浊的脏颗粒，不能用来形容干净。"}, {"text": "他在森林里采了一篮烟雾。", "explanation": "这里把烟雾当成了可以采摘装篮的〈野菜〉；烟雾是飘浮的颗粒，不能采来装篮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23382, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "烟雾", "is_correct": true, "explanation": "正确：烟雾是一团飘浮的颗粒，风一吹就会散开，句意成立。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“散开”多用于烟雾、人群，不说雨散开，雨应说“停”。"}, {"text": "灯光", "is_correct": false, "explanation": "语义：灯光不会被风吹散，句子不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不是可以随风散开的东西。"}], "explanations": {"烟雾": "正确：烟雾是一团飘浮的颗粒，风一吹就会散开，句意成立。", "雨": "搭配：“散开”多用于烟雾、人群，不说雨散开，雨应说“停”。", "灯光": "语义：灯光不会被风吹散，句子不通。", "价格": "语义：价格不是可以随风散开的东西。"}, "sentence_index": 6, "correct_answer": "烟雾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房里用烟雾煮了汤。", "explanation": "这里应该用〈蒸汽〉或〈火〉。烟雾是脏颗粒，不能用来煮东西；煮汤要用蒸汽或火。"}, {"text": "他的文章写得像烟雾一样清楚明白。", "explanation": "这里应该用〈模糊〉。烟雾让人看不清，比喻文章时要说模糊，不能说清楚明白。"}, {"text": "他把烟雾捏成一个球，放进口袋里。", "explanation": "这里把烟雾当成了可以捏成球的〈面团〉；烟雾是飘浮的颗粒，无法捏成球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23382, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天上飘着一个烟雾。", "corrected_sentence": "天上飘着一股烟雾。", "error_description": "量词错误：烟雾用“股”或“团”计量，“个”不适合。正确：一股烟雾；错误：一个烟雾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23382, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大风把烟雾们吹散了。", "corrected_sentence": "大风把烟雾吹散了。", "error_description": "“烟雾”是物质名词，不能加“们”表示复数；“们”只用于指人或拟人的名词。应去掉“们”，说“大风把烟雾吹散了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
