INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23384, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "雾霾是空气中的脏东西，让天空变得灰蒙蒙的。", "primary_collocate": null, "pronunciation": "wù mái", "ipa": "u˥˩ mai̯˧˥", "syllable_count": 2, "sentences": [{"text": "今天天空灰蒙蒙的，是雾霾。", "target_word": "雾霾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雾霾让天空变得很灰。", "target_word": "雾霾", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不喜欢雾霾。", "target_word": "雾霾", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "有雾霾的时候，我们要戴口罩。", "target_word": "雾霾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雾霾里有很多脏东西。", "target_word": "雾霾", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "空气不好是因为有雾霾。", "target_word": "雾霾", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下雨以后，雾霾就少了。", "target_word": "雾霾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雾霾来了，远处的楼都看不见。", "target_word": "雾霾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人和孩子在雾霾里最好别出去。", "target_word": "雾霾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在雾霾中走了很久，咳嗽得很厉害。", "target_word": "雾霾", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场雾霾", "label": "量词"}, {"form": "雾霾天", "label": "复合"}], "register": "中性", "sense_fingerprint": "空气中让天空发灰的脏东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62c45cbc-3149-46b9-a7c7-1923fe0f00ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23384, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雾霾", "is_correct": true, "explanation": "正确：雾霾是空气中的脏东西，会让天空灰蒙蒙的，符合句意。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光让天空明亮，与“灰蒙蒙”矛盾，不能解释天空的样子。"}, {"text": "晚霞", "is_correct": false, "explanation": "语义：晚霞色彩鲜艳，与“灰蒙蒙的天空”不符。"}, {"text": "彩虹", "is_correct": false, "explanation": "搭配：彩虹出现在雨后阳光中，“是彩虹”无法解释“灰蒙蒙的天空”。"}], "explanations": {"雾霾": "正确：雾霾是空气中的脏东西，会让天空灰蒙蒙的，符合句意。", "阳光": "语义：阳光让天空明亮，与“灰蒙蒙”矛盾，不能解释天空的样子。", "晚霞": "语义：晚霞色彩鲜艳，与“灰蒙蒙的天空”不符。", "彩虹": "搭配：彩虹出现在雨后阳光中，“是彩虹”无法解释“灰蒙蒙的天空”。"}, "sentence_index": 0, "correct_answer": "雾霾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋子里的雾霾太多了，我们要赶快打扫。", "explanation": "这里应该用〈灰尘〉。〈打扫〉用于灰尘、垃圾等实物，雾霾是弥散在空气中的污染，不能被打扫。"}, {"text": "我看见天上有一根雾霾。", "explanation": "这里应该用〈场〉。〈根〉用于细长的东西，雾霾是大面积弥漫的空气现象，应说“一场雾霾”。"}, {"text": "屋子里有一把雾霾，我们看不清东西。", "explanation": "这里应该用〈场〉。〈把〉用于有柄的器具，雾霾是弥漫的空气现象，应说“一场雾霾”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23384, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雾霾", "is_correct": true, "explanation": "正确：下雨后空气变干净，雾霾减少，“雾霾就少了”符合句意。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视与下雨、空气状况无因果关系，句意不通。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：钢笔与下雨后的变化无关，这个句子说不通。"}, {"text": "足球", "is_correct": false, "explanation": "搭配：“就少了”说的是某种现象减少，“足球”不是下雨后会减少的对象。"}], "explanations": {"雾霾": "正确：下雨后空气变干净，雾霾减少，“雾霾就少了”符合句意。", "电视": "语义：电视与下雨、空气状况无因果关系，句意不通。", "钢笔": "语义：钢笔与下雨后的变化无关，这个句子说不通。", "足球": "搭配：“就少了”说的是某种现象减少，“足球”不是下雨后会减少的对象。"}, "sentence_index": 6, "correct_answer": "雾霾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "早上的雾霾很干净，空气清新得让人想深呼吸。", "explanation": "这里应该用〈雾〉。雾是水汽凝结而成的，可以说清新；雾霾是空气中的脏东西，不能说“干净”。"}, {"text": "篝火燃起了很多雾霾，大家都咳嗽了。", "explanation": "这里应该用〈烟〉。篝火燃烧产生的是烟，雾霾是大范围的空气污染，不能说篝火燃起雾霾。"}, {"text": "屋角有一盏雾霾，把屋子照得很亮。", "explanation": "这里应该用〈场〉。〈盏〉用于灯具，雾霾是弥漫的空气现象，应说“一场雾霾”；雾霾不能发光，也照不亮屋子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23384, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天有一只大雾霾。", "corrected_sentence": "今天有一场大雾霾。", "error_description": "错误：“一只大雾霾”，“只”用于动物或成对物品中的一个，雾霾应使用量词“场”。正确为“一场大雾霾”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23384, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雾霾重很，我们别出门。", "corrected_sentence": "雾霾很重，我们别出门。", "error_description": "错误：“重很”，程度副词“很”应放在形容词“重”前面。正确形式为“很重”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec7996bc-fa14-4e46-b074-79ecf7269fcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
