INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23392, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "车或船带人走。", "primary_collocate": null, "pronunciation": "zài kè", "ipa": "tsai˥˩ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "这条小船最多载客八人。", "target_word": "载客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆面包车违规载客，司机每次都挨罚。", "target_word": "载客", "complexity_tier": "T3", "furigana": "zhè liàng miànbāochē wéiguī zài kè, sījī měi cì dōu āifá", "sentence_source": "generated"}, {"text": "河边的渡船每天载客过河。", "target_word": "载客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆旅游大巴今天载客去山里。", "target_word": "载客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出租车亮着红灯，说明正在载客。", "target_word": "载客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆货车改装后可以载客了。", "target_word": "载客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张开三轮车在镇上载客挣钱。", "target_word": "载客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖上的游船一次载客二十人。", "target_word": "载客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天出租车很忙，司机一直在载客。", "target_word": "载客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条船太旧了，已经不再载客。", "target_word": "载客", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "载客了", "label": "体标"}, {"form": "载客量", "label": "复合"}], "register": "中性", "sense_fingerprint": "日常生活中，车或船带着人走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a6dee57-3677-400c-a29a-64b4982be465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23392, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "载客", "is_correct": true, "explanation": "载客指车或船带着人走，是本词的读音与意思。"}, {"text": "宰客", "is_correct": false, "explanation": "zǎi（第三声）与 zài（第四声）声调不同，宰客意思是敲诈顾客。"}, {"text": "待客", "is_correct": false, "explanation": "dài 与 zài 声母不同（d 与 z），待客意思是招待客人。"}, {"text": "代课", "is_correct": false, "explanation": "dài 与 zài 声母不同（d 与 z），代课意思是临时替别人上课。"}], "explanations": {"载客": "载客指车或船带着人走，是本词的读音与意思。", "宰客": "zǎi（第三声）与 zài（第四声）声调不同，宰客意思是敲诈顾客。", "待客": "dài 与 zài 声母不同（d 与 z），待客意思是招待客人。", "代课": "dài 与 zài 声母不同（d 与 z），代课意思是临时替别人上课。"}, "sentence_index": null, "correct_answer": "载客"}, "level_3": {"options": [{"text": "载客", "is_correct": true, "explanation": "“最多载客八人”说的是船只能运送的人数，符合语境。"}, {"text": "装修", "is_correct": false, "explanation": "语义：装修指修饰房屋，不能用来说船只的载人数量，句意不通。"}, {"text": "发放", "is_correct": false, "explanation": "语义：发放指分给他人财物，不能用来说船只的载人数量，句意不通。"}, {"text": "驾驶", "is_correct": false, "explanation": "配价：“驾驶”的宾语是车船，不能直接带“八人”作宾语。"}], "explanations": {"载客": "“最多载客八人”说的是船只能运送的人数，符合语境。", "装修": "语义：装修指修饰房屋，不能用来说船只的载人数量，句意不通。", "发放": "语义：发放指分给他人财物，不能用来说船只的载人数量，句意不通。", "驾驶": "配价：“驾驶”的宾语是车船，不能直接带“八人”作宾语。"}, "sentence_index": 0, "correct_answer": "载客"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位画家在画室里载客。", "explanation": "这里应该用〈作画〉。载客指车或船带人走，不指画家在画室里作画。"}, {"text": "饭店服务员热情载客。", "explanation": "这里应该用〈接待〉。载客只指运送乘客，不指在饭店里接待客人。"}, {"text": "士兵在战场上载客。", "explanation": "这里应该用〈作战〉。载客指车或船带人走，不指士兵在战场上打仗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23392, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "载客", "is_correct": true, "explanation": "“开三轮车在镇上挣钱”的方式就是载客，符合语境。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：打扫是清理场地，与开车运人挣钱无关，句意不通。"}, {"text": "停放", "is_correct": false, "explanation": "语义：停放指把车停在某处，不能表示靠它挣钱。"}, {"text": "行驶", "is_correct": false, "explanation": "配价：“行驶”是不及物动词，后面不能直接带“挣钱”这类宾语。"}], "explanations": {"载客": "“开三轮车在镇上挣钱”的方式就是载客，符合语境。", "打扫": "语义：打扫是清理场地，与开车运人挣钱无关，句意不通。", "停放": "语义：停放指把车停在某处，不能表示靠它挣钱。", "行驶": "配价：“行驶”是不及物动词，后面不能直接带“挣钱”这类宾语。"}, "sentence_index": 6, "correct_answer": "载客"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朋友们到车站为我载客。", "explanation": "这里应该用〈送行〉。朋友只是来送别，并不运送乘客，不能说“载客”。"}, {"text": "保安在大门口载客。", "explanation": "这里应该用〈值守〉。载客指车或船带人走，不指保安在大门口值班守卫。"}, {"text": "护士在病房里载客。", "explanation": "这里应该用〈护理〉。载客指车或船带人走，不指护士照顾病人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23392, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这艘旧渡船今天载客十个游客。", "corrected_sentence": "这艘旧渡船今天载了十个游客。", "error_description": "“载客”后面已有“游客”，宾语重复。应把“客”换成动词后的“了”，说“载了十个游客”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23392, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老王以前在镇上载客过。", "corrected_sentence": "老王以前在镇上载过客。", "error_description": "应为“载过客”。“过”表示经历，要紧跟动词，放在动词后、宾语前；“载客过”的说法不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
