INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23394, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "意思是东西有多结实，或者力气有多大。", "primary_collocate": null, "pronunciation": "qiáng dù", "ipa": "tɕʰjɑŋ˧˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "这把椅子的强度不够，别站上去。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个盒子的强度很高，可以放重东西。", "target_word": "强度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买自行车要看车架的强度。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条绳子的强度能吊起一个人。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的玩具要有一定的强度，不能一碰就坏。", "target_word": "强度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座木桥的强度怎么样？", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "铁门的强度比木门高得多。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书架的强度不够，放太多书会倒。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个包的强度很好，装十本书也不会破。", "target_word": "强度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先检查一下桥的强度。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "強度", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西有多结实、能承受多大的力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8e754af-a1d8-4f78-a77f-c537910b3253') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23394, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "强度", "is_correct": true, "explanation": "正确答案：强度，qiáng dù，指东西有多结实、能承受多大的力。"}, {"text": "强大", "is_correct": false, "explanation": "dà（第四声）与 dù（第四声）韵母不同，意思是力量大。"}, {"text": "强盗", "is_correct": false, "explanation": "dào（第四声）与 dù（第四声）韵母不同，意思是抢夺财物的人。"}, {"text": "抢渡", "is_correct": false, "explanation": "qiǎng（第三声）与 qiáng（第二声）声调不同，抢渡的意思是抢先渡过江河。"}], "explanations": {"强度": "正确答案：强度，qiáng dù，指东西有多结实、能承受多大的力。", "强大": "dà（第四声）与 dù（第四声）韵母不同，意思是力量大。", "强盗": "dào（第四声）与 dù（第四声）韵母不同，意思是抢夺财物的人。", "抢渡": "qiǎng（第三声）与 qiáng（第二声）声调不同，抢渡的意思是抢先渡过江河。"}, "sentence_index": null, "correct_answer": "强度"}, "level_3": {"options": [{"text": "强度", "is_correct": true, "explanation": "正确：「不够」说椅子承受力的强弱，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“不够”说承受力或数量，颜色不说“不够”，句意也和“别站上去”无关。"}, {"text": "性格", "is_correct": false, "explanation": "语义：椅子没有性格，句子说不通。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：椅子没有脾气，句子说不通。"}], "explanations": {"强度": "正确：「不够」说椅子承受力的强弱，符合句意。", "颜色": "搭配：“不够”说承受力或数量，颜色不说“不够”，句意也和“别站上去”无关。", "性格": "语义：椅子没有性格，句子说不通。", "脾气": "语义：椅子没有脾气，句子说不通。"}, "sentence_index": 0, "correct_answer": "强度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条绳子的强度足够从二楼垂到地面。", "explanation": "这里应该用〈长度〉。强度说承受力的大小，够不够长要说长度。"}, {"text": "这块石头的强度很大，同样大小的东西就特别重。", "explanation": "这里应该用〈密度〉。强度说东西结实的程度，单位体积的重量要用密度，不能用强度来解释轻重。"}, {"text": "这架梯子的强度很高，我够不着天花板。", "explanation": "这里应该用〈高度〉。强度说东西结实的程度，离地有多高要用高度，不能用强度来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23394, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "强度", "is_correct": true, "explanation": "正确：「比木门高得多」比较的是门的结实程度，符合句意。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“高得多”不修饰年龄，年龄要说“大得多”。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”专指人的身长，门不说身高，句子不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“高得多”不修饰体重，体重要说“重得多”。"}], "explanations": {"强度": "正确：「比木门高得多」比较的是门的结实程度，符合句意。", "年龄": "搭配：“高得多”不修饰年龄，年龄要说“大得多”。", "身高": "语义：“身高”专指人的身长，门不说身高，句子不通。", "体重": "搭配：“高得多”不修饰体重，体重要说“重得多”。"}, "sentence_index": 6, "correct_answer": "强度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块铁板的强度是两毫米。", "explanation": "这里应该用〈厚度〉。强度是抵抗外力的能力，不能用毫米计量。"}, {"text": "这块玻璃的强度很高，能看清楚里面。", "explanation": "这里应该用〈透明度〉。强度说东西的结实程度，能不能看透要用透明度。"}, {"text": "这座桥的强度有十米，车可以并排开。", "explanation": "这里应该用〈宽度〉。强度说东西承受力的大小，桥面有多宽要用宽度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23394, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把椅子的强度够足，可以放心坐。", "corrected_sentence": "这把椅子的强度足够，可以放心坐。", "error_description": "语序错误：“够足”应为“足够”。说强度达到所需的程度时，要说“强度足够”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23394, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个书架的强度提了高了，可以多放些书。", "corrected_sentence": "这个书架的强度提高了，可以多放些书。", "error_description": "拆分错误：“提高”是不能拆开的词，“了”不能插在中间。应说“强度提高了”，不能说“强度提了高了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
