INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23396, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "买东西时，剩下的不够一个整数的钱。", "primary_collocate": null, "pronunciation": "líng tou", "ipa": "liŋ˧˥ tʰou", "syllable_count": 2, "sentences": [{"text": "一共八十三块，老板说零头不要了。", "target_word": "零头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我买菜花了二十七块五，老板不收五毛的零头。", "target_word": "零头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市今天抹了零头，我只付了一百块。", "target_word": "零头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总共四十八块六，收银员把零头抹掉了。", "target_word": "零头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋九十九块九，零头就算了吧。", "target_word": "零头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板人很好，我们的零头他没收。", "target_word": "零头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "结账的时候，零头我用手机付了。", "target_word": "零头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他买东西花了一百零二块，零头两块他用现金付了。", "target_word": "零头", "complexity_tier": "T3", "furigana": "tā mǎi dōng xi huā le yī bǎi líng èr kuài, líng tou liǎng kuài tā yòng xiàn jīn fù le.", "sentence_source": "generated"}, {"text": "菜一共三十六块四，老板只收三十六，没收零头。", "target_word": "零头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买完东西，妈妈让我把零头放进存钱罐。", "target_word": "零头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "零頭", "label": "繁体"}], "register": "口语", "sense_fingerprint": "买东西结账时不够整数的零碎钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8e754af-a1d8-4f78-a77f-c537910b3253') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23396, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "零头", "is_correct": true, "explanation": "零头：买东西时不够整数的零碎钱，符合「老板说零头不要了」的语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气与付钱、抹零无关，「老板说天气不要了」说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是结账时可以不要的东西，句子不通。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：「不要」后接的是东西或钱款，不说「不要时间」。"}], "explanations": {"零头": "零头：买东西时不够整数的零碎钱，符合「老板说零头不要了」的语境。", "天气": "语义：天气与付钱、抹零无关，「老板说天气不要了」说不通。", "颜色": "语义：颜色不是结账时可以不要的东西，句子不通。", "时间": "搭配：「不要」后接的是东西或钱款，不说「不要时间」。"}, "sentence_index": 0, "correct_answer": "零头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我付了五十块，收银员找了我一块零头。", "explanation": "这里应该用〈零钱〉。找给顾客的钱叫零钱；零头是不足整数的剩余部分，不是找回的钱。"}, {"text": "这次结账，收银员把整数凑成了零头。", "explanation": "这里应该说「把零头凑成整数」。凑整是把零头补足为整数，方向不能颠倒，不能把整数凑成零头。"}, {"text": "这次结账，老板把整数抹掉了，只收五十。", "explanation": "这里应该用〈抹零〉。抹零是去掉结账时不足整数的零头，整数本身不能抹掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23396, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "零头", "is_correct": true, "explanation": "零头：买东西时不够整数的零碎钱，符合「结账时用手机付零头」的语境。"}, {"text": "现金", "is_correct": false, "explanation": "语义：现金是实物钱，不能用手机付，与句意矛盾。"}, {"text": "小票", "is_correct": false, "explanation": "搭配：「付」的对象是钱款或账单，不说「付小票」。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：礼物不是用来付款的，与「用手机付」矛盾。"}], "explanations": {"零头": "零头：买东西时不够整数的零碎钱，符合「结账时用手机付零头」的语境。", "现金": "语义：现金是实物钱，不能用手机付，与句意矛盾。", "小票": "搭配：「付」的对象是钱款或账单，不说「付小票」。", "礼物": "语义：礼物不是用来付款的，与「用手机付」矛盾。"}, "sentence_index": 6, "correct_answer": "零头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次结账，我买了一包零头。", "explanation": "这里应该用〈零食〉。零食指小吃，零头指不足整数的钱，不能当作所买的东西。"}, {"text": "这次结账，我付的一百块全是零头。", "explanation": "这里把整笔钱说成零头，零头只指不足整数的剩余钱，整笔钱不能说全是零头。"}, {"text": "这次结账，老板把我的零头记作了利润。", "explanation": "这里应该用〈利润〉。利润是收入减去成本后的盈余，零头是结账时不足整数的钱，不能记作利润。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23396, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板把零头抹在了，只收五十。", "corrected_sentence": "老板把零头抹掉了，只收五十。", "error_description": "结果补语错误：「抹」后接「掉」表示去除，「抹在」不成立。正确形式是「抹掉」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23396, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "找钱的时候，我把一只零头放进了口袋。", "corrected_sentence": "找钱的时候，我把一点零头放进了口袋。", "error_description": "「零头」前应用量词「点」（或「些」）；「只」用于动物或单个的物件，不能修饰「零头」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
