INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23400, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让事情发生。", "primary_collocate": null, "pronunciation": "shǐ de", "ipa": "ʂʅ˨˩ tɤ", "syllable_count": 2, "sentences": [{"text": "大雨使得路很滑，我们走得很慢。", "target_word": "使得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个好消息使得大家都很高兴。", "target_word": "使得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网络使得世界变小了。", "target_word": "使得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气太冷，使得他生病了。", "target_word": "使得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的努力使得公司越来越好。", "target_word": "使得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机的出现使得生活方便了很多。", "target_word": "使得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一场大雪使得火车晚点了两个小时。", "target_word": "使得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师的话使得我明白了学习很重要。", "target_word": "使得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "交通不好，使得很多人不想去那里。", "target_word": "使得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的笑话使得整个教室都笑了起来。", "target_word": "使得", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "某事物导致某种结果出现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf9dc599-3173-4820-a892-52e831b34649') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23400, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "使得", "is_correct": true, "explanation": "使得表示某事物导致某种结果，大雨导致路很滑，符合句意。"}, {"text": "同意", "is_correct": false, "explanation": "语义：「同意」的主语必须是人，大雨不能同意路很滑。"}, {"text": "陪", "is_correct": false, "explanation": "配价：「陪」需要有被陪伴的人作宾语，「陪路很滑」不成立。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：「讨论」需要有人参与议论，大雨讨论路很滑说不通。"}], "explanations": {"使得": "使得表示某事物导致某种结果，大雨导致路很滑，符合句意。", "同意": "语义：「同意」的主语必须是人，大雨不能同意路很滑。", "陪": "配价：「陪」需要有被陪伴的人作宾语，「陪路很滑」不成立。", "讨论": "语义：「讨论」需要有人参与议论，大雨讨论路很滑说不通。"}, "sentence_index": 0, "correct_answer": "使得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我使得自己很高兴。", "explanation": "这里应该用〈让自己〉。使得多用于叙述某事引起的客观结果，不用来说自己的心情；表示自己高兴要说「让自己高兴」。"}, {"text": "我使得这把刀来切菜。", "explanation": "这里应该用〈使用〉。使得表示导致某种结果，不表示「用」的意思，「使用这把刀」才是正确说法。"}, {"text": "使得大家安静下来！", "explanation": "这里应该用〈让〉。〈让〉可以用于祈使句，如「让大家安静下来！」；使得是书面叙述用语，不用于命令或请求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23400, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "使得", "is_correct": true, "explanation": "使得表示某事物导致某种结果，一场大雪造成火车晚点，符合句意。"}, {"text": "批评", "is_correct": false, "explanation": "语义：「批评」的施事必须是人，一场大雪不能批评火车。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：「祝贺」需要有人表达祝福，一场大雪祝贺火车晚点说不通。"}, {"text": "照顾", "is_correct": false, "explanation": "配价：「照顾」的宾语应是人或需要照料的对象，「照顾火车晚点」不成立。"}], "explanations": {"使得": "使得表示某事物导致某种结果，一场大雪造成火车晚点，符合句意。", "批评": "语义：「批评」的施事必须是人，一场大雪不能批评火车。", "祝贺": "语义：「祝贺」需要有人表达祝福，一场大雪祝贺火车晚点说不通。", "照顾": "配价：「照顾」的宾语应是人或需要照料的对象，「照顾火车晚点」不成立。"}, "sentence_index": 6, "correct_answer": "使得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈不使得我们进屋。", "explanation": "这里应该用〈不让〉。使得表示导致某种结果，不用于允许或禁止；不准别人进来要说「不让我们进屋」。"}, {"text": "他提前出门，使得明天下雨。", "explanation": "这里应该用〈预计〉。使得连接的两件事必须有因果关系；提前出门与明天下雨没有因果，推测后事应说〈预计〉。"}, {"text": "他买了一本书，使得天气很好。", "explanation": "这里应该用〈恰好〉。使得表示导致某种结果，买书与天气没有因果关系，只是同时发生应说〈恰好〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23400, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场雨使得了我们的旅行推迟了。", "corrected_sentence": "这场雨使得我们的旅行推迟了。", "error_description": "错误：「了」紧跟在「使得」后面。「使得」后应直接接一个主谓小句「我们的旅行推迟了」，「了」应放在「推迟」之后，不能紧跟「使得」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23400, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次考试的难度使得的很多同学紧张了。", "corrected_sentence": "这次考试的难度使得很多同学紧张了。", "error_description": "错误：「使得」后面多加了「的」。「使得」后直接接兼语「很多同学」，应写作「使得很多同学紧张了」，「的」不能放在「使得」和「很多同学」之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
