INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23402, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "脏东西让空气、水和土地变坏了。", "primary_collocate": null, "pronunciation": "huán jìng wū rǎn", "ipa": "xwan˧˥ tɕiŋ˥˩ u˥ ɻan˨˩˦", "syllable_count": 4, "sentences": [{"text": "垃圾太多会造成环境污染。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环境污染让河水变臭了。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了减少环境污染，我们坐地铁上班。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子的环境污染很严重。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车多了，环境污染也变重了。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，乱扔垃圾会带来环境污染。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环境污染使鸟儿越来越少。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在研究怎么治理环境污染。", "target_word": "环境污染", "complexity_tier": "T3", "furigana": "huán jìng wū rǎn", "sentence_source": "generated"}, {"text": "环境污染对我们的身体不好。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近的工厂造成了环境污染。", "target_word": "环境污染", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "環境污染", "label": "繁体"}], "register": "中性", "sense_fingerprint": "垃圾、废气、废水让空气、水和土地变脏变坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8e754af-a1d8-4f78-a77f-c537910b3253') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23402, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "环境污染", "is_correct": true, "explanation": "正确：「造成」的结果是环境污染，与「垃圾太多」的因果关系相符。"}, {"text": "好运", "is_correct": false, "explanation": "语义：垃圾太多不会带来好运，与前文的因果语境相反。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：垃圾不能造成友谊，「造成友谊」与前文语境不符。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：「造成」后接抽象的结果，「眼睛」是器官，不能说「造成眼睛」。"}], "explanations": {"环境污染": "正确：「造成」的结果是环境污染，与「垃圾太多」的因果关系相符。", "好运": "语义：垃圾太多不会带来好运，与前文的因果语境相反。", "友谊": "语义：垃圾不能造成友谊，「造成友谊」与前文语境不符。", "眼睛": "搭配：「造成」后接抽象的结果，「眼睛」是器官，不能说「造成眼睛」。"}, "sentence_index": 0, "correct_answer": "环境污染"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个村子开展了环境污染。", "explanation": "这里应该用〈环境治理〉。「开展」的对象是有组织的工作，环境污染是要消除的现象，不能被开展。"}, {"text": "这次活动的目的是环境污染。", "explanation": "这里应该用〈生态保护〉。活动的目的应是积极的目标，环境污染是要消除的问题，不能作为目的。"}, {"text": "我在河边看到一只环境污染。", "explanation": "这里应该用〈种〉。「只」多用于动物和单件物品，环境污染是抽象现象，量词应用「种」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23402, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "环境污染", "is_correct": true, "explanation": "正确：「使鸟儿越来越少」的原因是环境污染，与句意相符。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光不会使鸟儿越来越少，与句中的因果语境相反。"}, {"text": "笑容", "is_correct": false, "explanation": "语义：笑容不会影响鸟类数量，「笑容使鸟儿越来越少」不成立。"}, {"text": "食堂", "is_correct": false, "explanation": "搭配：「使」后的施事应是能导致变化的事物，「食堂」是场所，不能与「使鸟儿越来越少」搭配。"}], "explanations": {"环境污染": "正确：「使鸟儿越来越少」的原因是环境污染，与句意相符。", "阳光": "语义：阳光不会使鸟儿越来越少，与句中的因果语境相反。", "笑容": "语义：笑容不会影响鸟类数量，「笑容使鸟儿越来越少」不成立。", "食堂": "搭配：「使」后的施事应是能导致变化的事物，「食堂」是场所，不能与「使鸟儿越来越少」搭配。"}, "sentence_index": 6, "correct_answer": "环境污染"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片湖正在进行环境污染。", "explanation": "这里应该用〈环境恢复〉。「进行」后接治理、恢复等工作，环境污染是需要消除的现象，不能被进行。"}, {"text": "专家进行了环境污染。", "explanation": "这里应该用〈环境评估〉。「进行」后接评估、检测等工作，环境污染不是可以进行的工作。"}, {"text": "我在新闻里看到一条环境污染。", "explanation": "这里应该用〈种〉。「条」多用于河流、消息、道路等，环境污染是抽象现象，量词应用「种」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23402, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市民们一起抗议这家工厂造成地环境污染。", "corrected_sentence": "市民们一起抗议这家工厂造成的环境污染。", "error_description": "定语标记错误：修饰名词「环境污染」的动词性定语后应用「的」，不能用「地」（「地」用于动词前作状语）。正确形式是「造成的环境污染」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23402, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个村子存在一块严重的环境污染。", "corrected_sentence": "这个村子存在一种严重的环境污染。", "error_description": "量词错误：「块」用于有块状形状的具体物体或地块，环境污染是抽象现象，应用「种」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d30997-af0e-4d47-865d-2a3175a99dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
