INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23414, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大家生活需要的公共设施，比如道路、桥梁、水电。", "primary_collocate": null, "pronunciation": "jī chǔ shè shī", "ipa": "tɕi˥ ʈʂʰu˨˩˦ ʂɤ˥˩ ʂʅ˥", "syllable_count": 4, "sentences": [{"text": "这个城市的基础设施很好。", "target_word": "基础设施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区的基础设施还不够完善。", "target_word": "基础设施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府正在建设新的基础设施。", "target_word": "基础设施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路和桥都是重要的基础设施。", "target_word": "基础设施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村要多花钱建设基础设施。", "target_word": "基础设施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的基础设施老了，路也不好走。", "target_word": "基础设施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了好的基础设施，人们生活更方便。", "target_word": "基础设施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水、电和网络都是基础设施。", "target_word": "基础设施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校附近的基础设施越来越多。", "target_word": "基础设施", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为小镇修建了基础设施。", "target_word": "基础设施", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "基礎設施", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大家生活需要的公共设施，如道路、桥梁、水电", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0cc0c3-2668-4386-9dc2-289c59985202') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23414, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基础设施", "is_correct": true, "explanation": "正确：「基础设施」指道路、水电等大家共用的设施，可以作为城市的特点来评价，符合「很好」。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：「噪音」不能用「很好」来评价，「这个城市的噪音很好」语义不通。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：「垃圾」是需要清理的东西，不能说城市的垃圾「很好」。"}, {"text": "疾病", "is_correct": false, "explanation": "搭配：「很好」用于评价状态或质量，不与「疾病」搭配。"}], "explanations": {"基础设施": "正确：「基础设施」指道路、水电等大家共用的设施，可以作为城市的特点来评价，符合「很好」。", "噪音": "语义：「噪音」不能用「很好」来评价，「这个城市的噪音很好」语义不通。", "垃圾": "语义：「垃圾」是需要清理的东西，不能说城市的垃圾「很好」。", "疾病": "搭配：「很好」用于评价状态或质量，不与「疾病」搭配。"}, "sentence_index": 0, "correct_answer": "基础设施"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂今年买了很多新的基础设施，用来生产汽车。", "explanation": "这里应该用〈设备〉。「基础设施」指道路、桥梁、水电等大家共用的公共设施，工厂的生产机器属于设备，不能说成基础设施。"}, {"text": "这篇文章的基础设施很清楚，读起来很容易。", "explanation": "这里应该用〈结构〉。「基础设施」指道路、水电等大家共用的公共设施，文章的组织框架要说「结构」。"}, {"text": "运动员们用的基础设施都很新。", "explanation": "这里应该用〈器材〉。运动员用的是体育器材，「基础设施」指公共设施，不指运动用的器具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb151336-7222-40c5-a287-147726e4414a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23414, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基础设施", "is_correct": true, "explanation": "正确：「好的基础设施」能让人们的生活更方便，与后句的「生活更方便」因果一致。"}, {"text": "肥料", "is_correct": false, "explanation": "语义：「肥料」是给庄稼用的，与「人们生活更方便」没有关系。"}, {"text": "烟雾", "is_correct": false, "explanation": "语义：「烟雾」会让生活变差，与「生活更方便」的结果矛盾。"}, {"text": "化石", "is_correct": false, "explanation": "搭配：「好的化石」不是常见说法，且「化石」与便利的生活无关。"}], "explanations": {"基础设施": "正确：「好的基础设施」能让人们的生活更方便，与后句的「生活更方便」因果一致。", "肥料": "语义：「肥料」是给庄稼用的，与「人们生活更方便」没有关系。", "烟雾": "语义：「烟雾」会让生活变差，与「生活更方便」的结果矛盾。", "化石": "搭配：「好的化石」不是常见说法，且「化石」与便利的生活无关。"}, "sentence_index": 6, "correct_answer": "基础设施"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "士兵们背着新的基础设施去训练。", "explanation": "这里应该用〈装备〉。士兵背的是个人装备，「基础设施」是大家共用的公共设施，不能背在身上。"}, {"text": "他的基础设施很好，一学就会。", "explanation": "这里应该用〈功底〉。「基础设施」指道路、水电等大家共用的公共设施，说个人的学习水平要用「功底」，不能说「基础设施」。"}, {"text": "客厅里摆着新买的基础设施，很漂亮。", "explanation": "这里应该用〈家具〉。「基础设施」指道路、水电等公共设施，不指客厅里的家具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb151336-7222-40c5-a287-147726e4414a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23414, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一把基础设施是去年建成的。", "corrected_sentence": "这一套基础设施是去年建成的。", "error_description": "量词错误：「基础设施」应与「套」搭配，说「这一套基础设施」，不能用「把」（「把」用于有柄的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb151336-7222-40c5-a287-147726e4414a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23414, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条基础设施已经用了十年。", "corrected_sentence": "这套基础设施已经用了十年。", "error_description": "量词错误：「基础设施」应用「套」计量，「条」用于细长的事物，不能修饰「基础设施」，应说「这套基础设施」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb151336-7222-40c5-a287-147726e4414a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
