INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23418, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "制造就是把东西做出来，比如工人制造玩具。", "primary_collocate": null, "pronunciation": "zhì zào", "ipa": "ʈʂɻ̩⁵¹ tsɑʊ̯⁵¹", "syllable_count": 2, "sentences": [{"text": "这家工厂制造汽车。", "target_word": "制造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们在工厂里制造玩具。", "target_word": "制造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司制造过很多手机。", "target_word": "制造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用机器制造这种杯子。", "target_word": "制造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工厂每天制造一千双鞋。", "target_word": "制造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸在工厂制造自行车。", "target_word": "制造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家公司想制造更好的电视。", "target_word": "制造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些椅子是工人在北京制造的。", "target_word": "制造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人制造了很多新桌子。", "target_word": "制造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在制造一辆新火车。", "target_word": "制造", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "制造了", "label": "体标"}, {"form": "制造过", "label": "体标"}, {"form": "制造商", "label": "复合"}, {"form": "制造业", "label": "复合"}], "register": "中性", "sense_fingerprint": "用工具或机器把东西做出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89604cde-aa36-49a3-b834-19b3606a7411') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23418, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "制造", "is_correct": true, "explanation": "正确。制造指用工具或机器把东西做出来，读作 zhì zào。"}, {"text": "织造", "is_correct": false, "explanation": "zhī（第一声）与 zhì（第四声）声调不同，意思是纺织，不是制造。"}, {"text": "铸造", "is_correct": false, "explanation": "zhù（第四声）与 zhì 韵母不同（u 与 i），意思是熔化金属后浇铸成器物，不是制造。"}, {"text": "缔造", "is_correct": false, "explanation": "dì 与 zhì 声母不同（d 与 zh），意思是创立、建立，不是制造。"}], "explanations": {"制造": "正确。制造指用工具或机器把东西做出来，读作 zhì zào。", "织造": "zhī（第一声）与 zhì（第四声）声调不同，意思是纺织，不是制造。", "铸造": "zhù（第四声）与 zhì 韵母不同（u 与 i），意思是熔化金属后浇铸成器物，不是制造。", "缔造": "dì 与 zhì 声母不同（d 与 zh），意思是创立、建立，不是制造。"}, "sentence_index": null, "correct_answer": "制造"}, "level_3": {"options": [{"text": "制造", "is_correct": true, "explanation": "正确。制造汽车是这家工厂的生产活动，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：工厂不会吃汽车，“吃”与“汽车”的语义不相容。"}, {"text": "驾驶", "is_correct": false, "explanation": "配价：“驾驶”需要能开车的人作施事，“工厂”不能驾驶汽车。"}, {"text": "唱", "is_correct": false, "explanation": "语义：汽车不能唱，“唱”不能带“汽车”作宾语。"}], "explanations": {"制造": "正确。制造汽车是这家工厂的生产活动，符合句意。", "吃": "语义：工厂不会吃汽车，“吃”与“汽车”的语义不相容。", "驾驶": "配价：“驾驶”需要能开车的人作施事，“工厂”不能驾驶汽车。", "唱": "语义：汽车不能唱，“唱”不能带“汽车”作宾语。"}, "sentence_index": 0, "correct_answer": "制造"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌是他十年前制造的。", "explanation": "这里应该用〈创作〉。制造用于做出实物，歌曲要用〈创作〉。"}, {"text": "他们在会上制造了一个新的计划。", "explanation": "这里应该用〈制定〉。制造用于做出实物或引起事故、混乱等，计划要用〈制定〉。"}, {"text": "我们班制造了一场比赛。", "explanation": "这里应该用〈举办〉。制造用于做出实物，比赛要用〈举办〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23418, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "制造", "is_correct": true, "explanation": "正确。制造更好的电视是这家公司的生产目标，符合句意。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的宾语是衣物，不能接“电视”。"}, {"text": "喝", "is_correct": false, "explanation": "语义：电视不能喝，“喝”与“电视”的语义不相容。"}, {"text": "游", "is_correct": false, "explanation": "配价：“游”不带事物宾语，不能接“电视”作宾语。"}], "explanations": {"制造": "正确。制造更好的电视是这家公司的生产目标，符合句意。", "穿": "搭配：“穿”的宾语是衣物，不能接“电视”。", "喝": "语义：电视不能喝，“喝”与“电视”的语义不相容。", "游": "配价：“游”不带事物宾语，不能接“电视”作宾语。"}, "sentence_index": 6, "correct_answer": "制造"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他想制造一个朋友。", "explanation": "这里应该用〈交〉。制造用于物品，交朋友不能用“制造”。"}, {"text": "这位作家制造了一部小说。", "explanation": "这里应该用〈写〉。制造指做出实物，小说是写出来的，要用〈写〉。"}, {"text": "妈妈每天制造一顿晚饭。", "explanation": "这里应该用〈做〉。制造多用于工业产品，做饭要用〈做〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23418, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司每年把手机制造。", "corrected_sentence": "这家公司每年把手机制造出来。", "error_description": "错误：“把”字句中动词后面需要补语或“了”等成分，不能只说“把手机制造”。正确说法是：这家公司每年把手机制造出来。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23418, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们正在制造了一种新的机器。", "corrected_sentence": "我们正在制造一种新的机器。", "error_description": "错误：“正在”表示动作正在进行，不能与表示完成的“了”同用。正确说法是：我们正在制造一种新的机器。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23422, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "宽敞", "is_correct": true, "explanation": "反义：“高密度”指东西挤在一起、很满，“宽敞”指空间大、不挤，二者构成反义。"}, {"text": "清楚", "is_correct": false, "explanation": "与“高密度”无反义关系，“清楚”形容明白、不模糊。"}, {"text": "美丽", "is_correct": false, "explanation": "与“高密度”无反义关系，“美丽”形容外貌或景色的好看。"}, {"text": "柔软", "is_correct": false, "explanation": "与“高密度”无反义关系，“柔软”形容质地或触感。"}], "correct_answer": "宽敞", "explanations": {"宽敞": "反义：“高密度”指东西挤在一起、很满，“宽敞”指空间大、不挤，二者构成反义。", "清楚": "与“高密度”无反义关系，“清楚”形容明白、不模糊。", "美丽": "与“高密度”无反义关系，“美丽”形容外貌或景色的好看。", "柔软": "与“高密度”无反义关系，“柔软”形容质地或触感。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23422, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "空旷", "is_correct": true, "explanation": "反义：“高密度”指东西挤满，“空旷”指没有东西、不拥挤，二者构成反义。"}, {"text": "缓慢", "is_correct": false, "explanation": "与“高密度”无反义关系，“缓慢”形容速度慢。"}, {"text": "复杂", "is_correct": false, "explanation": "与“高密度”无反义关系，“复杂”形容事物头绪多、不简单。"}, {"text": "响亮", "is_correct": false, "explanation": "与“高密度”无反义关系，“响亮”形容声音大而清晰。"}], "correct_answer": "空旷", "explanations": {"空旷": "反义：“高密度”指东西挤满，“空旷”指没有东西、不拥挤，二者构成反义。", "缓慢": "与“高密度”无反义关系，“缓慢”形容速度慢。", "复杂": "与“高密度”无反义关系，“复杂”形容事物头绪多、不简单。", "响亮": "与“高密度”无反义关系，“响亮”形容声音大而清晰。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23422, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "东西挤在一起，很满。", "primary_collocate": null, "pronunciation": "gāo mì dù", "ipa": "kau˥ mi˥˩ tu˥˩", "syllable_count": 3, "sentences": [{"text": "市中心有很多高密度的住宅楼。", "target_word": "高密度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高密度的停车位让司机很难转弯。", "target_word": "高密度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里是高密度的商业区，到处都是小店。", "target_word": "高密度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高密度的座位让乘客没有地方伸腿。", "target_word": "高密度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他住在一个高密度的老小区里。", "target_word": "高密度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高密度的楼房挡住了窗外的阳光。", "target_word": "高密度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家餐厅的高密度桌椅让服务员走不过去。", "target_word": "高密度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高密度的广告让路人看得眼花。", "target_word": "高密度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个展览的高密度展品多得看不过来。", "target_word": "高密度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高密度的货架上堆满了箱子。", "target_word": "高密度", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "高密度：东西挤在一起、很满很拥挤，日常说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f4ca28-5514-4bef-9e2b-fe5bad49018c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23422, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高密度", "is_correct": true, "explanation": "正确：“高密度的住宅楼”指楼房挤在一起，与“市中心”的语境相合，句意通顺。"}, {"text": "高温", "is_correct": false, "explanation": "语义：“高温”指气温高，与“市中心住宅楼”的描述无关，句子说不通。"}, {"text": "高效", "is_correct": false, "explanation": "搭配：“效率”指做事的成效，不能用来修饰住宅楼。"}, {"text": "高强度", "is_correct": false, "explanation": "搭配：“强度”说的是材料或劳动的承受程度，不能用来描述住宅楼的分布。"}], "explanations": {"高密度": "正确：“高密度的住宅楼”指楼房挤在一起，与“市中心”的语境相合，句意通顺。", "高温": "语义：“高温”指气温高，与“市中心住宅楼”的描述无关，句子说不通。", "高效": "搭配：“效率”指做事的成效，不能用来修饰住宅楼。", "高强度": "搭配：“强度”说的是材料或劳动的承受程度，不能用来描述住宅楼的分布。"}, "sentence_index": 0, "correct_answer": "高密度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子的高密度让它很明亮。", "explanation": "这里应该用〈明亮〉。明亮指光线充足，“高密度”指东西挤在一起，与光线明暗无关，不能这样说。"}, {"text": "他对朋友的高密度感情让人感动。", "explanation": "这里应该用〈深厚〉。“高密度”只用来说东西挤在一起，描述感情要用“深厚”。"}, {"text": "这间客厅的高密度让全家人很舒服。", "explanation": "这里应该用〈宽敞〉。宽敞指空间大、不拥挤，“高密度”指东西挤在一起，二者意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23422, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高密度", "is_correct": true, "explanation": "正确：“高密度桌椅”指桌椅摆得很挤，所以服务员走不过去，句意通顺。"}, {"text": "高亮", "is_correct": false, "explanation": "语义：“高亮”指亮度高，与桌椅挡住通道的意思不相关。"}, {"text": "高速", "is_correct": false, "explanation": "搭配：“速度”不用来修饰桌椅，句子说的是摆放太挤。"}, {"text": "高频", "is_correct": false, "explanation": "搭配：“频”指次数，不能修饰桌椅的摆放。"}], "explanations": {"高密度": "正确：“高密度桌椅”指桌椅摆得很挤，所以服务员走不过去，句意通顺。", "高亮": "语义：“高亮”指亮度高，与桌椅挡住通道的意思不相关。", "高速": "搭配：“速度”不用来修饰桌椅，句子说的是摆放太挤。", "高频": "搭配：“频”指次数，不能修饰桌椅的摆放。"}, "sentence_index": 6, "correct_answer": "高密度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片森林的高密度树林让阳光很容易照进来。", "explanation": "这里应该用〈稀疏〉。稀疏指分布得不密，阳光才容易照进来；“高密度”指东西挤在一起，与句意矛盾。"}, {"text": "这个广场的高密度让人感到冷清。", "explanation": "这里应该用〈空旷〉。空旷指没有东西、人少，才会让人觉得冷清；“高密度”指挤满，不能用来说广场冷清。"}, {"text": "这间教室的高密度让每个学生都有很大的活动空间。", "explanation": "这里应该用〈宽敞〉。宽敞指空间大、不拥挤，与“高密度”（挤在一起）意思相反，句子自相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23422, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把高密度座位让同学们转不开身。", "corrected_sentence": "这排高密度座位让同学们转不开身。", "error_description": "错误形式“这把高密度座位”：“座位”应配“排”“个”等量词，“把”多用于有柄的物件，不能修饰座位。正确形式为“这排高密度座位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23422, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家超市的很高密度货架让顾客很难转身。", "corrected_sentence": "这家超市的高密度货架让顾客很难转身。", "error_description": "错误形式“很高密度货架”：“高密度”是已经表示“挤满”的形容词，不能再被“很”修饰。正确形式为“高密度货架”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23424, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下降", "is_correct": true, "explanation": "反义：“攀升”指向高处移动，“下降”指向低处移动，二者构成反义。"}, {"text": "凝固", "is_correct": false, "explanation": "与“攀升”无反义关系，“凝固”指液体变成固体。"}, {"text": "演唱", "is_correct": false, "explanation": "与“攀升”无反义关系，“演唱”指唱歌给别人听。"}, {"text": "观察", "is_correct": false, "explanation": "与“攀升”无反义关系，“观察”指仔细看并研究。"}], "correct_answer": "下降", "explanations": {"下降": "反义：“攀升”指向高处移动，“下降”指向低处移动，二者构成反义。", "凝固": "与“攀升”无反义关系，“凝固”指液体变成固体。", "演唱": "与“攀升”无反义关系，“演唱”指唱歌给别人听。", "观察": "与“攀升”无反义关系，“观察”指仔细看并研究。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
