INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23424, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "往上升，比如东西从低处到高处。", "primary_collocate": null, "pronunciation": "pān shēng", "ipa": "pʰan˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "热气球慢慢攀升到天空中。", "target_word": "攀升", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "飞机起飞后很快攀升到高空。", "target_word": "攀升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山间的雾气沿着山坡缓缓攀升。", "target_word": "攀升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟迎着风向高处攀升。", "target_word": "攀升", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "火箭点火后迅速攀升。", "target_word": "攀升", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "烟从烟囱里缓缓攀升，飘向天空。", "target_word": "攀升", "complexity_tier": "T3", "furigana": "yān cóng yān cōng lǐ huǎn huǎn pān shēng piāo xiàng tiān kōng", "sentence_source": "generated"}, {"text": "登山队沿着陡坡一路攀升。", "target_word": "攀升", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "风筝借着风力攀升到云里。", "target_word": "攀升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无人机缓缓攀升，拍到了整座城市。", "target_word": "攀升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞鸟在山谷中盘旋着攀升。", "target_word": "攀升", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "攀升了", "label": "体标（了）"}, {"form": "攀升着", "label": "体标（着）"}, {"form": "攀升过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "攀升：物体或人从低处向高处移动上升，指具体位置变高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f4ca28-5514-4bef-9e2b-fe5bad49018c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23424, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "攀升", "is_correct": true, "explanation": "正确：“攀升到天空中”指热气球向高处移动，与“慢慢”搭配，句意通顺。"}, {"text": "降落", "is_correct": false, "explanation": "语义：“降落”指从高处往低处落，与“到天空中”的向上移动矛盾。"}, {"text": "倒", "is_correct": false, "explanation": "搭配：“倒”指向一侧跌落，不能用来描述热气球向上移动。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”指放映声音或影像，不能用来描述热气球的移动。"}], "explanations": {"攀升": "正确：“攀升到天空中”指热气球向高处移动，与“慢慢”搭配，句意通顺。", "降落": "语义：“降落”指从高处往低处落，与“到天空中”的向上移动矛盾。", "倒": "搭配：“倒”指向一侧跌落，不能用来描述热气球向上移动。", "播放": "搭配：“播放”指放映声音或影像，不能用来描述热气球的移动。"}, "sentence_index": 0, "correct_answer": "攀升"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小猫从屋顶攀升到地面。", "explanation": "这里应该用〈跳下〉。攀升指往上升，从屋顶到地面是向下移动，要用跳下。"}, {"text": "孩子在草地上攀升，慢慢往前走。", "explanation": "这里应该用〈爬〉。攀升强调向高处移动，在平地上向前行走要用爬。"}, {"text": "河水在平坦的河床上攀升，一路向东流去。", "explanation": "这里应该用〈流〉。攀升指向高处移动，河水沿平地向东流动要用流。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23424, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "攀升", "is_correct": true, "explanation": "正确：“一路攀升”指登山队沿陡坡向高处走，句意通顺。"}, {"text": "下坠", "is_correct": false, "explanation": "语义：“下坠”指往下掉，与“沿着陡坡一路”向上走的意思矛盾。"}, {"text": "漂浮", "is_correct": false, "explanation": "搭配：“漂浮”指浮在液体或空气中，不能用来描述登山队的行进。"}, {"text": "闪烁", "is_correct": false, "explanation": "搭配：“闪烁”指光亮时明时暗，不能用来描述人沿陡坡行进。"}], "explanations": {"攀升": "正确：“一路攀升”指登山队沿陡坡向高处走，句意通顺。", "下坠": "语义：“下坠”指往下掉，与“沿着陡坡一路”向上走的意思矛盾。", "漂浮": "搭配：“漂浮”指浮在液体或空气中，不能用来描述登山队的行进。", "闪烁": "搭配：“闪烁”指光亮时明时暗，不能用来描述人沿陡坡行进。"}, "sentence_index": 6, "correct_answer": "攀升"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "杂质攀升在杯底。", "explanation": "这里应该用〈沉淀〉。攀升指向高处移动，杂质下沉到杯底要用沉淀。"}, {"text": "小船在湖面上缓缓攀升。", "explanation": "这里应该用〈游动〉。攀升指向高处移动，小船在水面行进要用游动。"}, {"text": "树枝从树上攀升到地面。", "explanation": "这里应该用〈掉落〉。攀升指往上升，树枝从树上到地面是向下移动，要用掉落。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23424, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "无人机快速攀升屋顶上方。", "corrected_sentence": "无人机快速攀升到屋顶上方。", "error_description": "错误形式“攀升屋顶上方”：“攀升”后要用“到”引出到达的位置，应说“攀升到屋顶上方”，漏掉“到”不符合汉语习惯。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23424, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "直升机缓缓攀升在山顶上空。", "corrected_sentence": "直升机缓缓攀升到山顶上空。", "error_description": "错误形式“攀升在山顶上空”：表示向高处到达某处时，“攀升”后要用“到”引出到达的位置，应说“攀升到山顶上空”，“在”不能这样用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
