INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23426, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23426, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来制成另一种物质的原料或中间物。", "primary_collocate": null, "pronunciation": "qián tǐ", "ipa": "tɕʰjɛn˧˥ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "这种塑料的前体是石油。", "target_word": "前体", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工人把前体倒进大桶，再慢慢加热。", "target_word": "前体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种前体闻起来有点刺鼻。", "target_word": "前体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前体比最后的产品便宜很多。", "target_word": "前体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厂里每天要运来两吨前体。", "target_word": "前体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这瓶是前体，不是成品，不能直接用。", "target_word": "前体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们用这种前体做了一种新的颜料。", "target_word": "前体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在实验室里检查着前体的颜色。", "target_word": "前体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前体放在冷的地方，不容易坏。", "target_word": "前体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，先要有前体，才能做出药。", "target_word": "前体", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "前体物", "label": "复合"}, {"form": "前體", "label": "繁体"}], "register": "书面", "sense_fingerprint": "制成某物之前先有的原料或物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a6dee57-3677-400c-a29a-64b4982be465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23426, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前体", "is_correct": true, "explanation": "正确：前体是制成塑料之前的原料，句中说它是石油，符合“原料”的意思。"}, {"text": "产品", "is_correct": false, "explanation": "语义：产品是最后做成的东西，石油不是塑料的产品。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是性质，不能说“是石油”。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，与书面的化学说明不合，且“玩意儿是石油”说不通。"}], "explanations": {"前体": "正确：前体是制成塑料之前的原料，句中说它是石油，符合“原料”的意思。", "产品": "语义：产品是最后做成的东西，石油不是塑料的产品。", "颜色": "语义：颜色是性质，不能说“是石油”。", "玩意儿": "语域：“玩意儿”是口语，与书面的化学说明不合，且“玩意儿是石油”说不通。"}, "sentence_index": 0, "correct_answer": "前体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服是前体，穿起来很舒服。", "explanation": "这里应该用〈成品〉。前体指制成产品之前的原料，已经做好、能穿的衣服要说成品。"}, {"text": "这家工厂买了一台前体。", "explanation": "这里量词应用〈批〉或〈种〉，不用〈台〉。“台”用于机器，前体是物质。"}, {"text": "我的前体都很关心我。", "explanation": "这里应该用〈长辈〉。前体指先于某物出现的物质或阶段，不指人；指年长的亲属要用长辈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23426, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前体", "is_correct": true, "explanation": "正确：前体是用来制颜料的原料，“用这种前体做颜料”的说法成立。"}, {"text": "食物", "is_correct": false, "explanation": "语义：食物不是用来制成颜料的原料。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不能拿来制成颜料。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“用……做……”的对象是材料，“房子”不能作为制颜料的原料。"}], "explanations": {"前体": "正确：前体是用来制颜料的原料，“用这种前体做颜料”的说法成立。", "食物": "语义：食物不是用来制成颜料的原料。", "歌曲": "语义：歌曲不能拿来制成颜料。", "房子": "搭配：“用……做……”的对象是材料，“房子”不能作为制颜料的原料。"}, "sentence_index": 6, "correct_answer": "前体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的前体教了我很多东西。", "explanation": "这里应该用〈前辈〉。前体指先于产品的事物或阶段，不指人；指资历在前、指导过我的人要用前辈。"}, {"text": "他是个很有前体的人。", "explanation": "这里应该用〈前途〉。前体指先于某物出现的物质或阶段，不指人的发展前景；“有前途”要用前途。"}, {"text": "我们做了充分的前体。", "explanation": "这里应该用〈准备〉。前体指制成某物的原料，“做了充分的……”指事先筹划，要用准备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23426, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂每天要运来一个前体。", "corrected_sentence": "工厂每天要运来一批前体。", "error_description": "量词错误：“前体”是物质，应用“批”或“种”计量，“个”不适合。正确：一批前体；错误：一个前体。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23426, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们已经喝完了这批前体。", "corrected_sentence": "我们已经用完了这批前体。", "error_description": "动词搭配错误：“前体”是化工原料，不能“喝”。应说“用完了这批前体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06fe8372-8b41-4efd-8d62-f1d798eb5a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
