INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23430, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让一样东西看起来特别清楚，容易被看到。", "primary_collocate": null, "pronunciation": "tū xiǎn", "ipa": "tʰu˥ ɕjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "白色的墙让红门更加凸显。", "target_word": "凸显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑色的背景凸显了黄色的字。", "target_word": "凸显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "深色的衣服凸显了她白白的皮肤。", "target_word": "凸显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯光凸显了桌上的那盆花。", "target_word": "凸显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绿叶凸显了红花的颜色。", "target_word": "凸显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蓝天让白云凸显出来。", "target_word": "凸显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条黑裙子凸显了她的好身材。", "target_word": "凸显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪地里，红色的帽子特别凸显。", "target_word": "凸显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在字下面画线，让重点凸显出来。", "target_word": "凸显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑暗的房间里，白色的灯特别凸显。", "target_word": "凸显", "complexity_tier": "T3", "furigana": "tú xiǎn", "sentence_source": "generated"}], "morphological_forms": [{"form": "凸顯", "label": "繁体"}, {"form": "凸显了", "label": "体标"}], "register": "书面语", "sense_fingerprint": "凸显|在视觉上使某物特别醒目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f14b0bd-4442-4a82-ad1b-855548461c16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23430, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "掩盖", "is_correct": false, "explanation": "语义：「掩盖」指遮住使看不见，与「让红门更加」所描述的醒目效果相反。"}, {"text": "凸显", "is_correct": true, "explanation": "「凸显」指使某物特别醒目，与「白色的墙让红门更加……」的语境相符。"}, {"text": "减弱", "is_correct": false, "explanation": "搭配：「减弱」多用于力量、作用，不用来形容门的醒目程度。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：「忽视」指不加注意，墙不能忽视门，与白墙使红门更显眼的语境矛盾。"}], "explanations": {"掩盖": "语义：「掩盖」指遮住使看不见，与「让红门更加」所描述的醒目效果相反。", "凸显": "「凸显」指使某物特别醒目，与「白色的墙让红门更加……」的语境相符。", "减弱": "搭配：「减弱」多用于力量、作用，不用来形容门的醒目程度。", "忽视": "语义：「忽视」指不加注意，墙不能忽视门，与白墙使红门更显眼的语境矛盾。"}, "sentence_index": 0, "correct_answer": "凸显"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一口气凸显了三碗饭。", "explanation": "这里应该用〈吃〉。「凸显」是使事物醒目，与吃饭无关；一口气吃三碗饭要用〈吃〉。"}, {"text": "他每天凸显两个小时的钢琴。", "explanation": "这里应该用〈练〉。「凸显」是使事物醒目，不表示练习；每天练两个小时的钢琴要用〈练〉。"}, {"text": "他一天凸显了三十公里。", "explanation": "这里应该用〈走〉。「凸显」是使事物醒目，不表示行走距离；一天走三十公里要用〈走〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23430, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "锻炼", "is_correct": false, "explanation": "语义：「锻炼」指通过运动增强体质，裙子不能锻炼身体。"}, {"text": "辜负", "is_correct": false, "explanation": "搭配：「辜负」用于期望、心意，不搭配「好身材」。"}, {"text": "冒犯", "is_correct": false, "explanation": "语义：「冒犯」指得罪他人，与「好身材」所带的赞美语境不合。"}, {"text": "凸显", "is_correct": true, "explanation": "「凸显」指使某物特别醒目，裙子使她的好身材更显眼，符合语境。"}], "explanations": {"锻炼": "语义：「锻炼」指通过运动增强体质，裙子不能锻炼身体。", "辜负": "搭配：「辜负」用于期望、心意，不搭配「好身材」。", "冒犯": "语义：「冒犯」指得罪他人，与「好身材」所带的赞美语境不合。", "凸显": "「凸显」指使某物特别醒目，裙子使她的好身材更显眼，符合语境。"}, "sentence_index": 6, "correct_answer": "凸显"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个广告很凸显人。", "explanation": "这里应该用〈吸引〉。「凸显」指使可见的事物醒目，并不表示使人感兴趣，说广告吸引人要用〈吸引〉。"}, {"text": "我昨晚凸显了一整本小说。", "explanation": "这里应该用〈读〉。「凸显」是使事物醒目，不表示阅读；读完一整本小说要用〈读〉。"}, {"text": "他每个月都凸显一笔钱进银行。", "explanation": "这里应该用〈存〉。「凸显」是使事物醒目，不表示存放；把钱存进银行要用〈存〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23430, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "灯光让桌上的花凸显出去。", "corrected_sentence": "灯光让桌上的花凸显出来。", "error_description": "趋向补语错误：应说「凸显出来」，表示事物显露到醒目的状态；「出去」表示向外离开，与「凸显」的意思不合。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23430, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪地里，黑色的树干特别的凸显。", "corrected_sentence": "雪地里，黑色的树干特别凸显。", "error_description": "状语错误：「特别」修饰动词时直接放在动词前，不加「的」（「的」用于名词或形容词作定语）；应说「特别凸显」，不能说「特别的凸显」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
