INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23432, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指能看见的范围。", "primary_collocate": null, "pronunciation": "shì yù", "ipa": "ʂɻ̩˥˩ y˥˩", "syllable_count": 2, "sentences": [{"text": "一辆车慢慢驶进了我的视阈。", "target_word": "视阈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雾让司机的视阈变得很小。", "target_word": "视阈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只小鸟很快飞出了我们的视阈。", "target_word": "视阈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在山顶，我的视阈一下子变宽了。", "target_word": "视阈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山顶上的视阈很开阔，远处的城市一目了然。", "target_word": "视阈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走到门口，那个人已经不在视阈之内。", "target_word": "视阈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把手机放在孩子的视阈之外。", "target_word": "视阈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外的树挡住了我的视阈。", "target_word": "视阈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车的后视镜能扩大司机的视阈。", "target_word": "视阈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里灯光太暗，视阈只有几米。", "target_word": "视阈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "視閾", "label": "繁体"}], "register": "书面", "sense_fingerprint": "视阈：眼睛实际能看到的空间范围（视野）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f4ca28-5514-4bef-9e2b-fe5bad49018c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23432, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "视阈", "is_correct": true, "explanation": "视阈：shì yù，指眼睛能看到的范围。"}, {"text": "食欲", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是食欲，胃口。"}, {"text": "事务", "is_correct": false, "explanation": "yù（ü）与 wù（u）韵母不同，意思是事务。"}, {"text": "事宜", "is_correct": false, "explanation": "yù 与 yí 韵母不同，意思是事宜，指各种具体安排。"}], "explanations": {"视阈": "视阈：shì yù，指眼睛能看到的范围。", "食欲": "shí（第二声）与 shì（第四声）声调不同，意思是食欲，胃口。", "事务": "yù（ü）与 wù（u）韵母不同，意思是事务。", "事宜": "yù 与 yí 韵母不同，意思是事宜，指各种具体安排。"}, "sentence_index": null, "correct_answer": "视阈"}, "level_3": {"options": [{"text": "视阈", "is_correct": true, "explanation": "视阈：眼睛能看到的空间范围。此处指车进入了眼睛能看到的范围。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是随身的通讯工具，车不能驶进去，句子不通。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“驶进”搭配场所或空间，不说“驶进心情”。"}, {"text": "体型", "is_correct": false, "explanation": "体貌：“体型”指身体的形态，车不能驶进它，也与视线范围无关。"}], "explanations": {"视阈": "视阈：眼睛能看到的空间范围。此处指车进入了眼睛能看到的范围。", "手机": "语义：“手机”是随身的通讯工具，车不能驶进去，句子不通。", "心情": "搭配：“驶进”搭配场所或空间，不说“驶进心情”。", "体型": "体貌：“体型”指身体的形态，车不能驶进它，也与视线范围无关。"}, "sentence_index": 0, "correct_answer": "视阈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个车站的视阈很吵，人听了很烦。", "explanation": "这里应该用〈声音〉。声音指声波传到耳中的感受，视阈指能看见的范围，不能用“吵”来形容。"}, {"text": "这个包的视阈很轻，背起来很舒服。", "explanation": "这里应该用〈重量〉。重量指物体的轻重，视阈指能看见的范围，不能用“轻”来形容。"}, {"text": "这张照片的视阈很低。", "explanation": "这里应该用〈视角〉。拍摄的高低角度要用视角，视阈指能看到的范围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23432, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "视阈", "is_correct": true, "explanation": "视阈：眼睛能看到的空间范围。此处指手机应放在孩子看不到的地方。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指人生存的年数，不是可以放置物品的范围，句子不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“之外”后接空间或范围，“体重之外”搭配不当。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，不能作为放置手机的位置，句子意思不通。"}], "explanations": {"视阈": "视阈：眼睛能看到的空间范围。此处指手机应放在孩子看不到的地方。", "年龄": "语义：“年龄”指人生存的年数，不是可以放置物品的范围，句子不通。", "体重": "搭配：“之外”后接空间或范围，“体重之外”搭配不当。", "颜色": "语义：“颜色”指色彩，不能作为放置手机的位置，句子意思不通。"}, "sentence_index": 6, "correct_answer": "视阈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位作家的视阈很深，读者都很佩服。", "explanation": "这里应该用〈见解〉。见解指对事情的看法，视阈指能看到的空间范围，不能用“深”来形容看法。"}, {"text": "这道菜的视阈很辣，吃了一口就出汗。", "explanation": "这里应该用〈味道〉。味道指食物入口后的滋味，视阈指能看见的范围，不能用“辣”来形容。"}, {"text": "他的视阈很毒，一眼就能看出别人的短处。", "explanation": "这里应该用〈眼光〉。“眼光毒”指判断敏锐，视阈指能看到的空间范围，不能说“毒”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23432, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大雾我的视阈挡住了。", "corrected_sentence": "大雾把我的视阈挡住了。", "error_description": "“把”字句中处置对象前应有“把”，应说“大雾把我的视阈挡住了”。缺少“把”，“大雾我的视阈挡住了”两个名词连用，不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23432, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座山让我视阈延伸得很远。", "corrected_sentence": "这座山让我的视阈延伸得很远。", "error_description": "“我”修饰名词“视阈”时须加“的”，应说“我的视阈”，漏掉“的”不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
