INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23434, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "能用来换别的东西的能力。", "primary_collocate": null, "pronunciation": "tì dài xìng", "ipa": "tʰi˥˩ taɪ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "糖和蜂蜜有一定的替代性。", "target_word": "替代性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面包和米饭的替代性很高，都可以当主食。", "target_word": "替代性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把椅子的替代性很强，也可以当桌子用。", "target_word": "替代性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种布的替代性很好，能代替皮革做包。", "target_word": "替代性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果的替代性高，没有苹果就买梨。", "target_word": "替代性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个旧工具的替代性很小，扔了很可惜。", "target_word": "替代性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "筷子对勺子有一点替代性。", "target_word": "替代性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "木头的替代性比较强，家里常用它做东西。", "target_word": "替代性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纸杯的替代性很强，没有杯子时可以用它喝水。", "target_word": "替代性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词的替代性不大，换了意思就变。", "target_word": "替代性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不可替代性", "label": "复合词"}], "register": "中性", "sense_fingerprint": "替代性：东西能换成别的东西来用的能力，日常说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f4ca28-5514-4bef-9e2b-fe5bad49018c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23434, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "替代性", "is_correct": true, "explanation": "替代性：一种能代替另一种使用的特性。此处指糖和蜂蜜之间能互相代替的程度。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指生存的年数，糖和蜂蜜不能说有年龄，句子意思不通。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：“外貌”指人或动物的容貌，不能用来形容糖和蜂蜜。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”搭配人或动物，不说食物有脾气，“有一定的脾气”不通。"}], "explanations": {"替代性": "替代性：一种能代替另一种使用的特性。此处指糖和蜂蜜之间能互相代替的程度。", "年龄": "语义：“年龄”指生存的年数，糖和蜂蜜不能说有年龄，句子意思不通。", "外貌": "体貌：“外貌”指人或动物的容貌，不能用来形容糖和蜂蜜。", "脾气": "搭配：“脾气”搭配人或动物，不说食物有脾气，“有一定的脾气”不通。"}, "sentence_index": 0, "correct_answer": "替代性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块蛋糕的替代性很浓，孩子特别喜欢。", "explanation": "这里应该用〈甜味〉。甜味指食物入口后的甜的感觉，替代性指能否代替，不能用“浓”来形容。"}, {"text": "这床被子的替代性很薄，夏天盖正好。", "explanation": "这里应该用〈厚度〉。厚度指物体上下或前后的距离，替代性不能用“薄”来形容。"}, {"text": "这间屋子的替代性很难闻，要开窗通风。", "explanation": "这里应该用〈气味〉。气味指气体散发的味道，替代性不能用“难闻”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23434, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "替代性", "is_correct": true, "explanation": "替代性：一种能代替另一种使用的特性。此处指筷子与勺子在某些用途上可以互换。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指食物的滋味，不能用来说筷子和勺子之间的关系，句子不通。"}, {"text": "音量", "is_correct": false, "explanation": "搭配：“音量”指声音的大小，“有一点音量”与此处的关系说法不搭配。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人或动物的重量，筷子和勺子不能用它来比较。"}], "explanations": {"替代性": "替代性：一种能代替另一种使用的特性。此处指筷子与勺子在某些用途上可以互换。", "味道": "语义：“味道”指食物的滋味，不能用来说筷子和勺子之间的关系，句子不通。", "音量": "搭配：“音量”指声音的大小，“有一点音量”与此处的关系说法不搭配。", "体重": "语义：“体重”指人或动物的重量，筷子和勺子不能用它来比较。"}, "sentence_index": 6, "correct_answer": "替代性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个词的替代性很难念，很多人都读错。", "explanation": "这里应该用〈发音〉。发音指读音，替代性指能否代替，不能用“难念”来形容。"}, {"text": "这碗汤的替代性很鲜，喝一口就知道。", "explanation": "这里应该用〈味道〉。味道指食物入口后的滋味，替代性不能用“鲜”来形容。"}, {"text": "这辆车的替代性很快，十分钟就到了。", "explanation": "这里应该用〈速度〉。速度指移动的快慢，替代性不能用“快”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23434, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种油的替代性强很，炒菜和炸东西都能用。", "corrected_sentence": "这种油的替代性很强，炒菜和炸东西都能用。", "error_description": "程度副词“很”应放在形容词“强”之前，应说“很强”，不能说“强很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23434, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "买东西前，人们常会考虑替代性很。", "corrected_sentence": "买东西前，人们常会考虑替代性。", "error_description": "错误形式“替代性很”：“很”是程度副词，不能直接放在名词“替代性”后面，句子说不完整，应删去“很”，说“考虑替代性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
