INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23436, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西研制或做出来。", "primary_collocate": null, "pronunciation": "kāi fā", "ipa": "kʰai˥ fa˥", "syllable_count": 2, "sentences": [{"text": "小明想开发一个新的小游戏。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈开发出了一道新菜。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们开发了一种新玩法。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店开发了三种新口味的茶。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他自己开发了一个学习网站。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班开发了一个有趣的小程序。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把自己开发的小游戏给朋友玩。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起开发出了一个小机器人。", "target_word": "开发", "complexity_tier": "T3", "furigana": "dà jiā yì qǐ kāi fā chū le yí gè xiǎo jī qì rén", "sentence_source": "generated"}, {"text": "爸爸正在开发一个记账的软件。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玩具是工厂新开发的。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开发了", "label": "体标"}, {"form": "开发过", "label": "体标"}, {"form": "开发着", "label": "体标"}, {"form": "开发者", "label": "复合"}, {"form": "開發", "label": "繁体"}], "register": "中性", "sense_fingerprint": "开发：把东西做出来（简单义，新玩法、新口味、小程序）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f4ca28-5514-4bef-9e2b-fe5bad49018c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23436, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "开发", "is_correct": true, "explanation": "正确答案：开发（kāi fā），指把东西做出来。"}, {"text": "开放", "is_correct": false, "explanation": "fàng 与 fā 韵母不同（fàng 带 -ng），声调也不同，意思是开放。"}, {"text": "开方", "is_correct": false, "explanation": "fāng 与 fā 只多了韵尾 -ng，声调相同，意思是开方（数学运算）。"}, {"text": "开花", "is_correct": false, "explanation": "huā 与 fā 声母不同（h 与 f），声调相同，意思是开花。"}, {"text": "开饭", "is_correct": false, "explanation": "fàn 与 fā 韵尾不同（-n）且声调不同，意思是开饭、开始吃饭。"}], "explanations": {"开发": "正确答案：开发（kāi fā），指把东西做出来。", "开放": "fàng 与 fā 韵母不同（fàng 带 -ng），声调也不同，意思是开放。", "开方": "fāng 与 fā 只多了韵尾 -ng，声调相同，意思是开方（数学运算）。", "开花": "huā 与 fā 声母不同（h 与 f），声调相同，意思是开花。", "开饭": "fàn 与 fā 韵尾不同（-n）且声调不同，意思是开饭、开始吃饭。"}, "sentence_index": null, "correct_answer": "开发"}, "level_3": {"options": [{"text": "开发", "is_correct": true, "explanation": "正确：“开发”指做出新游戏，与“小游戏”搭配，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能说吃一个游戏。"}, {"text": "种", "is_correct": false, "explanation": "搭配：“种”用于植物，不能说种游戏。"}, {"text": "咳嗽", "is_correct": false, "explanation": "配价：“咳嗽”是不及物动词，不能带“游戏”作宾语。"}], "explanations": {"开发": "正确：“开发”指做出新游戏，与“小游戏”搭配，符合句意。", "吃": "语义：“吃”指进食，不能说吃一个游戏。", "种": "搭配：“种”用于植物，不能说种游戏。", "咳嗽": "配价：“咳嗽”是不及物动词，不能带“游戏”作宾语。"}, "sentence_index": 0, "correct_answer": "开发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爷爷开发了一个有趣的故事。", "explanation": "这里应该用〈讲〉。开发指做出或研制新东西，不说开发故事，讲故事要用讲。"}, {"text": "妹妹开发了一幅漂亮的画。", "explanation": "这里应该用〈画〉。开发不用于绘画，画画要用画。"}, {"text": "她开发了一首好听的歌。", "explanation": "这里应该用〈唱〉。开发不用于唱歌，唱歌要用唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23436, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开发", "is_correct": true, "explanation": "正确：“开发的小游戏”指自己做出的小游戏，与句意相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，不能用来修饰做出的游戏。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：“饲养”用于动物，不能说饲养小游戏。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”指流泪，与做游戏毫无关系。"}], "explanations": {"开发": "正确：“开发的小游戏”指自己做出的小游戏，与句意相符。", "唱": "语义：“唱”指发出歌声，不能用来修饰做出的游戏。", "饲养": "搭配：“饲养”用于动物，不能说饲养小游戏。", "哭": "语义：“哭”指流泪，与做游戏毫无关系。"}, "sentence_index": 6, "correct_answer": "开发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他开发了一次愉快的旅行。", "explanation": "这里应该用〈进行〉。开发指做出或研制新东西，旅行要用进行。"}, {"text": "姐姐开发了一封温暖的信。", "explanation": "这里应该用〈写〉。开发指做出或研制新东西，写信要用写。"}, {"text": "我们开发了一场精彩的比赛。", "explanation": "这里应该用〈举办〉。开发指做出新东西，比赛要用举办。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23436, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹想开发过一个会唱歌的小机器人。", "corrected_sentence": "妹妹想开发一个会唱歌的小机器人。", "error_description": "错误：“想”表示打算，动作尚未发生，不能用表示经历的“过”。应删去“开发”后的“过”，说“妹妹想开发一个会唱歌的小机器人。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23436, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把这个小游戏开发出了来。", "corrected_sentence": "我们把这个小游戏开发出来了。", "error_description": "错误：结果补语“出来”是固定组合，中间不能插入“了”，应说“开发出来了”，不能说“出了来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23438, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变冷", "is_correct": true, "explanation": "「变冷」指天气转凉，与「变暖」构成反义关系。"}, {"text": "出发", "is_correct": false, "explanation": "「出发」与「变暖」没有反义关系，不是答案。"}, {"text": "唱歌", "is_correct": false, "explanation": "「唱歌」与「变暖」没有反义关系，不是答案。"}, {"text": "写字", "is_correct": false, "explanation": "「写字」与「变暖」没有反义关系，不是答案。"}], "correct_answer": "变冷", "explanations": {"变冷": "「变冷」指天气转凉，与「变暖」构成反义关系。", "出发": "「出发」与「变暖」没有反义关系，不是答案。", "唱歌": "「唱歌」与「变暖」没有反义关系，不是答案。", "写字": "「写字」与「变暖」没有反义关系，不是答案。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23438, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变冷", "is_correct": true, "explanation": "「变冷」指天气转凉，与「变暖」构成反义关系。"}, {"text": "打扫", "is_correct": false, "explanation": "「打扫」与「变暖」没有反义关系，不是答案。"}, {"text": "练习", "is_correct": false, "explanation": "「练习」与「变暖」没有反义关系，不是答案。"}, {"text": "游泳", "is_correct": false, "explanation": "「游泳」与「变暖」没有反义关系，不是答案。"}], "correct_answer": "变冷", "explanations": {"变冷": "「变冷」指天气转凉，与「变暖」构成反义关系。", "打扫": "「打扫」与「变暖」没有反义关系，不是答案。", "练习": "「练习」与「变暖」没有反义关系，不是答案。", "游泳": "「游泳」与「变暖」没有反义关系，不是答案。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23438, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "天气由冷变得暖和了。", "primary_collocate": null, "pronunciation": "biàn nuǎn", "ipa": "pjɛn˥˩ nwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "三月以后，天气慢慢变暖了。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天变暖了，我们可以去公园玩。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，天气开始变暖。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变暖，我就不穿厚衣服了。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了今天，天气会变暖一点儿。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气一变暖，花就开了。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下个星期天气会变暖。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变暖了，河里的冰也化了。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等天变暖，我们去爬山。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几天天气变暖，街上的人多了。", "target_word": "变暖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "變暖", "label": "繁体"}, {"form": "变暖了", "label": "体标"}], "register": "口语", "sense_fingerprint": "变暖|天气由冷变得暖和", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f14b0bd-4442-4a82-ad1b-855548461c16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23438, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "变暖", "is_correct": true, "explanation": "「变暖」指天气由冷转暖，与「三月以后」的春天语境相符。"}, {"text": "融化", "is_correct": false, "explanation": "搭配：「融化」多说冰雪，不说天气融化。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：「结冰」指水变成冰，与三月转暖的语境不合。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：「发芽」是植物的生长动作，不能用来描述天气。"}], "explanations": {"变暖": "「变暖」指天气由冷转暖，与「三月以后」的春天语境相符。", "融化": "搭配：「融化」多说冰雪，不说天气融化。", "结冰": "语义：「结冰」指水变成冰，与三月转暖的语境不合。", "发芽": "语义：「发芽」是植物的生长动作，不能用来描述天气。"}, "sentence_index": 0, "correct_answer": "变暖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "书包里的书变暖了。", "explanation": "这里应该用〈减少〉。「变暖」只用于天气或温度，书的数量变化要用〈减少〉。"}, {"text": "今天的物价变暖了。", "explanation": "这里应该用〈降低〉。「变暖」说气温上升，物价的下降要用〈降低〉。"}, {"text": "这个城市的人口变暖得很快。", "explanation": "这里应该用〈增长〉。「变暖」只用于温度，人口的变化要用〈增长〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23438, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生锈", "is_correct": false, "explanation": "搭配：「生锈」用于金属，不说天气生锈。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：「点燃」指使东西着火，天气不能被点燃。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：「结婚」是人的行为，天气不会结婚。"}, {"text": "变暖", "is_correct": true, "explanation": "「变暖」指天气转暖，符合「下个星期」的时间语境。"}], "explanations": {"生锈": "搭配：「生锈」用于金属，不说天气生锈。", "点燃": "语义：「点燃」指使东西着火，天气不能被点燃。", "结婚": "语义：「结婚」是人的行为，天气不会结婚。", "变暖": "「变暖」指天气转暖，符合「下个星期」的时间语境。"}, "sentence_index": 6, "correct_answer": "变暖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的收入变暖了。", "explanation": "这里应该用〈增加〉。「变暖」只用于天气或温度，收入的增长要用〈增加〉。"}, {"text": "这家公司的规模变暖了。", "explanation": "这里应该用〈扩大〉。「变暖」只用于温度，说公司规模要用〈扩大〉。"}, {"text": "这次考试的难度变暖了。", "explanation": "这里应该用〈提高〉。「变暖」只说温度上升，难度的变化要用〈提高〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23438, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春天到了，天气很变暖了。", "corrected_sentence": "春天到了，天气变暖了。", "error_description": "副词错误：「很」不能直接修饰动词「变暖」；应删去「很」，说「天气变暖了」或「天气变得很暖和」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23438, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个星期天气被变暖了，大家都出来了。", "corrected_sentence": "这个星期天气变暖了，大家都出来了。", "error_description": "被字句错误：「变暖」是不及物动词，不能用「被」字句；应说「天气变暖了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
