INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23442, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "能装很多很多东西。", "primary_collocate": null, "pronunciation": "gāo róng liàng", "ipa": "kɑu̯˥ ɻʊŋ˧˥ ljɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "我想买一个高容量的充电宝，出门不怕没电。", "target_word": "高容量", "complexity_tier": "T3", "furigana": "wǒ xiǎng mǎi yí ge gāo róng liàng de chōng diàn bǎo, chū mén bú pà méi diàn", "sentence_source": "generated"}, {"text": "这块高容量电池能让手机用上两天。", "target_word": "高容量", "complexity_tier": "T3", "furigana": "zhè kuài gāo róng liàng diàn chí néng ràng shǒu jī yòng shàng liǎng tiān", "sentence_source": "generated"}, {"text": "她的硬盘是高容量的，存了好几万张照片。", "target_word": "高容量", "complexity_tier": "T3", "furigana": "tā de yìng pán shì gāo róng liàng de, cún le hǎo jǐ wàn zhāng zhào piàn", "sentence_source": "generated"}, {"text": "我家的洗衣机是高容量的，一次能洗两床被子。", "target_word": "高容量", "complexity_tier": "T3", "furigana": "wǒ jiā de xǐ yī jī shì gāo róng liàng de, yí cì néng xǐ liǎng chuáng bèi zi", "sentence_source": "generated"}, {"text": "这台打印机的纸盒是高容量的，一次能装很多纸。", "target_word": "高容量", "complexity_tier": "T3", "furigana": "zhè tái dǎ yìn jī de zhǐ hé shì gāo róng liàng de, yí cì néng zhuāng hěn duō zhǐ", "sentence_source": "generated"}, {"text": "这台高容量冰箱放得下整只西瓜。", "target_word": "高容量", "complexity_tier": "T3", "furigana": "zhè tái gāo róng liàng bīng xiāng fàng de xià zhěng zhī xī guā", "sentence_source": "generated"}, {"text": "我的相机存储卡是高容量的，能拍很多视频。", "target_word": "高容量", "complexity_tier": "T3", "furigana": "wǒ de xiàng jī cún chǔ kǎ shì gāo róng liàng de, néng pāi hěn duō shì pín", "sentence_source": "generated"}, {"text": "这款烤箱是高容量的，一次能烤十二个面包。", "target_word": "高容量", "complexity_tier": "T3", "furigana": "zhè kuǎn kǎo xiāng shì gāo róng liàng de, yí cì néng kǎo shí èr ge miàn bāo", "sentence_source": "generated"}, {"text": "这款洗碗机是高容量的，一次能洗一大家子的碗。", "target_word": "高容量", "complexity_tier": "T3", "furigana": "zhè kuǎn xǐ wǎn jī shì gāo róng liàng de, yí cì néng xǐ yí dà jiā zi de wǎn", "sentence_source": "generated"}, {"text": "这个高容量的优盘可以存下整部电影。", "target_word": "高容量", "complexity_tier": "T3", "furigana": "zhè ge gāo róng liàng de yōu pán kě yǐ cún xià zhěng bù diàn yǐng", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "定语：日常的包、杯、箱等容器能装很多东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36440c-1b9c-48b5-9e18-6c80bfba6e21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23442, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高容量", "is_correct": true, "explanation": "正确：“高容量”说明充电宝能储存很多电量，与“出门不怕没电”相符。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”形容光线，不能用来说明充电宝的蓄电量。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能修饰充电宝。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：“高兴”形容人的心情，不能修饰充电宝。"}], "explanations": {"高容量": "正确：“高容量”说明充电宝能储存很多电量，与“出门不怕没电”相符。", "明亮": "语义：“明亮”形容光线，不能用来说明充电宝的蓄电量。", "清脆": "搭配：“清脆”形容声音，不能修饰充电宝。", "高兴": "搭配：“高兴”形容人的心情，不能修饰充电宝。"}, "sentence_index": 0, "correct_answer": "高容量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件毛衣是高容量的，我穿正好合适。", "explanation": "这里应该用〈大号〉。“高容量”指容器能装多少，不用来形容衣服的尺码。"}, {"text": "这个高容量的声音很大，吵得我睡不着。", "explanation": "这里把“高容量”当成了〈响亮〉的意思。“高容量”只说能装多少，不能形容声音的大小。"}, {"text": "我的同桌是一个高容量的学生，成绩很好。", "explanation": "这里把“高容量”当成了〈能力强〉的意思。“高容量”只指设施或容器能容纳多少，不能用来形容人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23442, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高容量", "is_correct": true, "explanation": "正确：“高容量”说明存储卡能容纳很多照片和视频，与语境相符。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：“柔软”形容质地，不能说明存储卡的容量。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”多形容水或眼神，不能修饰存储卡。"}, {"text": "年迈", "is_correct": false, "explanation": "搭配：“年迈”形容人的年龄，不能修饰存储卡。"}], "explanations": {"高容量": "正确：“高容量”说明存储卡能容纳很多照片和视频，与语境相符。", "柔软": "语义：“柔软”形容质地，不能说明存储卡的容量。", "清澈": "搭配：“清澈”多形容水或眼神，不能修饰存储卡。", "年迈": "搭配：“年迈”形容人的年龄，不能修饰存储卡。"}, "sentence_index": 6, "correct_answer": "高容量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他写的字高容量，别人一眼就能看懂。", "explanation": "这里应该用〈工整〉。“高容量”只说明能装多少，不能用来形容字的好坏，应说字写得很工整。"}, {"text": "这杯茶的颜色高容量，喝起来很香。", "explanation": "这里应该用〈深〉。“高容量”只说明能装多少，不能形容颜色的深浅，应说颜色很深。"}, {"text": "他高容量地存下了整部电影。", "explanation": "这里把“高容量”当成了〈大量〉的意思。“高容量”描述的是物体能装多少，不能修饰“存”这样的动作；句中应描写优盘本身的容量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23442, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个高容量地保温杯能装两升水。", "corrected_sentence": "这个高容量的保温杯能装两升水。", "error_description": "错误：修饰名词“保温杯”时用了“地”。正确：“高容量的保温杯”。“地”用于修饰动词，名词前要用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23442, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了一台高容量的的电饭煲。", "corrected_sentence": "我买了一台高容量的电饭煲。", "error_description": "错误：结构助词“的”重复使用，“高容量的的电饭煲”多了一个“的”。正确：“一台高容量的电饭煲”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23444, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23444, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23444, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "想出的一个好主意。", "primary_collocate": null, "pronunciation": "gòu xiǎng", "ipa": "kou̯˥˩ ɕjɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的构想很新鲜，大家都很感兴趣。", "target_word": "构想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个构想听起来不错，可是太贵了。", "target_word": "构想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她向经理说明了自己的构想。", "target_word": "构想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板很满意这个新产品的构想。", "target_word": "构想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有一个构想，想和你谈谈。", "target_word": "构想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个构想一直没有变成现实。", "target_word": "构想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自己的构想画成了一张图。", "target_word": "构想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家提出了很多好构想。", "target_word": "构想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位建筑师的构想很大胆。", "target_word": "构想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，每个人都说了自己的构想。", "target_word": "构想", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个构想", "label": "量词"}, {"form": "構想", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：想出来的主意、设想、方案", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36440c-1b9c-48b5-9e18-6c80bfba6e21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23444, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "构想", "is_correct": true, "explanation": "正确：“构想”指想出的主意，与“很新鲜”“大家都很感兴趣”相符。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“新鲜”多用于新颖的事物或食物，不能修饰“体重”这类数值。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”是人的性情，不是能让大家感兴趣的新事物。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”是客观事实，不能被说成“很新鲜”，也不会引起大家的兴趣。"}], "explanations": {"构想": "正确：“构想”指想出的主意，与“很新鲜”“大家都很感兴趣”相符。", "体重": "搭配：“新鲜”多用于新颖的事物或食物，不能修饰“体重”这类数值。", "脾气": "语义：“脾气”是人的性情，不是能让大家感兴趣的新事物。", "年龄": "语义：“年龄”是客观事实，不能被说成“很新鲜”，也不会引起大家的兴趣。"}, "sentence_index": 0, "correct_answer": "构想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他提出了一把构想，大家都听得很认真。", "explanation": "这里应该用量词〈个〉。“把”用于有柄、可握持的物品，构想是抽象的想法，不能用“把”计量。"}, {"text": "她讲了一只很有趣的构想。", "explanation": "这里应该用量词〈个〉。“只”用于动物或成对器官中的一个，不用来计量抽象的构想。"}, {"text": "他把构想放进了书包里。", "explanation": "这里应该用〈图纸〉。构想是抽象的想法，不能装进书包；可以放进书包的是图纸，应用〈图纸〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23444, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "构想", "is_correct": true, "explanation": "正确：“构想”是可以画成图的想法，与“把自己的……画成了一张图”的语境相符。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“把……画成一张图”要求对象是可视的事物，“脚步”是动作和声音，不能这样搭配。"}, {"text": "口音", "is_correct": false, "explanation": "语义：“口音”是说话时的语音特征，不是可以画成一张图的事物。"}, {"text": "叫声", "is_correct": false, "explanation": "语义：“叫声”是听觉上的声音，不能被画成一张图。"}], "explanations": {"构想": "正确：“构想”是可以画成图的想法，与“把自己的……画成了一张图”的语境相符。", "脚步": "搭配：“把……画成一张图”要求对象是可视的事物，“脚步”是动作和声音，不能这样搭配。", "口音": "语义：“口音”是说话时的语音特征，不是可以画成一张图的事物。", "叫声": "语义：“叫声”是听觉上的声音，不能被画成一张图。"}, "sentence_index": 6, "correct_answer": "构想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他犯了一个构想，大家都很惊讶。", "explanation": "这里应该用〈错误〉。“犯”搭配“错误”，构想是想出的好主意，不能被“犯”。"}, {"text": "她的构想很开朗，大家都喜欢和她聊天。", "explanation": "这里应该用〈性格〉。“开朗”形容人的性格，构想是想出的主意，不能用“开朗”来形容。"}, {"text": "他一口气喝光了构想。", "explanation": "这里应该用〈饮料〉。“喝”的对象是饮品，构想是想出的主意，不能被喝下去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23444, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她想出了一张好的构想。", "corrected_sentence": "她想出了一个好的构想。", "error_description": "错误：“构想”前的量词“张”不对。正确：“一个构想”。“张”用于纸张、桌子等扁平物，抽象的构想要用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23444, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他提出了一个很好构想，大家都很赞成。", "corrected_sentence": "他提出了一个很好的构想，大家都很赞成。", "error_description": "错误：“很好”修饰名词“构想”时漏掉了结构助词“的”。正确：“很好的构想”。形容词或形容词性短语修饰名词时要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
