INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23446, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人们等车的地方。", "primary_collocate": null, "pronunciation": "zhàn diǎn", "ipa": "ʈʂan˥˩ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "我在站点等了二十分钟，车才来。", "target_word": "站点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站点旁边有一家小超市。", "target_word": "站点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨很大，大家都躲在站点的棚子下。", "target_word": "站点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在家门口的站点上了车。", "target_word": "站点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站点上有很多人在排队等车。", "target_word": "站点", "complexity_tier": "T3", "furigana": "zhàn diǎn shàng yǒu hěn duō rén zài pái duì děng chē", "sentence_source": "generated"}, {"text": "老人在站点坐着休息。", "target_word": "站点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在学校门口的站点见面吧。", "target_word": "站点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个站点只有一条线路经过。", "target_word": "站点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，站点上只剩他一个人。", "target_word": "站点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我跑到站点，可是末班车已经走了。", "target_word": "站点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个站点", "label": "量词"}, {"form": "站點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：路边人们等车、候车的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36440c-1b9c-48b5-9e18-6c80bfba6e21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23446, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "站点", "is_correct": true, "explanation": "“站点”指路边供人等车、上下车的地方，此处正是等车的场所，是正确答案。"}, {"text": "教室", "is_correct": false, "explanation": "语义：“教室”是上课的地方，不是等公交车的场所，“车才来”无法成立。"}, {"text": "厕所", "is_correct": false, "explanation": "语义：“厕所”不是等车的地方，句子中等车的意思不通。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是装书本的袋子，不是等车的地方，“等了二十分钟”无法成立。"}], "explanations": {"站点": "“站点”指路边供人等车、上下车的地方，此处正是等车的场所，是正确答案。", "教室": "语义：“教室”是上课的地方，不是等公交车的场所，“车才来”无法成立。", "厕所": "语义：“厕所”不是等车的地方，句子中等车的意思不通。", "书包": "语义：“书包”是装书本的袋子，不是等车的地方，“等了二十分钟”无法成立。"}, "sentence_index": 0, "correct_answer": "站点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个站点有三层楼，楼里有很多商店。", "explanation": "这里应该用〈车站〉。站点是路边等车的地方，没有楼层和商店，有这类建筑的设施应说车站。"}, {"text": "司机发动了站点，车子慢慢开走了。", "explanation": "这里应该用〈汽车〉。站点是人们等车的地方，不能被发动；发动的应是汽车。"}, {"text": "我在一把站点旁边等车。", "explanation": "这里应该用〈个〉。“把”用于有柄的物品，站点要用“个”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23446, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "站点", "is_correct": true, "explanation": "“站点”是路边供人聚集、等车的地方，可以作为约定见面的地点，是正确答案。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”不是场所，不能作为见面的地点。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“课本”是书，不能当作见面的地方。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "搭配：“见面”的地点要能供人聚集，“垃圾桶”不适合用来约见。"}], "explanations": {"站点": "“站点”是路边供人聚集、等车的地方，可以作为约定见面的地点，是正确答案。", "作业": "语义：“作业”不是场所，不能作为见面的地点。", "课本": "语义：“课本”是书，不能当作见面的地方。", "垃圾桶": "搭配：“见面”的地点要能供人聚集，“垃圾桶”不适合用来约见。"}, "sentence_index": 6, "correct_answer": "站点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个站点很长，要坐一个小时才到终点。", "explanation": "这里应该用〈线路〉。站点是人们等车的地方，没有长短；说路程远近要用线路。"}, {"text": "这个站点的门票卖得很好，游客们排起了长队。", "explanation": "这里应该用〈景点〉。站点是人们等车的地方，不卖门票；卖门票、吸引游客的应是景点。"}, {"text": "等车的人在一台站点前排成了队。", "explanation": "这里应该用〈个〉。“台”用于机器、设备等，站点要用“个”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23446, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们约好在一把站点碰面，然后一起坐车。", "corrected_sentence": "我们约好在一个站点碰面，然后一起坐车。", "error_description": "量词错误：“站点”应用量词“个”，不用“把”（“把”用于有柄的物品）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23446, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈站点等了很久，才看见公交车。", "corrected_sentence": "妈妈在站点等了很久，才看见公交车。", "error_description": "介词错误：在某处等待时，地点前要加介词“在”，“站点等”应说“在站点等”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
