INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23448, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "把东西放在哪里，或者事情怎么安排。", "primary_collocate": null, "pronunciation": "bù jú", "ipa": "pu˥˩ tɕy˧˥", "syllable_count": 2, "sentences": [{"text": "我家客厅的布局很简单。", "target_word": "布局", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新房子的布局我很喜欢。", "target_word": "布局", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个房间的布局不太好，太挤了。", "target_word": "布局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把房间的布局改了。", "target_word": "布局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店的布局让人很容易找到东西。", "target_word": "布局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看一下这张图，就知道教室的布局。", "target_word": "布局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨房的布局要方便做饭。", "target_word": "布局", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家餐厅的布局很特别。", "target_word": "布局", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公园里花草的布局很漂亮。", "target_word": "布局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新办公室的布局经过重新设计，大家办事更方便。", "target_word": "布局", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "房间布局", "label": "复合"}, {"form": "整体布局", "label": "复合"}, {"form": "空间布局", "label": "复合"}], "register": "通用", "sense_fingerprint": "东西摆放的位置与安排方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36440c-1b9c-48b5-9e18-6c80bfba6e21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23448, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "布局", "is_correct": true, "explanation": "布局（bù jú）：指东西的摆放位置与安排方式，是本句所用的意思。"}, {"text": "赌局", "is_correct": false, "explanation": "dǔ（第三声）与 bù（第四声）声母不同，声调也不同，意思是赌博的局面。"}, {"text": "组局", "is_correct": false, "explanation": "zǔ 与 bù 声母不同，声调也不同，意思是组织一场聚会或游戏。"}, {"text": "不计", "is_correct": false, "explanation": "jì（第四声）与 jú 韵母不同，声调也不同，意思是不计较。"}, {"text": "不及", "is_correct": false, "explanation": "jí 与 jú 韵母不同，意思是来不及、赶不上。"}], "explanations": {"布局": "布局（bù jú）：指东西的摆放位置与安排方式，是本句所用的意思。", "赌局": "dǔ（第三声）与 bù（第四声）声母不同，声调也不同，意思是赌博的局面。", "组局": "zǔ 与 bù 声母不同，声调也不同，意思是组织一场聚会或游戏。", "不计": "jì（第四声）与 jú 韵母不同，声调也不同，意思是不计较。", "不及": "jí 与 jú 韵母不同，意思是来不及、赶不上。"}, "sentence_index": null, "correct_answer": "布局"}, "level_3": {"options": [{"text": "布局", "is_correct": true, "explanation": "布局：指客厅的摆放和安排，与「很简单」相符。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄指存在的时间长短，不能用来形容客厅的摆放。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体形，不能用来说房间。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：「很简单」不修饰价格，价格不说“简单”。"}], "explanations": {"布局": "布局：指客厅的摆放和安排，与「很简单」相符。", "年龄": "语义：年龄指存在的时间长短，不能用来形容客厅的摆放。", "身材": "体貌：身材指人的体形，不能用来说房间。", "价格": "搭配：「很简单」不修饰价格，价格不说“简单”。"}, "sentence_index": 0, "correct_answer": "布局"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的布局很厚，放在书架上很占地方。", "explanation": "这里应该用〈厚度〉。布局指安排格局，不能用来说书有多厚，应说厚度。"}, {"text": "这碗汤的布局很鲜美，大家都夸好喝。", "explanation": "这里应该用〈味道〉。布局指安排格局，不能形容汤的鲜美，应说汤的味道很好。"}, {"text": "这个箱子的布局很重，搬起来很费力。", "explanation": "这里应该用〈重量〉。布局指安排格局，不能用来说物体的轻重，应说箱子的重量很大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23448, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "布局", "is_correct": true, "explanation": "布局（bù jú）：指东西的摆放位置与安排方式，是本句所用的意思。"}, {"text": "入局", "is_correct": false, "explanation": "rù（第四声）与 bù 声母不同，意思是进入某种局面或竞争。"}, {"text": "不拘", "is_correct": false, "explanation": "jū（第一声）与 jú（第二声）声调不同，意思是不受限制。"}, {"text": "不吉", "is_correct": false, "explanation": "jí 与 jú 韵母不同，意思是不吉利。"}], "explanations": {"布局": "布局（bù jú）：指东西的摆放位置与安排方式，是本句所用的意思。", "入局": "rù（第四声）与 bù 声母不同，意思是进入某种局面或竞争。", "不拘": "jū（第一声）与 jú（第二声）声调不同，意思是不受限制。", "不吉": "jí 与 jú 韵母不同，意思是不吉利。"}, "sentence_index": null, "correct_answer": "布局"}, "level_3": {"options": [{"text": "布局", "is_correct": true, "explanation": "布局：指厨房的摆放安排，与「方便做饭」相符。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不是可以摆放的对象，「方便做饭」无法说明时间。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「方便做饭」不能修饰颜色，颜色不说“要方便做饭”。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气指人的性情，不能说厨房的脾气要方便做饭。"}], "explanations": {"布局": "布局：指厨房的摆放安排，与「方便做饭」相符。", "时间": "语义：时间不是可以摆放的对象，「方便做饭」无法说明时间。", "颜色": "搭配：「方便做饭」不能修饰颜色，颜色不说“要方便做饭”。", "脾气": "语义：脾气指人的性情，不能说厨房的脾气要方便做饭。"}, "sentence_index": 6, "correct_answer": "布局"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座桥的布局很坚固，几十年都没坏。", "explanation": "这里应该用〈结构〉。布局指安排，说桥梁坚固要用结构。"}, {"text": "这台电脑的布局很高，运行非常快。", "explanation": "这里应该用〈配置〉。布局指安排，说电脑的性能高低要用配置。"}, {"text": "这位老人的布局很矮，走路很慢。", "explanation": "这里用错了对象：布局指事物的安排，不能形容人的身高，应该说〈个子〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23448, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套公寓有一把很实用的布局。", "corrected_sentence": "这套公寓有一种很实用的布局。", "error_description": "“布局”的量词用错：“把”用于有柄的器具，布局应该用“种”，正确说法是「一种很实用的布局」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23448, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店得布局很合理，方便顾客。", "corrected_sentence": "这家店的布局很合理，方便顾客。", "error_description": "“的”误写成“得”：“布局”前的修饰语要用结构助词“的”，“得”只用于动词或形容词后的补语，正确说法是「这家店的布局很合理」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
