INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23450, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个东西连在一起，互相影响。", "primary_collocate": null, "pronunciation": "ǒu hé", "ipa": "oʊ˨˩˦ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "这两个系统的耦合太强了。", "target_word": "耦合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师想减少模块之间的耦合。", "target_word": "耦合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "耦合太高，改一处就会影响别处。", "target_word": "耦合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电路中的耦合会让信号互相影响。", "target_word": "耦合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个线圈之间有很强的耦合。", "target_word": "耦合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的程序要做到低耦合。", "target_word": "耦合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种耦合让两台机器一起工作。", "target_word": "耦合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们研究了两种材料的耦合。", "target_word": "耦合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "软件里的耦合越小越好。", "target_word": "耦合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "耦合的好处是联系紧密，坏处是难修改。", "target_word": "耦合", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "耦合器", "label": "复合"}, {"form": "耦合度", "label": "复合"}], "register": "书面", "sense_fingerprint": "耦合：两个系统或部分相互联系、互相影响", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89604cde-aa36-49a3-b834-19b3606a7411') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23450, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "耦合", "is_correct": true, "explanation": "正确。耦合指两个系统之间相互联系、互相影响的程度，“太强了”正好描述这种程度。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不能用“强”来形容，这里说的是系统之间的联系程度。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“太强了”多用于力量、影响等，不用来形容温度。"}, {"text": "国籍", "is_correct": false, "explanation": "语义：国籍与两个系统之间的联系程度无关，不能说“太强了”。"}], "explanations": {"耦合": "正确。耦合指两个系统之间相互联系、互相影响的程度，“太强了”正好描述这种程度。", "年龄": "语义：年龄不能用“强”来形容，这里说的是系统之间的联系程度。", "温度": "搭配：“太强了”多用于力量、影响等，不用来形容温度。", "国籍": "语义：国籍与两个系统之间的联系程度无关，不能说“太强了”。"}, "sentence_index": 0, "correct_answer": "耦合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和老同学的耦合一直很密切。", "explanation": "这里应该用〈联系〉。耦合指系统或部件之间的相互影响，不用来形容人与人之间的往来。"}, {"text": "他们两人的耦合很好。", "explanation": "这里应该用〈关系〉。耦合是技术术语，不用于形容人际关系。"}, {"text": "两国代表的耦合很顺利。", "explanation": "这里应该用〈交流〉。耦合不用于会谈、来往等人与人之间的活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23450, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "耦合", "is_correct": true, "explanation": "正确。耦合是把两台机器连在一起、使它们相互影响的关系，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“让两台机器一起工作”需要能起联动作用的东西，颜色不能与之搭配。"}, {"text": "感情", "is_correct": false, "explanation": "语义：感情不能让机器工作，句中需要的是把两台机器连在一起的东西。"}, {"text": "方言", "is_correct": false, "explanation": "语义：方言不能让两台机器一起工作，与句意不符。"}], "explanations": {"耦合": "正确。耦合是把两台机器连在一起、使它们相互影响的关系，符合句意。", "颜色": "搭配：“让两台机器一起工作”需要能起联动作用的东西，颜色不能与之搭配。", "感情": "语义：感情不能让机器工作，句中需要的是把两台机器连在一起的东西。", "方言": "语义：方言不能让两台机器一起工作，与句意不符。"}, "sentence_index": 6, "correct_answer": "耦合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次相遇纯属耦合。", "explanation": "这里表示偶然的巧合，应该用〈偶合〉。耦合指系统或部件之间的相互作用，不表示偶然。"}, {"text": "他把耦合放进了冰箱。", "explanation": "耦合是抽象的相互作用，不是实物，不能放进冰箱。"}, {"text": "这家商店的耦合卖得很好。", "explanation": "耦合是技术概念，不是商品，不能作为商品出售。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23450, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只耦合很强。", "corrected_sentence": "这种耦合很强。", "error_description": "错误：“耦合”是抽象名词，量词应用“种”。“只”多用于动物，不能用于“耦合”。正确说法是：这种耦合很强。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23450, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些耦合们都很强。", "corrected_sentence": "这些耦合都很强。", "error_description": "错误：“耦合”是抽象名词，不能加“们”表示复数。正确说法是：这些耦合都很强。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
