INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23452, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "住在某个地方。", "primary_collocate": null, "pronunciation": "jū zhù", "ipa": "tɕy˥˥ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "请写下您现在居住的地址。", "target_word": "居住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这个城市居住了很多年。", "target_word": "居住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐和朋友一起居住在大学附近。", "target_word": "居住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国人在中国居住需要办手续。", "target_word": "居住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师居住的小区离学校很近。", "target_word": "居住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小时候在一个有院子的房子里居住过。", "target_word": "居住", "complexity_tier": "T3", "furigana": "Wǒ xiǎo shí hou zài yí ge yǒu yuàn zi de fáng zi lǐ jū zhù guo.", "sentence_source": "generated"}, {"text": "奶奶不愿意离开，还想居住在老房子里。", "target_word": "居住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家晚年居住在南方的小镇。", "target_word": "居住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们居住的地方夏天很热。", "target_word": "居住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问您现在居住在几号楼？", "target_word": "居住", "complexity_tier": "T3", "furigana": "Qǐng wèn nín xiàn zài jū zhù zài jǐ hào lóu?", "sentence_source": "generated"}], "morphological_forms": [{"form": "居住了", "label": "体标"}, {"form": "居住着", "label": "体标"}, {"form": "居住过", "label": "体标"}], "register": "书面", "sense_fingerprint": "住在某地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569bc8cf-48c5-4326-bc0a-b2a00dd42f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23452, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "居住", "is_correct": true, "explanation": "正确：「您现在居住的地址」指您目前住在的地方，「居住」修饰「地址」，语义通顺。"}, {"text": "停靠", "is_correct": false, "explanation": "语义：「停靠」指车船靠岸或停下，「停靠的地址」说不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：「洗」的宾语是衣物等物品，不能修饰「地址」。"}, {"text": "生长", "is_correct": false, "explanation": "配价：「生长」是不及物动词，不能用来修饰「地址」，句子成分不成立。"}], "explanations": {"居住": "正确：「您现在居住的地址」指您目前住在的地方，「居住」修饰「地址」，语义通顺。", "停靠": "语义：「停靠」指车船靠岸或停下，「停靠的地址」说不通。", "洗": "搭配：「洗」的宾语是衣物等物品，不能修饰「地址」。", "生长": "配价：「生长」是不及物动词，不能用来修饰「地址」，句子成分不成立。"}, "sentence_index": 0, "correct_answer": "居住"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子居住在教室里。", "explanation": "这里应该用〈放〉。居住的主语须是人或动物，桌子不能居住，应说「放在教室里」。"}, {"text": "他在北京居住了很多朋友。", "explanation": "这里应该用〈交〉。居住不能带「朋友」作宾语，交朋友要说〈交〉。"}, {"text": "我们周末去长城居住了一天。", "explanation": "这里应该用〈参观〉。居住不能以景点作宾语，去长城游览要说〈参观〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23452, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "居住", "is_correct": true, "explanation": "正确：「还想居住在老房子里」表示愿意继续住在那里，与句意一致。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“玩耍”是消遣活动，与“还想……住在老房子里”的居住意愿不符。"}, {"text": "玩耍", "is_correct": false, "explanation": "搭配：「玩耍」不带「在……里」这类处所结构作常规搭配，表达「愿意住」时不成立。"}, {"text": "搬", "is_correct": false, "explanation": "配价：「搬」要求「搬到」或「搬进」这类趋向结构，「搬在老房子里」不成立。"}], "explanations": {"居住": "正确：「还想居住在老房子里」表示愿意继续住在那里，与句意一致。", "拆除": "语义：“玩耍”是消遣活动，与“还想……住在老房子里”的居住意愿不符。", "玩耍": "搭配：「玩耍」不带「在……里」这类处所结构作常规搭配，表达「愿意住」时不成立。", "搬": "配价：「搬」要求「搬到」或「搬进」这类趋向结构，「搬在老房子里」不成立。"}, "sentence_index": 6, "correct_answer": "居住"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们今天下午居住了长城，每天都去游览。", "explanation": "这里应该用〈游览〉。居住不能以景点作宾语，去长城玩要说〈游览〉。"}, {"text": "这只杯子居住在厨房里。", "explanation": "居住的主语须是人或动物，杯子不能居住，应说〈放〉。"}, {"text": "我们明天居住这座工厂，开始工作。", "explanation": "这里应该用〈进入〉。居住不能以工厂作宾语，去工厂工作要说〈进入〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23452, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在山村了居住了很多年。", "corrected_sentence": "他们在山村居住了很多年。", "error_description": "体标错误：「了」只能放在动词之后，前面多出的「了」应删去，正确说法是「居住了很多年」。正确句为「他们在山村居住了很多年。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23452, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在农村居住了过很多年。", "corrected_sentence": "他们在农村居住过很多年。", "error_description": "体标错误：「了」与「过」不能同时用于「居住」，多出的「了」应删去，正确说法是「居住过很多年」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '701f40c6-a02b-4582-a976-73244cf24ac8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
