INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23468, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "许多人或东西聚在一起。", "primary_collocate": null, "pronunciation": "jí jù", "ipa": "tɕi˧˥ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "下课后，学生集聚在操场上。", "target_word": "集聚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人集聚在门口看热闹。", "target_word": "集聚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟集聚在树上唱歌。", "target_word": "集聚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "节日里，亲戚们集聚在奶奶家。", "target_word": "集聚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人们集聚到广场上看烟花。", "target_word": "集聚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河边集聚了很多钓鱼的人。", "target_word": "集聚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店门口集聚着一群孩子。", "target_word": "集聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车站里集聚了等车的旅客。", "target_word": "集聚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天黑前，大家集聚到村口。", "target_word": "集聚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游客们集聚在山顶看日出。", "target_word": "集聚", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "集聚了", "label": "体标"}, {"form": "集聚着", "label": "体标"}, {"form": "集聚过", "label": "体标"}], "register": "通用", "sense_fingerprint": "许多人或东西聚到同一个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36440c-1b9c-48b5-9e18-6c80bfba6e21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23468, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "集聚", "is_correct": true, "explanation": "集聚（jí jù）：指许多人或东西聚在一起，是本句所用的意思。"}, {"text": "戏剧", "is_correct": false, "explanation": "xì（第四声）与 jí（第二声）声母和声调都不同，意思是戏剧。"}, {"text": "例句", "is_correct": false, "explanation": "lì（第四声）与 jí（第二声）声母和声调都不同，意思是例子中的句子。"}, {"text": "击剧", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是击剑运动。"}], "explanations": {"集聚": "集聚（jí jù）：指许多人或东西聚在一起，是本句所用的意思。", "戏剧": "xì（第四声）与 jí（第二声）声母和声调都不同，意思是戏剧。", "例句": "lì（第四声）与 jí（第二声）声母和声调都不同，意思是例子中的句子。", "击剧": "jī（第一声）与 jí（第二声）声调不同，意思是击剑运动。"}, "sentence_index": null, "correct_answer": "集聚"}, "level_3": {"options": [{"text": "集聚", "is_correct": true, "explanation": "集聚：指许多人聚在一起，与「下课后，学生…在操场上」相符。"}, {"text": "融化", "is_correct": false, "explanation": "语义：融化指固体变成液体，学生不能融化。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉与下课后在操场上聚集的情境不符，句意不通。"}, {"text": "摆放", "is_correct": false, "explanation": "搭配：摆放用于物品，不说学生被摆放。"}], "explanations": {"集聚": "集聚：指许多人聚在一起，与「下课后，学生…在操场上」相符。", "融化": "语义：融化指固体变成液体，学生不能融化。", "睡觉": "语义：睡觉与下课后在操场上聚集的情境不符，句意不通。", "摆放": "搭配：摆放用于物品，不说学生被摆放。"}, "sentence_index": 0, "correct_answer": "集聚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他集聚了一身肌肉，常去健身房。", "explanation": "这里应该用〈练出〉。集聚指人或东西聚在一起，不用来说通过锻炼长出肌肉。"}, {"text": "他向朋友集聚了一句道歉，心里轻松多了。", "explanation": "这里应该用〈说〉。集聚指人或东西聚到一处，不表示说出话语。"}, {"text": "我们要集聚时间，多学一些内容。", "explanation": "这里应该用〈挤出〉。集聚指人或东西到一处，不表示从忙碌中腾出时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23468, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "集聚", "is_correct": true, "explanation": "集聚（jí jù）：指许多人或东西聚在一起，是本句所用的意思。"}, {"text": "词句", "is_correct": false, "explanation": "cí（第二声）与 jí 声母不同（c 与 j），意思是词语和句子。"}, {"text": "疑惧", "is_correct": false, "explanation": "yí（第二声）与 jí 声母不同，意思是怀疑和恐惧。"}, {"text": "几句", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是几句话。"}, {"text": "机具", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是机器和工具。"}], "explanations": {"集聚": "集聚（jí jù）：指许多人或东西聚在一起，是本句所用的意思。", "词句": "cí（第二声）与 jí 声母不同（c 与 j），意思是词语和句子。", "疑惧": "yí（第二声）与 jí 声母不同，意思是怀疑和恐惧。", "几句": "jǐ（第三声）与 jí（第二声）声调不同，意思是几句话。", "机具": "jī（第一声）与 jí（第二声）声调不同，意思是机器和工具。"}, "sentence_index": null, "correct_answer": "集聚"}, "level_3": {"options": [{"text": "集聚", "is_correct": true, "explanation": "集聚：指许多人聚在一起，与「商店门口…着一群孩子」相符。"}, {"text": "矗立", "is_correct": false, "explanation": "语义：矗立指高耸地竖立，不用于形容一群孩子。"}, {"text": "罗列", "is_correct": false, "explanation": "搭配：罗列多用于物品或项目，不用于孩子。"}, {"text": "漂浮", "is_correct": false, "explanation": "语义：漂浮指浮在液体或空中，与商店门口站着的孩子不符。"}], "explanations": {"集聚": "集聚：指许多人聚在一起，与「商店门口…着一群孩子」相符。", "矗立": "语义：矗立指高耸地竖立，不用于形容一群孩子。", "罗列": "搭配：罗列多用于物品或项目，不用于孩子。", "漂浮": "语义：漂浮指浮在液体或空中，与商店门口站着的孩子不符。"}, "sentence_index": 6, "correct_answer": "集聚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校集聚了一场运动会。", "explanation": "这里应该用〈组织〉。集聚指人或东西聚到一处，不能表示有计划地举办活动。"}, {"text": "他集聚出了三个候选人。", "explanation": "这里应该用〈筛选〉。集聚指人或东西聚到一处，不表示挑选。"}, {"text": "他在股市里集聚了很多存款。", "explanation": "这里应该用〈积攒〉。集聚指人或东西聚到一处，不指逐步积蓄金钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23468, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学生们集聚操场上玩耍。", "corrected_sentence": "学生们集聚在操场上玩耍。", "error_description": "“集聚”后缺少介词“在”：应说「集聚在操场上」，不能直接接地点名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23468, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "旅客们集聚了在车站等车。", "corrected_sentence": "旅客们集聚在车站等车。", "error_description": "“了”放错了位置：“集聚”后直接接“在车站”，“了”不能插在“集聚”和地点之间，正确说法是「旅客们集聚在车站等车」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
