INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23472, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "两个地方之间很远。", "primary_collocate": null, "pronunciation": "cháng jù lí", "ipa": "ʈʂʰɑŋ˧˥ tɕy˥˩ li˧˥", "syllable_count": 3, "sentences": [{"text": "从北京到广州，要坐长距离的火车。", "target_word": "长距离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他参加了一场长距离的游泳比赛。", "target_word": "长距离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不想长距离开车去那里。", "target_word": "长距离", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "走长距离的路，要带够水。", "target_word": "长距离", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她经常长距离出差，很少在家。", "target_word": "长距离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种自行车适合长距离骑行。", "target_word": "长距离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "长距离的运动对心脏很好。", "target_word": "长距离", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟第一次坐长距离的汽车，一路都在睡觉。", "target_word": "长距离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天长距离上学，孩子很累。", "target_word": "长距离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这段长距离的山路，我们得早点出发。", "target_word": "长距离", "complexity_tier": "T3", "furigana": "zhè duàn cháng jù lí de shān lù, wǒ men děi zǎo diǎn chū fā.", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容两地之间路程很远，修饰行为或路途，如长距离骑行、长距离出差", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53331fef-4a2b-4af8-8ea1-ed5c509c92d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23472, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长距离", "is_correct": true, "explanation": "正确。“长距离的火车”指路程远的列车，与“从北京到广州”的路程相符。"}, {"text": "本地", "is_correct": false, "explanation": "语义：“本地”指同一城市或地区，与“从北京到广州”的跨省路程不符。"}, {"text": "室内", "is_correct": false, "explanation": "搭配：“室内”指房屋之内，不能修饰“火车”。"}, {"text": "暖和", "is_correct": false, "explanation": "搭配：“暖和”形容温度，不能用来描述火车的路程特征，与句意不符。"}], "explanations": {"长距离": "正确。“长距离的火车”指路程远的列车，与“从北京到广州”的路程相符。", "本地": "语义：“本地”指同一城市或地区，与“从北京到广州”的跨省路程不符。", "室内": "搭配：“室内”指房屋之内，不能修饰“火车”。", "暖和": "搭配：“暖和”形容温度，不能用来描述火车的路程特征，与句意不符。"}, "sentence_index": 0, "correct_answer": "长距离"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的长距离很厚。", "explanation": "这里应该用〈厚〉。“长距离”说的是两地之间的远近，描述书的厚薄要说厚。"}, {"text": "这根绳子的长距离很长。", "explanation": "这里应该用〈长〉。“长距离”说的是两地之间的远近，描述绳子本身的长短要说长。"}, {"text": "我们长距离地等了三个小时。", "explanation": "这里应该用〈长时间〉。“长时间”指时间持续得久，如长时间等待；“长距离”只说地点之间的远近，不能表示等待的时长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6006d7-9289-404a-bd33-5cf9c717080e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23472, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长距离", "is_correct": true, "explanation": "正确。“长距离的运动”指距离长的运动，如长跑、长距离游泳，符合“对心脏很好”的句意。"}, {"text": "停滞", "is_correct": false, "explanation": "语义：“停滞”指停止不前，与“运动”及“对心脏很好”的句意相矛盾。"}, {"text": "有毒", "is_correct": false, "explanation": "语义：“有毒”与“对心脏很好”相矛盾，不能用来修饰好的运动。"}, {"text": "冰冷", "is_correct": false, "explanation": "搭配：“冰冷”形容温度，不能修饰“运动”，且与运动对心脏有益的句意不符。"}], "explanations": {"长距离": "正确。“长距离的运动”指距离长的运动，如长跑、长距离游泳，符合“对心脏很好”的句意。", "停滞": "语义：“停滞”指停止不前，与“运动”及“对心脏很好”的句意相矛盾。", "有毒": "语义：“有毒”与“对心脏很好”相矛盾，不能用来修饰好的运动。", "冰冷": "搭配：“冰冷”形容温度，不能修饰“运动”，且与运动对心脏有益的句意不符。"}, "sentence_index": 6, "correct_answer": "长距离"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对未来有长距离的考虑。", "explanation": "这里应该用〈长远〉。“长远考虑”指着眼于长期发展；“长距离”只说空间上的远近，不能用来修饰“考虑”。"}, {"text": "他的工资长距离很高。", "explanation": "这里应该用〈高〉。“长距离”说的是两地之间的远近，不能描述工资的高低。"}, {"text": "这条河的一只长距离很难测量。", "explanation": "这里应该用〈段〉。路程的量词是“段”，“只”一般用于动物等，不能计量“长距离”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6006d7-9289-404a-bd33-5cf9c717080e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23472, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们明天要进行长距离得骑行。", "corrected_sentence": "我们明天要进行长距离的骑行。", "error_description": "“长距离”修饰名词“骑行”时应用“的”，即“长距离的骑行”。写成“长距离得骑行”，“得”用于动词或形容词之后引出补语，此处用错。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6006d7-9289-404a-bd33-5cf9c717080e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23472, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他长距离的骑车，很辛苦。", "corrected_sentence": "他长距离地骑车，很辛苦。", "error_description": "“长距离”作状语修饰动词“骑车”时，应写作“长距离地”，即“长距离地骑车”。写成“长距离的骑车”，“的”用于名词性修饰语，此处应用“地”，只需替换这一处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6006d7-9289-404a-bd33-5cf9c717080e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
