INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23478, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23478, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用地就是用来做某件事的土地。", "primary_collocate": null, "pronunciation": "yòng dì", "ipa": "jʊŋ˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "这块用地要建一所小学。", "target_word": "用地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "村里有一块用地，打算做运动场。", "target_word": "用地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园用地不能盖房子。", "target_word": "用地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们公司需要一块新的用地。", "target_word": "用地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片用地是用来种菜的。", "target_word": "用地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校旁边的用地准备建医院。", "target_word": "用地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想买一块用地盖房子。", "target_word": "用地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这里是工厂用地，不是住宅。", "target_word": "用地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块用地太小，放不下大楼。", "target_word": "用地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说这块用地将来会变成花园。", "target_word": "用地", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块用地", "label": "量词"}, {"form": "建设用地", "label": "复合"}, {"form": "工厂用地", "label": "复合"}, {"form": "公园用地", "label": "复合"}], "register": "通用", "sense_fingerprint": "准备用来做某件事的一块土地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36440c-1b9c-48b5-9e18-6c80bfba6e21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23478, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "用地", "is_correct": true, "explanation": "“用地”指准备用来做某件事的土地，与“要建一所小学”搭配，是正确答案。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：“蛋糕”是食物，不能用来建学校。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“建”的对象要是土地或建筑，不能说建面包。"}, {"text": "手表", "is_correct": false, "explanation": "语义：“手表”是小物件，不可能用来建一所小学。"}], "explanations": {"用地": "“用地”指准备用来做某件事的土地，与“要建一所小学”搭配，是正确答案。", "蛋糕": "语义：“蛋糕”是食物，不能用来建学校。", "面包": "搭配：“建”的对象要是土地或建筑，不能说建面包。", "手表": "语义：“手表”是小物件，不可能用来建一所小学。"}, "sentence_index": 0, "correct_answer": "用地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块用地很大，一家人在这里看电视。", "explanation": "这里应该用〈客厅〉。“用地”是规划用途的土地，不是室内空间，不能说在里面看电视的客厅。"}, {"text": "我们公司需要一把新的用地。", "explanation": "这里应该用〈块〉。“把”用于有柄的物品，用地要用“块”计量。"}, {"text": "这块用地的饭菜很便宜，学生们都爱来。", "explanation": "这里应该用〈食堂〉。“用地”指规划用途的土地，不卖饭菜；卖饭菜、供学生吃饭的地方要说食堂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23478, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用地", "is_correct": true, "explanation": "“用地”指用来做某件事的土地，与“盖房子”搭配，是正确答案。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：“饼干”是食品，不能用来盖房子。"}, {"text": "巧克力", "is_correct": false, "explanation": "语义：“巧克力”是食物，不是可以买来用于建房的东西。"}, {"text": "肥皂", "is_correct": false, "explanation": "搭配：“盖房子”要用土地或建筑材料，肥皂不能作为盖房的对象。"}], "explanations": {"用地": "“用地”指用来做某件事的土地，与“盖房子”搭配，是正确答案。", "饼干": "语义：“饼干”是食品，不能用来盖房子。", "巧克力": "语义：“巧克力”是食物，不是可以买来用于建房的东西。", "肥皂": "搭配：“盖房子”要用土地或建筑材料，肥皂不能作为盖房的对象。"}, "sentence_index": 6, "correct_answer": "用地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块用地有三百名学生，每天都很热闹。", "explanation": "这里应该用〈学校〉。“用地”是规划用途的土地，不能容纳学生上课；有学生上课、老师教学的地方要说学校。"}, {"text": "我们公司买了一本新的用地，准备盖厂房。", "explanation": "这里应该用〈块〉。“本”用于书籍，用地要用“块”计量。"}, {"text": "这只用地将来要建一所小学。", "explanation": "这里应该用〈块〉。“只”用于动物等，不用于土地，用地要用“块”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23478, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里划出一条用地，准备建小广场。", "corrected_sentence": "村里划出一块用地，准备建小广场。", "error_description": "量词错误：“用地”应用量词“块”，不用“条”（“条”用于线路、河流等狭长事物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23478, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校旁边有一块的用地，准备盖一栋宿舍楼。", "corrected_sentence": "学校旁边有一块用地，准备盖一栋宿舍楼。", "error_description": "语法错误：数量短语“一块”后不能加“的”来修饰“用地”，应说“一块用地”，去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aad1a85b-d2db-4bd2-bd96-a6c6691e89fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
