INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23484, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示事情发生的最开始、最底下的地方或原因。", "primary_collocate": null, "pronunciation": "cóng gēn běn shàng", "ipa": "tsʰʊŋ˧˥ kən˥˥ pən˨˩˦ ʂɑŋ˥˩", "syllable_count": 4, "sentences": [{"text": "我们要从根本上找出问题的原因。", "target_word": "从根本上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说，要从根本上查清这种病的来源。", "target_word": "从根本上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想从根本上弄明白事情是怎么发生的。", "target_word": "从根本上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从根本上找到了错误的来源。", "target_word": "从根本上", "complexity_tier": "T3", "furigana": "tā cóng gēn běn shàng zhǎo dào le cuò wù de lái yuán", "sentence_source": "generated"}, {"text": "警察正从根本上调查这起事故的原因。", "target_word": "从根本上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要治好这种病，必须从根本上找到病因。", "target_word": "从根本上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们从根本上了解这个词的来源。", "target_word": "从根本上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水总是脏，得从根本上看看管子哪里坏了。", "target_word": "从根本上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们得从根本上分析一下，这次失败的原因是什么。", "target_word": "从根本上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从根本上检查了机器，终于找到了毛病。", "target_word": "从根本上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "从根本上：回到事情最开始的地方或根源，去查找、了解原因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dc1047-0180-45c4-a535-02dddfb4af73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23484, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从根本上", "is_correct": true, "explanation": "正确：“从根本上”表示追溯到根源，与“找出问题的原因”的语境相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，不能用于有目的、系统地找原因。"}, {"text": "瞎", "is_correct": false, "explanation": "语域：“瞎”口语色彩强、带贬义，不适合正式的分析语境。"}, {"text": "随手", "is_correct": false, "explanation": "语义：“随手”指顺手、不费力，与认真追查原因的意图相反。"}], "explanations": {"从根本上": "正确：“从根本上”表示追溯到根源，与“找出问题的原因”的语境相符。", "偶尔": "语义：“偶尔”表示不常发生，不能用于有目的、系统地找原因。", "瞎": "语域：“瞎”口语色彩强、带贬义，不适合正式的分析语境。", "随手": "语义：“随手”指顺手、不费力，与认真追查原因的意图相反。"}, "sentence_index": 0, "correct_answer": "从根本上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从根本上到了北京。", "explanation": "这里应该用〈终于〉。从根本上指事物的根本层面，不能表示经过一段路程后最终到达某地。"}, {"text": "这盏灯从根本上亮了。", "explanation": "这里应该用〈突然〉。从根本上指事物的根本层面或原因，不能描写灯光骤然亮起。"}, {"text": "我们从根本上去公园。", "explanation": "这里应该用〈一起〉。从根本上表示追溯根源，不能表示一同行动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21c85038-5747-4c20-ac84-49a80cc56e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23484, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从根本上", "is_correct": true, "explanation": "正确：“从根本上”表示追溯根源，与“老师让我们了解这个词的来源”的语境相符。"}, {"text": "突然", "is_correct": false, "explanation": "搭配：“突然”表示出乎意料，不能修饰“让我们了解”这种有计划的安排。"}, {"text": "草草", "is_correct": false, "explanation": "语义：“草草”表示敷衍、匆忙，与老师希望学生深入了解的意图相反。"}, {"text": "偶然", "is_correct": false, "explanation": "语义：“偶然”表示碰巧，与老师有意组织的学习不符。"}], "explanations": {"从根本上": "正确：“从根本上”表示追溯根源，与“老师让我们了解这个词的来源”的语境相符。", "突然": "搭配：“突然”表示出乎意料，不能修饰“让我们了解”这种有计划的安排。", "草草": "语义：“草草”表示敷衍、匆忙，与老师希望学生深入了解的意图相反。", "偶然": "语义：“偶然”表示碰巧，与老师有意组织的学习不符。"}, "sentence_index": 6, "correct_answer": "从根本上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从根本上走回家。", "explanation": "这里应该用〈慢慢〉。从根本上指向根源，不能用来描写走路的速度。"}, {"text": "他从根本上摔倒了。", "explanation": "这里应该用〈当场〉。从根本上表示根本层面，不能描写摔倒当时的即时情况。"}, {"text": "我从根本上遇见了老同学。", "explanation": "这里应该用〈偶然〉。从根本上表示追溯根源，不能描写无意中遇到某人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21c85038-5747-4c20-ac84-49a80cc56e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23484, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工程师要从根本上被检查系统的故障。", "corrected_sentence": "工程师要从根本上检查系统的故障。", "error_description": "被字句错误：被动式动词“检查”后不能直接带宾语“系统的故障”。应去掉“被”，说“工程师要从根本上检查系统的故障”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21c85038-5747-4c20-ac84-49a80cc56e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23484, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们从根本上的理清了事故的经过。", "corrected_sentence": "我们从根本上理清了事故的经过。", "error_description": "“从根本上”是状语，后面不能加“的”直接修饰动词。应说“从根本上理清了事故的经过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21c85038-5747-4c20-ac84-49a80cc56e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
