INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23490, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用最少的时间做最多的事。", "primary_collocate": null, "pronunciation": "lì yòng xiào lǜ", "ipa": "li⁵¹ yʊŋ⁵¹ ɕiaʊ⁵¹ ly⁵¹", "syllable_count": 4, "sentences": [{"text": "我们要提高时间的利用效率。", "target_word": "利用效率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做作业很专心，时间的利用效率很高。", "target_word": "利用效率", "complexity_tier": "T3", "furigana": "lìyòng xiàolǜ", "sentence_source": "generated"}, {"text": "他每天列计划，学习时间的利用效率提高了不少。", "target_word": "利用效率", "complexity_tier": "T3", "furigana": "lìyòng xiàolǜ", "sentence_source": "generated"}, {"text": "他的工作时间很长，但利用效率很低。", "target_word": "利用效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎样提高课堂的利用效率。", "target_word": "利用效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机放在一边，复习时间的利用效率会更高。", "target_word": "利用效率", "complexity_tier": "T3", "furigana": "lìyòng xiàolǜ", "sentence_source": "generated"}, {"text": "开会太多，上班时间的利用效率很低。", "target_word": "利用效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学会列清单以后，他的时间利用效率高多了。", "target_word": "利用效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用手机提醒自己，午休时间的利用效率更高。", "target_word": "利用效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间的利用效率不高，所以他总是加班。", "target_word": "利用效率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "时间或资源被用得多有效的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f97476-a1c8-44d6-945d-bc65b062c339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23490, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "语义：“时间的体重”不成立，时间没有体重，不能作为提高的对象。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的外形特征，不能用来说“时间”的提高。"}, {"text": "利用效率", "is_correct": true, "explanation": "正确。“时间的利用效率”指用最少时间做最多事的程度，与“提高”搭配，符合句意。"}, {"text": "零钱", "is_correct": false, "explanation": "搭配：“零钱”是钱的一种，不能作为“时间”的修饰对象来提高。"}], "explanations": {"体重": "语义：“时间的体重”不成立，时间没有体重，不能作为提高的对象。", "身高": "体貌：“身高”是人的外形特征，不能用来说“时间”的提高。", "利用效率": "正确。“时间的利用效率”指用最少时间做最多事的程度，与“提高”搭配，符合句意。", "零钱": "搭配：“零钱”是钱的一种，不能作为“时间”的修饰对象来提高。"}, "sentence_index": 0, "correct_answer": "利用效率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭店的利用效率很好，客人都很满意。", "explanation": "这里应该用〈服务态度〉。利用效率说的是资源被用得是否高效，不指服务好坏，说服务态度好要用〈服务态度〉。"}, {"text": "昨晚他的利用效率很差，睡不着。", "explanation": "这里应该用〈睡眠质量〉。利用效率不描述睡眠的好坏，说睡得好不好要用〈睡眠质量〉。"}, {"text": "她最近利用效率变好了，比以前瘦多了。", "explanation": "这里应该用〈身材〉。利用效率不用来形容人的体形变化，说身材变化要用〈身材〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d296638-cb17-4ff8-a734-32b70dfda79d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
